    // Game States
    const STATES = {
        MENU: 'MENU',
        LEVEL_SELECT: 'LEVEL_SELECT',
        PLAYING: 'PLAYING',
        PAUSED: 'PAUSED',
        VICTORY: 'VICTORY',
        DEFEAT: 'DEFEAT',
        CUTSCENE: 'CUTSCENE'
    };
    let currentState = STATES.MENU;

    // Viewport & Scale Settings
    let width = 1200;
    let height = 675;
    let cameraX = 0;
    let cameraY = 0;

    function resizeCanvas() {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        const scale = canvas.height / 675;
        width = canvas.width / scale;
        height = 675;
    }
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    // Input Controller
    const keys = {
        left: false,
        right: false,
        up: false,
        down: false,
        crouch: false,
        shift: false,
        shiftPressedThisFrame: false,
        jump: false,
        jumpPressedThisFrame: false,
        interact: false,
        interactPressedThisFrame: false
    };

    function togglePause() {
        if (currentState === STATES.PLAYING) {
            currentState = STATES.PAUSED;
            pauseScreen.classList.remove('hidden');
            pauseScreen.classList.add('screen-active');
        } else if (currentState === STATES.PAUSED) {
            currentState = STATES.PLAYING;
            pauseScreen.classList.remove('screen-active');
            pauseScreen.classList.add('hidden');
        }
    }

    window.addEventListener('keydown', (e) => {
        if (achievementsModal && achievementsModal.open) return;
        initAudio();

        const isGameKey = [
            'KeyA', 'KeyD', 'KeyW', 'KeyS',
            'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown',
            'ControlLeft', 'ControlRight', 'KeyC', 'KeyE', 'Space',
            'ShiftLeft', 'ShiftRight',
            'Escape', 'KeyP'
        ].includes(e.code) || e.key === 'Control' || e.key === 'Shift';

        if (isGameKey) {
            e.preventDefault();
        }

        if (currentState === STATES.CUTSCENE) {
            if (cutsceneIntro21 && cutsceneIntro21.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishLevel21IntroCutscene();
                    return;
                }
            } else if (typeof cutsceneIntro41 !== 'undefined' && cutsceneIntro41 && cutsceneIntro41.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishLevel41IntroCutscene();
                    return;
                }
            } else if (typeof cutsceneIntro61 !== 'undefined' && cutsceneIntro61 && cutsceneIntro61.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishLevel61IntroCutscene();
                    return;
                }
            } else if (typeof cutsceneIntro81 !== 'undefined' && cutsceneIntro81 && cutsceneIntro81.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishLevel81IntroCutscene();
                    return;
                }
            } else if (typeof cutsceneIntro101 !== 'undefined' && cutsceneIntro101 && cutsceneIntro101.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishLevel101IntroCutscene();
                    return;
                }
            } else if (typeof golemCutscene !== 'undefined' && golemCutscene && golemCutscene.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishGolemDefeatCutscene();
                    return;
                }
            } else if (typeof golemIntroCutscene !== 'undefined' && golemIntroCutscene && golemIntroCutscene.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishGolemIntroCutscene();
                    return;
                }
            } else if (typeof yetiIntroCutscene !== 'undefined' && yetiIntroCutscene && yetiIntroCutscene.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishYetiIntroCutscene();
                    return;
                }
            } else if (typeof yetiDefeatCutscene !== 'undefined' && yetiDefeatCutscene && yetiDefeatCutscene.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishYetiDefeatCutscene();
                    return;
                }
            } else if (typeof mummyIntroCutscene !== 'undefined' && mummyIntroCutscene && mummyIntroCutscene.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishMummyIntroCutscene();
                    return;
                }
            } else if (typeof mummyDefeatCutscene !== 'undefined' && mummyDefeatCutscene && mummyDefeatCutscene.active) {
                if (e.code === 'Space' || e.code === 'Escape' || e.code === 'Enter') {
                    finishMummyDefeatCutscene();
                    return;
                }
            } else if (typeof samuraiIntroCutscene !== 'undefined' && samuraiIntroCutscene && samuraiIntroCutscene.active) {
                if (e.code === 'Space' || e.code === 'Enter') {
                    advanceSamuraiIntroCutscene();
                    return;
                } else if (e.code === 'Escape') {
                    finishSamuraiIntroCutscene();
                    return;
                }
            } else if (typeof samuraiDefeatCutscene !== 'undefined' && samuraiDefeatCutscene && samuraiDefeatCutscene.active) {
                if (e.code === 'Space' || e.code === 'Enter') {
                    advanceSamuraiDefeatCutscene();
                    return;
                } else if (e.code === 'Escape') {
                    finishSamuraiDefeatCutscene();
                    return;
                }
            }
        }

        if (currentState === STATES.LEVEL_SELECT || (levelSelectScreen && !levelSelectScreen.classList.contains('hidden'))) {
            if (e.code === 'ArrowRight') {
                if (currentSelectPage === 1) {
                    currentSelectPage = 2;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 2) {
                    currentSelectPage = 3;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 3) {
                    currentSelectPage = 4;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 4) {
                    currentSelectPage = 5;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 5) {
                    currentSelectPage = 6;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                }
            } else if (e.code === 'ArrowLeft') {
                if (currentSelectPage === 6) {
                    currentSelectPage = 5;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 5) {
                    currentSelectPage = 4;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 4) {
                    currentSelectPage = 3;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 3) {
                    currentSelectPage = 2;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                } else if (currentSelectPage === 2) {
                    currentSelectPage = 1;
                    playSound('jump');
                    generateLevelsGrid();
                    return;
                }
            }
        }

        if (e.code === 'Escape' || e.code === 'KeyP') {
            togglePause();
            return;
        }

        if (currentState === STATES.PAUSED) return;

        if (e.code === 'KeyA' || e.code === 'ArrowLeft') keys.left = true;
        if (e.code === 'KeyD' || e.code === 'ArrowRight') keys.right = true;
        if (e.code === 'KeyW' || e.code === 'ArrowUp') keys.up = true;
        if (e.code === 'KeyS' || e.code === 'ArrowDown') keys.down = true;
        if (e.code === 'ControlLeft' || e.code === 'ControlRight' || e.key === 'Control' || e.code === 'KeyC') keys.crouch = true;
        if (e.code === 'ShiftLeft' || e.code === 'ShiftRight' || e.key === 'Shift') {
            if (!keys.shift) keys.shiftPressedThisFrame = true;
            keys.shift = true;
        }
        if (e.code === 'KeyE' || e.code === 'KeyF') {
            if (!keys.interact) keys.interactPressedThisFrame = true;
            keys.interact = true;
            if (currentState === STATES.PLAYING && currentLevelIndex === 60 && typeof yeti !== 'undefined' && yeti.active && player.state !== 'DEFEAT') {
                playerThrowSnowball();
            } else if (currentState === STATES.PLAYING && currentLevelIndex === 80 && typeof mummy !== 'undefined' && mummy.active && player.state !== 'DEFEAT') {
                if (mummy.qteActive) {
                    handleMummyQteClick();
                } else {
                    playerPunch();
                }
            }
        }
        if (e.code === 'Space') {
            if (!keys.jump) keys.jumpPressedThisFrame = true;
            keys.jump = true;
            if (currentState === STATES.PLAYING && currentLevelIndex === 80 && typeof mummy !== 'undefined' && mummy.active && mummy.qteActive && player.state !== 'DEFEAT') {
                handleMummyQteClick();
            }
        }
        if (currentState === STATES.PLAYING && currentLevelIndex === 100 && typeof samuraiBoss !== 'undefined' && samuraiBoss.active && !samuraiBoss.isFallen && player.state !== 'DEFEAT') {
            if (e.code === 'Digit1' || e.key === '1') usePlayerSamuraiSkill(1);
            else if (e.code === 'Digit2' || e.key === '2') usePlayerSamuraiSkill(2);
            else if (e.code === 'Digit3' || e.key === '3') usePlayerSamuraiSkill(3);
            else if (e.code === 'Digit4' || e.key === '4') usePlayerSamuraiSkill(4);
        }
    });

    canvas.addEventListener('pointerdown', (e) => {
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        initAudio();
        if (currentState === STATES.PLAYING && player.state !== 'DEFEAT') {
            if (currentLevelIndex === 60 && typeof yeti !== 'undefined' && yeti.active) {
                playerThrowSnowball();
            } else if (currentLevelIndex === 80 && typeof mummy !== 'undefined' && mummy.active) {
                if (mummy.qteActive) {
                    handleMummyQteClick();
                } else {
                    playerPunch();
                }
            } else if (player.hasSamuraiOutfit || (currentLevelData && currentLevelData.theme === 'sakura') || (currentLevelIndex >= 81 && currentLevelIndex <= 100)) {
                playerKatanaSlash();
            } else {
                playerPunch();
            }
        }
    });

    window.addEventListener('keyup', (e) => {
        const isGameKey = [
            'KeyA', 'KeyD', 'KeyW', 'KeyS',
            'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown',
            'ControlLeft', 'ControlRight', 'KeyC', 'KeyE', 'KeyF', 'Space',
            'ShiftLeft', 'ShiftRight'
        ].includes(e.code) || e.key === 'Control' || e.key === 'Shift';

        if (isGameKey) {
            e.preventDefault();
        }

        if (e.code === 'KeyA' || e.code === 'ArrowLeft') keys.left = false;
        if (e.code === 'KeyD' || e.code === 'ArrowRight') keys.right = false;
        if (e.code === 'KeyW' || e.code === 'ArrowUp') keys.up = false;
        if (e.code === 'KeyS' || e.code === 'ArrowDown') keys.down = false;
        if (e.code === 'ControlLeft' || e.code === 'ControlRight' || e.key === 'Control' || e.code === 'KeyC') keys.crouch = false;
        if (e.code === 'ShiftLeft' || e.code === 'ShiftRight' || e.key === 'Shift') keys.shift = false;
        if (e.code === 'KeyE' || e.code === 'KeyF') keys.interact = false;
        if (e.code === 'Space') keys.jump = false;
    });

    // --- LEVELS DATABASE & PAGE PROGRESSION ---
    let unlockedPage1Levels = 20; // 1st Page: all 20 levels unlocked
    let unlockedPage2Levels = 40; // 2nd Page: levels 21 to 40 unlocked!
