    function updateCutsceneIntro41() {
        cutsceneIntro41.timer += 0.016;

        // Breath puffs emitting into cold air
        if (Math.random() < 0.12) {
            cutsceneIntro41.breathPuffs.push({
                x: player.x + player.facing * 12,
                y: player.y - 66,
                vx: player.facing * (1.1 + Math.random() * 1.4),
                vy: -(0.8 + Math.random() * 1.0),
                size: 3 + Math.random() * 3.5,
                alpha: 0.7,
                life: 0.9
            });
        }

        if (cutsceneIntro41.phase === 'WALK') {
            player.animTime += 0.14;
            player.x += player.vx;
            player.facing = 1;
            player.state = 'WALK';

            // Snow dust kicked up by footsteps
            if (Math.random() < 0.25) {
                particles.push({
                    x: player.x + (Math.random() - 0.5) * 8,
                    y: player.y,
                    vx: -player.facing * (0.8 + Math.random() * 1.2),
                    vy: -Math.random() * 1.5,
                    size: 2 + Math.random() * 3,
                    color: '#f8fafc',
                    life: 0.5,
                    decay: 0.03
                });
            }

            if (player.x >= 390) {
                player.x = 390;
                player.vx = 0;
                player.state = 'PICKUP_LIGHTER';
                cutsceneIntro41.phase = 'PICKUP';
                cutsceneIntro41.timer = 0;
                playSound('rustle');

                if (cutsceneText) cutsceneText.textContent = 'Стикмен наклоняется и находит на снегу металлическую зажигалку!';
            }
        } else if (cutsceneIntro41.phase === 'PICKUP') {
            player.state = 'PICKUP_LIGHTER';
            player.vx = 0;

            if (cutsceneIntro41.timer >= 1.8) {
                player.state = 'INSPECT_LIGHTER';
                cutsceneIntro41.phase = 'INSPECT';
                cutsceneIntro41.timer = 0;

                if (cutsceneText) cutsceneText.textContent = 'Она замёрзла в снегу, но механизм цел. Стикмен пробует проверить, работает ли она...';
            }
        } else if (cutsceneIntro41.phase === 'INSPECT') {
            player.state = 'INSPECT_LIGHTER';
            player.vx = 0;

            if (cutsceneIntro41.timer >= 1.8) {
                player.state = 'CLICK_LIGHTER';
                cutsceneIntro41.phase = 'FLICK';
                cutsceneIntro41.timer = 0;
                cutsceneIntro41.flameTimer = 0;

                playSound('lighterClick');

                // Burst of flint sparks!
                for (let s = 0; s < 14; s++) {
                    cutsceneIntro41.sparks.push({
                        x: player.x + player.facing * 16,
                        y: player.y - 54,
                        vx: (Math.random() - 0.3) * player.facing * 4,
                        vy: -Math.random() * 5 - 1,
                        size: 2 + Math.random() * 2.5,
                        color: Math.random() < 0.6 ? '#facc15' : '#f97316',
                        alpha: 1,
                        life: 0.5
                    });
                }

                setTimeout(() => {
                    playSound('lighterFlame');
                }, 120);

                if (cutsceneText) cutsceneText.textContent = 'Щёлк! Яркое пламя вырывается наружу! Зажигалка отлично работает!';
            }
        } else if (cutsceneIntro41.phase === 'FLICK') {
            player.state = 'CLICK_LIGHTER';
            player.vx = 0;
            cutsceneIntro41.flameTimer += 0.016;

            // Occasional tiny flame spark
            if (Math.random() < 0.2) {
                cutsceneIntro41.sparks.push({
                    x: player.x + player.facing * 16 + (Math.random() - 0.5) * 4,
                    y: player.y - 62,
                    vx: (Math.random() - 0.5) * 1.5,
                    vy: -Math.random() * 3 - 1,
                    size: 1.5 + Math.random() * 2,
                    color: Math.random() < 0.5 ? '#fde047' : '#ea580c',
                    alpha: 0.9,
                    life: 0.4
                });
            }

            if (cutsceneIntro41.timer >= 3.2) {
                cutsceneIntro41.phase = 'POCKET';
                cutsceneIntro41.timer = 0;
                player.state = 'IDLE';
                player.hasLighter = true;

                if (cutsceneText) cutsceneText.textContent = 'Зажигалка надёжно убрана в карман. Теперь можно исследовать Вечный холод!';
            }
        } else if (cutsceneIntro41.phase === 'POCKET') {
            player.state = 'IDLE';
            player.vx = 0;

            if (cutsceneIntro41.timer >= 1.6) {
                finishLevel41IntroCutscene();
            }
        }

        // Update sparks
        for (let i = cutsceneIntro41.sparks.length - 1; i >= 0; i--) {
            const sp = cutsceneIntro41.sparks[i];
            sp.x += sp.vx;
            sp.y += sp.vy;
            sp.vy += 0.12;
            sp.alpha -= 0.025;
            if (sp.alpha <= 0) cutsceneIntro41.sparks.splice(i, 1);
        }

        // Update breath puffs
        for (let i = cutsceneIntro41.breathPuffs.length - 1; i >= 0; i--) {
            const p = cutsceneIntro41.breathPuffs[i];
            p.x += p.vx;
            p.y += p.vy;
            p.size += 0.16;
            p.alpha -= 0.018;
            if (p.alpha <= 0) cutsceneIntro41.breathPuffs.splice(i, 1);
        }
    }

    function finishLevel41IntroCutscene() {
        if (!cutsceneIntro41.active) return;
        cutsceneIntro41.active = false;

        if (cutsceneOverlay) cutsceneOverlay.classList.add('hidden');
        if (hudOverlay) hudOverlay.classList.remove('hidden');

        player.state = 'IDLE';
        player.x = 440;
        player.y = currentLevelData.groundY;
        player.vx = 0;
        player.vy = 0;
        player.facing = 1;
        player.grounded = true;
        player.hasLighter = true;

        if (inventoryHud) {
            inventoryHud.classList.remove('hidden');
        }
        if (coldHud) {
            coldHud.classList.remove('hidden');
            updateColdHud();
        }

        cameraX = 0;
        cameraY = 0;

        currentState = STATES.PLAYING;
        playSound('natureStart');
    }

    // Helper: Draw lighter resting on the snow during WALK phase of cutscene
    function drawCutsceneLighter(scale) {
        if (!cutsceneIntro41.active) return;

        // Draw breath vapor puffs
        cutsceneIntro41.breathPuffs.forEach(p => {
            const px = (p.x - cameraX) * scale;
            const py = (p.y - cameraY) * scale;
            ctx.save();
            ctx.fillStyle = `rgba(241, 245, 249, ${p.alpha * 0.75})`;
            ctx.beginPath();
            ctx.arc(px, py, p.size * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });

        // Draw sparks
        cutsceneIntro41.sparks.forEach(sp => {
            const sx = (sp.x - cameraX) * scale;
            const sy = (sp.y - cameraY) * scale;
            ctx.save();
            ctx.shadowColor = sp.color;
            ctx.shadowBlur = 8 * scale;
            ctx.fillStyle = sp.color;
            ctx.beginPath();
            ctx.arc(sx, sy, sp.size * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });

        // If lighter still on the snow
        if (cutsceneIntro41.phase === 'WALK') {
            const lx = (cutsceneIntro41.lighterX - cameraX) * scale;
            const ly = (cutsceneIntro41.lighterY - cameraY) * scale;

            ctx.save();
            // Lighter shadow in snow
            ctx.fillStyle = 'rgba(15, 23, 42, 0.4)';
            ctx.beginPath();
            ctx.ellipse(lx + 4 * scale, ly + 2 * scale, 8 * scale, 3 * scale, 0, 0, Math.PI * 2);
            ctx.fill();

            // Shiny chrome body
            const bodyGrad = ctx.createLinearGradient(lx - 4 * scale, ly - 8 * scale, lx + 6 * scale, ly);
            bodyGrad.addColorStop(0, '#e2e8f0');
            bodyGrad.addColorStop(0.5, '#94a3b8');
            bodyGrad.addColorStop(1, '#475569');
            ctx.fillStyle = bodyGrad;
            ctx.fillRect(lx - 5 * scale, ly - 8 * scale, 10 * scale, 8 * scale);
            ctx.strokeStyle = '#0f172a';
            ctx.lineWidth = 1.5 * scale;
            ctx.strokeRect(lx - 5 * scale, ly - 8 * scale, 10 * scale, 8 * scale);

            // Brass wheel / flint cap
            ctx.fillStyle = '#f59e0b';
            ctx.fillRect(lx + 1 * scale, ly - 11 * scale, 4 * scale, 3 * scale);

            // Sparkling twinkle glint every 0.6s
            const twinkle = Math.sin(Date.now() * 0.008);
            if (twinkle > 0.4) {
                const alpha = (twinkle - 0.4) * 1.6;
                ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
                ctx.lineWidth = 1.8 * scale;
                ctx.beginPath();
                ctx.moveTo(lx, ly - 14 * scale);
                ctx.lineTo(lx, ly - 4 * scale);
                ctx.moveTo(lx - 5 * scale, ly - 9 * scale);
                ctx.lineTo(lx + 5 * scale, ly - 9 * scale);
                ctx.stroke();

                ctx.fillStyle = `rgba(254, 240, 138, ${alpha})`;
                ctx.beginPath();
                ctx.arc(lx, ly - 9 * scale, 2.5 * scale, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.restore();
        }
    }

    // ==========================================
    // --- LEVEL 61: DESERT INTRO CUTSCENE ---
    // ==========================================
    const cutsceneIntro61 = {
        active: false,
        phase: 'WALK_COLD',
        timer: 0,
        steamPuffs: [],
        breathPuffs: []
    };

    function startLevel61IntroCutscene() {
        currentState = STATES.CUTSCENE;
        cutsceneIntro61.active = true;
        cutsceneIntro61.phase = 'WALK_COLD';
        cutsceneIntro61.timer = 0;
        cutsceneIntro61.steamPuffs = [];
        cutsceneIntro61.breathPuffs = [];

        if (hudOverlay) hudOverlay.classList.add('hidden');
        if (inventoryHud) inventoryHud.classList.add('hidden');
        if (coldHud) coldHud.classList.add('hidden');
        if (healthHud) healthHud.classList.add('hidden');
        if (cutsceneOverlay) cutsceneOverlay.classList.remove('hidden');

        player.cold = 0;
        player.health = 100;
        player.maxHealth = 100;
        player.damageCooldown = 0;

        player.x = 100;
        player.y = 540;
        player.vx = 2.0;
        player.vy = 0;
        player.facing = 1;
        player.grounded = true;
        player.state = 'WALK';
        player.isBossMode = false;
        player.isCrouching = false;
        player.height = 76;

        cameraX = 0;
        cameraY = 0;

        playSound('coldWind');
        if (cutsceneChapter) cutsceneChapter.textContent = '🏜️ СТРАНИЦА 4: ИСОХШАЯ ЗЕМЛЯ';
        if (cutsceneText) cutsceneText.textContent = 'Стикмен оставляет позади морозные ледники... Прямо перед ним раскинулась знойная пустыня!';
    }

    function updateCutsceneIntro61() {
        cutsceneIntro61.timer += 0.016;

        if (cutsceneIntro61.phase === 'WALK_COLD') {
            player.animTime += 0.14;
            player.x += player.vx;
            player.facing = 1;
            player.state = 'WALK';

            // Cold breath puff
            if (Math.random() < 0.12) {
                cutsceneIntro61.breathPuffs.push({
                    x: player.x + player.facing * 12,
                    y: player.y - 66,
                    vx: player.facing * (1.1 + Math.random()),
                    vy: -(0.7 + Math.random() * 0.8),
                    size: 2.5 + Math.random() * 3,
                    alpha: 0.75,
                    life: 0.8
                });
            }

            // Snow dust kicked up by footsteps
            if (Math.random() < 0.25) {
                particles.push({
                    x: player.x + (Math.random() - 0.5) * 8,
                    y: player.y,
                    vx: -player.facing * (0.8 + Math.random()),
                    vy: -Math.random() * 1.5,
                    size: 2 + Math.random() * 2.5,
                    color: '#f8fafc',
                    life: 0.5,
                    decay: 0.03
                });
            }

            if (player.x >= 350) {
                player.x = 350;
                player.vx = 0;
                player.state = 'IDLE';
                cutsceneIntro61.phase = 'CONTEMPLATE';
                cutsceneIntro61.timer = 0;
                if (cutsceneText) cutsceneText.textContent = 'Перед ним две разные стороны: слева леденящий мороз, а справа — пылающий зной и пески!';
            }
        } else if (cutsceneIntro61.phase === 'CONTEMPLATE') {
            player.state = 'IDLE';
            player.vx = 0;

            if (Math.random() < 0.08) {
                cutsceneIntro61.breathPuffs.push({
                    x: player.x + player.facing * 12,
                    y: player.y - 66,
                    vx: player.facing * 1.0,
                    vy: -0.8,
                    size: 3,
                    alpha: 0.65,
                    life: 0.8
                });
            }

            if (cutsceneIntro61.timer >= 2.6) {
                cutsceneIntro61.phase = 'STEP_DESERT';
                cutsceneIntro61.timer = 0;
                player.vx = 1.9;
                player.state = 'WALK';
                if (cutsceneText) cutsceneText.textContent = 'Стикмен делает шаг и ступает в пустыню... Приятное тепло мгновенно охватывает его!';
            }
        } else if (cutsceneIntro61.phase === 'STEP_DESERT') {
            player.animTime += 0.13;
            player.x += player.vx;
            player.state = 'WALK';

            // Sand dust under footsteps
            if (Math.random() < 0.3) {
                particles.push({
                    x: player.x + (Math.random() - 0.5) * 8,
                    y: player.y,
                    vx: -player.facing * (0.8 + Math.random()),
                    vy: -Math.random() * 1.5,
                    size: 2 + Math.random() * 3,
                    color: '#f59e0b',
                    life: 0.5,
                    decay: 0.03
                });
            }

            if (player.x >= 490) {
                player.x = 490;
                player.vx = 0;
                player.state = 'IDLE';
                cutsceneIntro61.phase = 'THAW_STEAM';
                cutsceneIntro61.timer = 0;
                playSound('steamWarm');
                if (cutsceneText) cutsceneText.textContent = 'От согревшегося тела поднимается лёгкий пар. Холод отступил! Добро пожаловать в Исохшую землю!';
            }
        } else if (cutsceneIntro61.phase === 'THAW_STEAM') {
            player.state = 'IDLE';
            player.vx = 0;

            // Translucent rising steam puffs from body and arms
            if (Math.random() < 0.45) {
                cutsceneIntro61.steamPuffs.push({
                    x: player.x + (Math.random() - 0.5) * 24,
                    y: player.y - 15 - Math.random() * 55,
                    vx: (Math.random() - 0.5) * 0.8 + 0.3,
                    vy: -(1.3 + Math.random() * 1.4),
                    size: 3.5 + Math.random() * 4,
                    alpha: 0.85,
                    life: 1.2
                });
            }

            if (cutsceneIntro61.timer >= 3.2) {
                finishLevel61IntroCutscene();
            }
        }

        // Update steam puffs
        for (let i = cutsceneIntro61.steamPuffs.length - 1; i >= 0; i--) {
            const sp = cutsceneIntro61.steamPuffs[i];
            sp.x += sp.vx;
            sp.y += sp.vy;
            sp.size += 0.18;
            sp.alpha -= 0.016;
            if (sp.alpha <= 0) cutsceneIntro61.steamPuffs.splice(i, 1);
        }

        // Update breath puffs
        for (let i = cutsceneIntro61.breathPuffs.length - 1; i >= 0; i--) {
            const p = cutsceneIntro61.breathPuffs[i];
            p.x += p.vx;
            p.y += p.vy;
            p.size += 0.15;
            p.alpha -= 0.02;
            if (p.alpha <= 0) cutsceneIntro61.breathPuffs.splice(i, 1);
        }
    }

    function finishLevel61IntroCutscene() {
        if (!cutsceneIntro61.active) return;
        cutsceneIntro61.active = false;

        if (cutsceneOverlay) cutsceneOverlay.classList.add('hidden');
        if (hudOverlay) hudOverlay.classList.remove('hidden');

        player.state = 'IDLE';
        player.x = currentLevelData.playerStartX || 180;
        player.y = currentLevelData.groundY;
        player.vx = 0;
        player.vy = 0;
        player.facing = 1;
        player.grounded = true;
        player.health = 100;
        player.maxHealth = 100;
        player.damageCooldown = 0;

        if (inventoryHud) inventoryHud.classList.add('hidden');
        if (coldHud) coldHud.classList.add('hidden');
        if (healthHud) {
            healthHud.classList.remove('hidden');
            updateHealthHud();
        }

        cameraX = 0;
        cameraY = 0;

        currentState = STATES.PLAYING;
        playSound('natureStart');
    }

    function drawCutscene61Scene(scale) {
        if (!cutsceneIntro61.active) return;

        const borderWorldX = 420;
        const splitX = (borderWorldX - cameraX) * scale;
        const groundY = (540 - cameraY) * scale;

        // 1. Left Side: Snow Biome (Cold side: x < splitX)
        ctx.save();
        ctx.beginPath();
        ctx.rect(0, 0, splitX, canvas.height);
        ctx.clip();

        // Dark Twilight Winter Sky
        const winterSky = ctx.createLinearGradient(0, 0, 0, canvas.height);
        winterSky.addColorStop(0, '#0b1329');
        winterSky.addColorStop(0.4, '#1e293b');
        winterSky.addColorStop(0.75, '#334155');
        winterSky.addColorStop(1, '#64748b');
        ctx.fillStyle = winterSky;
        ctx.fillRect(0, 0, splitX, canvas.height);

        // Cold Winter Sun
        const coldSunX = 140 * scale;
        const coldSunY = 110 * scale;
        const cSunR = 36 * scale;
        const cSunGrad = ctx.createRadialGradient(coldSunX, coldSunY, 4 * scale, coldSunX, coldSunY, cSunR * 2.2);
        cSunGrad.addColorStop(0, '#ffffff');
        cSunGrad.addColorStop(0.35, 'rgba(224, 242, 254, 0.7)');
        cSunGrad.addColorStop(1, 'rgba(186, 230, 253, 0)');
        ctx.fillStyle = cSunGrad;
        ctx.beginPath();
        ctx.arc(coldSunX, coldSunY, cSunR * 2.2, 0, Math.PI * 2);
        ctx.fill();

        // Jagged Snow Mountain Silhouettes
        ctx.fillStyle = '#334155';
        ctx.beginPath();
        ctx.moveTo(0, canvas.height);
        ctx.lineTo(0, 310 * scale);
        ctx.lineTo(130 * scale, 170 * scale);
        ctx.lineTo(260 * scale, 310 * scale);
        ctx.lineTo(390 * scale, 210 * scale);
        ctx.lineTo(splitX, 290 * scale);
        ctx.lineTo(splitX, canvas.height);
        ctx.closePath();
        ctx.fill();

        // White snowcaps
        ctx.fillStyle = '#f8fafc';
        ctx.beginPath();
        ctx.moveTo(130 * scale, 170 * scale);
        ctx.lineTo(105 * scale, 215 * scale);
        ctx.lineTo(155 * scale, 215 * scale);
        ctx.closePath();
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(390 * scale, 210 * scale);
        ctx.lineTo(365 * scale, 250 * scale);
        ctx.lineTo(415 * scale, 250 * scale);
        ctx.closePath();
        ctx.fill();

        // Frozen Rock Ground Platform
        const rockGrad = ctx.createLinearGradient(0, groundY, 0, canvas.height);
        rockGrad.addColorStop(0, '#334155');
        rockGrad.addColorStop(0.4, '#1e293b');
        rockGrad.addColorStop(1, '#0f172a');
        ctx.fillStyle = rockGrad;
        ctx.fillRect(0, groundY, splitX, canvas.height - groundY);

        // Snow Blanket on surface
        ctx.fillStyle = '#f8fafc';
        ctx.fillRect(0, groundY, splitX, 12 * scale);
        ctx.fillStyle = '#bae6fd';
        for (let ix = 20 * scale; ix < splitX - 10 * scale; ix += 28 * scale) {
            ctx.beginPath();
            ctx.moveTo(ix - 3 * scale, groundY + 12 * scale);
            ctx.lineTo(ix, groundY + 24 * scale);
            ctx.lineTo(ix + 3 * scale, groundY + 12 * scale);
            ctx.fill();
        }

        // Falling Blizzard flakes on snow side
        drawSnowfall(scale);

        ctx.restore();

        // 2. Right Side: Desert Biome (Heat side: x >= splitX)
        ctx.save();
        ctx.beginPath();
        ctx.rect(splitX, 0, canvas.width - splitX, canvas.height);
        ctx.clip();

        // Blazing Radiant Desert Sky
        const desertSky = ctx.createLinearGradient(0, 0, 0, canvas.height);
        desertSky.addColorStop(0, '#c2410c'); // rich burnt orange
        desertSky.addColorStop(0.28, '#ea580c');
        desertSky.addColorStop(0.55, '#f59e0b');
        desertSky.addColorStop(0.82, '#fde047');
        desertSky.addColorStop(1, '#fef08a');
        ctx.fillStyle = desertSky;
        ctx.fillRect(splitX, 0, canvas.width - splitX, canvas.height);

        // Blazing Desert Sun with radiant corona
        const sunX = Math.max(splitX + 160 * scale, canvas.width - 180 * scale);
        const sunY = 120 * scale;
        const dSunR = 48 * scale;
        const dSunGrad = ctx.createRadialGradient(sunX, sunY, 6 * scale, sunX, sunY, dSunR * 2.8);
        dSunGrad.addColorStop(0, '#ffffff');
        dSunGrad.addColorStop(0.2, '#fef08a');
        dSunGrad.addColorStop(0.5, 'rgba(251, 191, 36, 0.45)');
        dSunGrad.addColorStop(1, 'rgba(245, 158, 11, 0)');
        ctx.fillStyle = dSunGrad;
        ctx.beginPath();
        ctx.arc(sunX, sunY, dSunR * 2.8, 0, Math.PI * 2);
        ctx.fill();

        // Sun Corona Rays
        ctx.strokeStyle = 'rgba(254, 240, 138, 0.35)';
        ctx.lineWidth = 2 * scale;
        for (let r = 0; r < 12; r++) {
            const ang = (r * Math.PI) / 6 + Date.now() * 0.0004;
            ctx.beginPath();
            ctx.moveTo(sunX + Math.cos(ang) * (dSunR + 4 * scale), sunY + Math.sin(ang) * (dSunR + 4 * scale));
            ctx.lineTo(sunX + Math.cos(ang) * (dSunR + 32 * scale), sunY + Math.sin(ang) * (dSunR + 32 * scale));
            ctx.stroke();
        }

        // Distant Sandstone Canyon Mesa Silhouettes
        ctx.fillStyle = '#b45309';
        ctx.beginPath();
        ctx.moveTo(splitX, canvas.height);
        ctx.lineTo(splitX, 320 * scale);
        ctx.lineTo(splitX + 120 * scale, 240 * scale);
        ctx.lineTo(splitX + 280 * scale, 240 * scale);
        ctx.lineTo(splitX + 340 * scale, 330 * scale);
        ctx.lineTo(splitX + 500 * scale, 220 * scale);
        ctx.lineTo(splitX + 660 * scale, 220 * scale);
        ctx.lineTo(canvas.width, 340 * scale);
        ctx.lineTo(canvas.width, canvas.height);
        ctx.closePath();
        ctx.fill();

        // Rolling Golden Sand Dunes
        ctx.fillStyle = '#d97706';
        ctx.beginPath();
        ctx.moveTo(splitX, canvas.height);
        ctx.quadraticCurveTo(splitX + 160 * scale, 340 * scale, splitX + 340 * scale, 420 * scale);
        ctx.quadraticCurveTo(splitX + 520 * scale, 360 * scale, canvas.width, 410 * scale);
        ctx.lineTo(canvas.width, canvas.height);
        ctx.closePath();
        ctx.fill();

        // Distant Saguaro Cactus in the sand
        ctx.fillStyle = '#15803d';
        const dcX = splitX + 220 * scale;
        const dcY = groundY;
        ctx.fillRect(dcX - 4 * scale, dcY - 45 * scale, 8 * scale, 45 * scale);
        ctx.fillRect(dcX - 14 * scale, dcY - 32 * scale, 10 * scale, 5 * scale);
        ctx.fillRect(dcX - 14 * scale, dcY - 44 * scale, 5 * scale, 16 * scale);
        ctx.fillRect(dcX + 4 * scale, dcY - 26 * scale, 12 * scale, 5 * scale);
        ctx.fillRect(dcX + 11 * scale, dcY - 38 * scale, 5 * scale, 16 * scale);

        // Desert Golden Sand Ground Platform
        const sandGrad = ctx.createLinearGradient(0, groundY, 0, canvas.height);
        sandGrad.addColorStop(0, '#d97706');
        sandGrad.addColorStop(0.3, '#b45309');
        sandGrad.addColorStop(1, '#78350f');
        ctx.fillStyle = sandGrad;
        ctx.fillRect(splitX, groundY, canvas.width - splitX, canvas.height - groundY);

        // Golden sand dune crest & ripples
        ctx.fillStyle = '#f59e0b';
        ctx.fillRect(splitX, groundY, canvas.width - splitX, 10 * scale);
        ctx.fillStyle = '#fde047';
        ctx.fillRect(splitX, groundY, canvas.width - splitX, 3.5 * scale);

        // Ambient Drifting Sand Particles
        drawAmbientSand(scale);

        ctx.restore();

        // 3. Contrast Dividing Border Line (where cold meets heat)
        ctx.save();
        const seamGrad = ctx.createLinearGradient(splitX - 6 * scale, groundY - 140 * scale, splitX + 6 * scale, groundY + 60 * scale);
        seamGrad.addColorStop(0, 'rgba(186, 230, 253, 0.7)');
        seamGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.95)');
        seamGrad.addColorStop(1, 'rgba(251, 191, 36, 0.85)');
        ctx.strokeStyle = seamGrad;
        ctx.lineWidth = 3 * scale;
        ctx.beginPath();
        ctx.moveTo(splitX, 0);
        ctx.lineTo(splitX, canvas.height);
        ctx.stroke();

        // Melting Water Droplets at the Seam
        ctx.fillStyle = 'rgba(224, 242, 254, 0.85)';
        for (let dy = groundY; dy < groundY + 40 * scale; dy += 10 * scale) {
            ctx.beginPath();
            ctx.arc(splitX, dy, 2.5 * scale, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();

        // 4. Draw Breath Puffs (cold side)
        cutsceneIntro61.breathPuffs.forEach(p => {
            const px = (p.x - cameraX) * scale;
            const py = (p.y - cameraY) * scale;
            ctx.save();
            ctx.fillStyle = `rgba(241, 245, 249, ${p.alpha * 0.75})`;
            ctx.beginPath();
            ctx.arc(px, py, p.size * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });

        // 5. Draw Thawing Steam Puffs (rising from stickman in desert)
        cutsceneIntro61.steamPuffs.forEach(sp => {
            const sx = (sp.x - cameraX) * scale;
            const sy = (sp.y - cameraY) * scale;
            ctx.save();
            const sGrad = ctx.createRadialGradient(sx, sy, 0, sx, sy, sp.size * scale);
            sGrad.addColorStop(0, `rgba(254, 243, 199, ${sp.alpha * 0.8})`);
            sGrad.addColorStop(0.5, `rgba(248, 250, 252, ${sp.alpha * 0.5})`);
            sGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');
            ctx.fillStyle = sGrad;
            ctx.beginPath();
            ctx.arc(sx, sy, sp.size * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });
    }

    // ==========================================
    // --- DESERT RENDERING: BUILDINGS, LADDERS, CACTI & SAND ---
    // ==========================================
    const ambientSand = [];
    for (let i = 0; i < 75; i++) {
        ambientSand.push({
            x: Math.random() * 2600,
            y: Math.random() * 650,
            vx: 1.8 + Math.random() * 2.5,
            vy: (Math.random() - 0.4) * 0.8,
            size: 1.2 + Math.random() * 2.2,
            alpha: 0.25 + Math.random() * 0.5,
            color: Math.random() < 0.6 ? '#f59e0b' : '#fde047'
        });
    }

    function updateAmbientSand() {
        const scale = canvas.height / 675 || 1;
        const viewW = canvas.width / scale;
        ambientSand.forEach(grain => {
            grain.x += grain.vx;
            grain.y += grain.vy;
            if (grain.x > cameraX + viewW + 100) {
                grain.x = cameraX - 100;
                grain.y = Math.random() * 580;
            }
            if (grain.y > 600) {
                grain.y = Math.random() * 400;
            }
        });
    }

    function drawAmbientSand(scale) {
        ambientSand.forEach(grain => {
            const gx = (grain.x - cameraX) * scale;
            const gy = (grain.y - cameraY) * scale;
            if (gx < -30 || gx > canvas.width + 30) return;

            ctx.save();
            ctx.fillStyle = grain.color;
            ctx.globalAlpha = grain.alpha;
            ctx.beginPath();
            ctx.arc(gx, gy, grain.size * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });
    }

    function drawDesertBuilding(box, scale) {
        const drawX = (box.x - cameraX) * scale;
        const drawY = (box.y - cameraY) * scale;
        const drawW = box.w * scale;
        const drawH = box.h * scale;

        ctx.save();
        // Main sandstone body gradient (warm yellowish-orange tones)
        const bGrad = ctx.createLinearGradient(drawX, drawY, drawX + drawW, drawY + drawH);
        bGrad.addColorStop(0, '#d97706'); // warm golden amber sandstone
        bGrad.addColorStop(0.45, '#b45309');
        bGrad.addColorStop(1, '#78350f');
        ctx.fillStyle = bGrad;
        ctx.fillRect(drawX, drawY, drawW, drawH);

        // Sandstone Ashlar Block Courses (horizontal mortar lines)
        ctx.strokeStyle = 'rgba(69, 26, 3, 0.4)';
        ctx.lineWidth = 2 * scale;
        const rowHeight = 26;
        let rIndex = 0;
        for (let by = box.y; by < box.y + box.h; by += rowHeight) {
            const screenBy = (by - cameraY) * scale;
            ctx.beginPath();
            ctx.moveTo(drawX, screenBy);
            ctx.lineTo(drawX + drawW, screenBy);
            ctx.stroke();

            // Alternating vertical brick lines
            const colWidth = 48;
            const shift = (rIndex % 2) * (colWidth / 2);
            for (let bx = box.x + shift; bx < box.x + box.w; bx += colWidth) {
                const screenBx = (bx - cameraX) * scale;
                ctx.beginPath();
                ctx.moveTo(screenBx, screenBy);
                ctx.lineTo(screenBx, Math.min(drawY + drawH, screenBy + rowHeight * scale));
                ctx.stroke();
            }
            rIndex++;
        }

        // Rooftop Sandstone Coping / Parapet Trim
        const topH = 8 * scale;
        ctx.fillStyle = '#f59e0b';
        ctx.fillRect(drawX - 2 * scale, drawY - 2 * scale, drawW + 4 * scale, topH);
        ctx.fillStyle = '#fef08a';
        ctx.fillRect(drawX - 2 * scale, drawY - 2 * scale, drawW + 4 * scale, 2.5 * scale);

        // Decorative Roof Crenellations along the top edge
        const crenW = 20 * scale;
        const crenH = 10 * scale;
        ctx.fillStyle = '#f59e0b';
        for (let cx = drawX + 4 * scale; cx < drawX + drawW - crenW; cx += crenW * 2) {
            ctx.fillRect(cx, drawY - crenH, crenW, crenH);
            ctx.strokeStyle = 'rgba(69, 26, 3, 0.5)';
            ctx.lineWidth = 1.5 * scale;
            ctx.strokeRect(cx, drawY - crenH, crenW, crenH);
        }

        // Projecting Wooden Beams (Vigas) below the roofline
        const vigaStep = 38 * scale;
        for (let vx = drawX + 16 * scale; vx < drawX + drawW - 14 * scale; vx += vigaStep) {
            const vy = drawY + 18 * scale;
            ctx.fillStyle = '#451a03';
            ctx.beginPath();
            ctx.arc(vx, vy, 4.5 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#78350f';
            ctx.beginPath();
            ctx.arc(vx - 1 * scale, vy - 1 * scale, 3 * scale, 0, Math.PI * 2);
            ctx.fill();
        }

        // Sandstone Arched Doorways or Windows
        if (box.h >= 160) {
            // Upper Window
            const winX = drawX + drawW / 2;
            const winY = drawY + 44 * scale;
            const winW = 18 * scale;
            const winH = 28 * scale;
            ctx.fillStyle = '#1e1005';
            ctx.beginPath();
            ctx.arc(winX, winY, winW / 2, Math.PI, 0);
            ctx.rect(winX - winW / 2, winY, winW, winH);
            ctx.fill();
            ctx.strokeStyle = '#f59e0b';
            ctx.lineWidth = 2 * scale;
            ctx.stroke();
        }
        if (box.h >= 240) {
            // Second lower window
            const win2X = drawX + drawW / 2;
            const win2Y = drawY + 120 * scale;
            const winW = 22 * scale;
            const winH = 34 * scale;
            ctx.fillStyle = '#1c0f05';
            ctx.beginPath();
            ctx.arc(win2X, win2Y, winW / 2, Math.PI, 0);
            ctx.rect(win2X - winW / 2, win2Y, winW, winH);
            ctx.fill();
            ctx.strokeStyle = '#d97706';
            ctx.lineWidth = 2 * scale;
            ctx.stroke();
        }

        // Archway Gate (crawl-through tunnel underneath, e.g. when y < 0 and tall)
        if (box.y < 0) {
            const archW = 120 * scale;
            const archH = 100 * scale;
            const archX = drawX + (drawW - archW) / 2;
            const archBaseY = (540 - cameraY) * scale;
            ctx.fillStyle = '#1a0b03';
            ctx.beginPath();
            ctx.arc(archX + archW / 2, archBaseY - archH + archW / 2, archW / 2, Math.PI, 0);
            ctx.rect(archX, archBaseY - archH + archW / 2, archW, archH - archW / 2);
            ctx.fill();
            ctx.strokeStyle = '#f59e0b';
            ctx.lineWidth = 3 * scale;
            ctx.stroke();
        }

        // Outer building outline
        ctx.strokeStyle = '#92400e';
        ctx.lineWidth = 2.5 * scale;
        ctx.strokeRect(drawX, drawY, drawW, drawH);

        // Sand drift at the building base
        ctx.fillStyle = '#f59e0b';
        ctx.beginPath();
        ctx.moveTo(drawX - 8 * scale, drawY + drawH);
        ctx.quadraticCurveTo(drawX + drawW * 0.25, drawY + drawH - 10 * scale, drawX + drawW * 0.5, drawY + drawH - 4 * scale);
        ctx.quadraticCurveTo(drawX + drawW * 0.75, drawY + drawH - 12 * scale, drawX + drawW + 8 * scale, drawY + drawH);
        ctx.closePath();
        ctx.fill();

        ctx.restore();
    }

    function drawDesertLadder(lad, scale) {
        const drawX = (lad.x - cameraX) * scale;
        const drawTopY = (lad.topY - cameraY) * scale;
        const drawBotY = (lad.bottomY - cameraY) * scale;
        const drawW = (lad.w || 38) * scale;

        const leftX = drawX - drawW / 2;
        const rightX = drawX + drawW / 2;

        ctx.save();
        // Vertical Desert Timber Beams
        ctx.strokeStyle = '#78350f';
        ctx.lineWidth = 4.5 * scale;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(leftX, drawTopY - 4 * scale);
        ctx.lineTo(leftX, drawBotY);
        ctx.moveTo(rightX, drawTopY - 4 * scale);
        ctx.lineTo(rightX, drawBotY);
        ctx.stroke();

        // Iron Mounting Brackets on Wall
        const bStep = 80;
        for (let by = lad.topY + 20; by < lad.bottomY; by += bStep) {
            const screenBy = (by - cameraY) * scale;
            ctx.fillStyle = '#334155';
            ctx.fillRect(leftX - 6 * scale, screenBy - 3 * scale, 5 * scale, 6 * scale);
            ctx.fillRect(rightX + 1 * scale, screenBy - 3 * scale, 5 * scale, 6 * scale);
        }

        // Wooden Rungs
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 3.5 * scale;
        const rungStep = 22;
        for (let rY = lad.topY + 12; rY <= lad.bottomY - 8; rY += rungStep) {
            const rungScreenY = (rY - cameraY) * scale;
            ctx.beginPath();
            ctx.moveTo(leftX + 2 * scale, rungScreenY);
            ctx.lineTo(rightX - 2 * scale, rungScreenY);
            ctx.stroke();

            // Iron nail on rungs
            ctx.fillStyle = '#1e293b';
            ctx.beginPath();
            ctx.arc(leftX + 4 * scale, rungScreenY, 1.8 * scale, 0, Math.PI * 2);
            ctx.arc(rightX - 4 * scale, rungScreenY, 1.8 * scale, 0, Math.PI * 2);
            ctx.fill();
        }

        // Top Finials
        ctx.fillStyle = '#b45309';
        ctx.beginPath();
        ctx.arc(leftX, drawTopY - 4 * scale, 4 * scale, 0, Math.PI * 2);
        ctx.arc(rightX, drawTopY - 4 * scale, 4 * scale, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }

    function drawDesertCactus(cactus, scale) {
        const drawX = (cactus.x - cameraX) * scale;
        const drawY = (cactus.y - cameraY) * scale;
        const drawW = cactus.w * scale;
        const drawH = cactus.h * scale;

        ctx.save();
        // Soft sand shadow under cactus
        ctx.fillStyle = 'rgba(120, 53, 15, 0.45)';
        ctx.beginPath();
        ctx.ellipse(drawX, drawY + 2 * scale, drawW * 0.7, 5 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // Main Trunk Column
        const trunkW = drawW * 0.42;
        const trunkX = drawX - trunkW / 2;
        const trunkH = drawH;

        const cGrad = ctx.createLinearGradient(trunkX, drawY - trunkH, trunkX + trunkW, drawY);
        cGrad.addColorStop(0, '#22c55e'); // sunlit green
        cGrad.addColorStop(0.4, '#16a34a');
        cGrad.addColorStop(0.85, '#15803d');
        cGrad.addColorStop(1, '#14532d'); // shaded green

        // Draw Main Trunk
        ctx.fillStyle = cGrad;
        ctx.beginPath();
        ctx.arc(drawX, drawY - trunkH + trunkW / 2, trunkW / 2, Math.PI, 0);
        ctx.rect(trunkX, drawY - trunkH + trunkW / 2, trunkW, trunkH - trunkW / 2);
        ctx.fill();

        // Saguaro Arms (if height >= 60)
        const armW = trunkW * 0.8;
        if (cactus.h >= 60) {
            // Left arm
            const leftArmY = drawY - trunkH * 0.55;
            const leftArmLen = drawW * 0.45;
            const leftArmUp = trunkH * 0.4;

            ctx.fillStyle = cGrad;
            ctx.beginPath();
            ctx.rect(drawX - trunkW / 2 - leftArmLen, leftArmY, leftArmLen + 2 * scale, armW);
            ctx.rect(drawX - trunkW / 2 - leftArmLen, leftArmY - leftArmUp + armW / 2, armW, leftArmUp);
            ctx.arc(drawX - trunkW / 2 - leftArmLen + armW / 2, leftArmY - leftArmUp + armW / 2, armW / 2, Math.PI, 0);
            ctx.fill();

            // Right arm (for taller cacti)
            if (cactus.h >= 75) {
                const rightArmY = drawY - trunkH * 0.45;
                const rightArmLen = drawW * 0.48;
                const rightArmUp = trunkH * 0.45;

                ctx.fillStyle = cGrad;
                ctx.beginPath();
                ctx.rect(drawX + trunkW / 2 - 2 * scale, rightArmY, rightArmLen + 2 * scale, armW);
                ctx.rect(drawX + trunkW / 2 + rightArmLen - armW, rightArmY - rightArmUp + armW / 2, armW, rightArmUp);
                ctx.arc(drawX + trunkW / 2 + rightArmLen - armW / 2, rightArmY - rightArmUp + armW / 2, armW / 2, Math.PI, 0);
                ctx.fill();
            }
        }

        // Vertical Rib Striations
        ctx.strokeStyle = 'rgba(20, 83, 45, 0.45)';
        ctx.lineWidth = 1.5 * scale;
        const ribCount = 3;
        for (let r = 1; r <= ribCount; r++) {
            const rx = trunkX + (trunkW / (ribCount + 1)) * r;
            ctx.beginPath();
            ctx.moveTo(rx, drawY - trunkH + trunkW * 0.4);
            ctx.lineTo(rx, drawY);
            ctx.stroke();
        }

        // Sharp Needles / Spines along edges
        ctx.strokeStyle = '#fef08a';
        ctx.lineWidth = 1.5 * scale;
        const spineStep = 14 * scale;
        for (let sy = drawY - trunkH + 12 * scale; sy < drawY - 6 * scale; sy += spineStep) {
            // Left spine
            ctx.beginPath();
            ctx.moveTo(trunkX, sy);
            ctx.lineTo(trunkX - 6 * scale, sy - 3 * scale);
            ctx.moveTo(trunkX, sy);
            ctx.lineTo(trunkX - 6 * scale, sy + 3 * scale);
            // Right spine
            ctx.moveTo(trunkX + trunkW, sy);
            ctx.lineTo(trunkX + trunkW + 6 * scale, sy - 3 * scale);
            ctx.moveTo(trunkX + trunkW, sy);
            ctx.lineTo(trunkX + trunkW + 6 * scale, sy + 3 * scale);
            ctx.stroke();
        }

        // Vibrant Pink/Magenta Desert Blossom on select cacti
        if (cactus.hasFlower || (cactus.h >= 70 && !cactus.isSmall)) {
            const flX = drawX;
            const flY = drawY - trunkH;
            ctx.fillStyle = '#ec4899'; // desert rose magenta
            for (let a = 0; a < Math.PI * 2; a += Math.PI / 3) {
                ctx.beginPath();
                ctx.ellipse(flX + Math.cos(a) * 4 * scale, flY + Math.sin(a) * 4 * scale, 4 * scale, 2 * scale, a, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.fillStyle = '#fde047';
            ctx.beginPath();
            ctx.arc(flX, flY, 2.5 * scale, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();
    }

    function drawDesertFlag(flag, scale) {
        const flagX = (flag.x - cameraX) * scale;
        const flagY = (flag.y - cameraY) * scale;
        const poleH = (flag.poleHeight || 110) * scale;
        const bannerW = (flag.bannerW || 45) * scale;
        const bannerH = (flag.bannerH || 30) * scale;

        ctx.save();
        // Brass Pole
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 5 * scale;
        ctx.beginPath();
        ctx.moveTo(flagX, flagY);
        ctx.lineTo(flagX, flagY - poleH);
        ctx.stroke();

        // Golden Sun Finial on top
        ctx.fillStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(flagX, flagY - poleH, 7 * scale, 0, Math.PI * 2);
        ctx.fill();
        // Sun rays
        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 2 * scale;
        for (let r = 0; r < 8; r++) {
            const ang = (r * Math.PI) / 4;
            ctx.beginPath();
            ctx.moveTo(flagX + Math.cos(ang) * 8 * scale, flagY - poleH + Math.sin(ang) * 8 * scale);
            ctx.lineTo(flagX + Math.cos(ang) * 13 * scale, flagY - poleH + Math.sin(ang) * 13 * scale);
            ctx.stroke();
        }

        // Silk Banner fluttering in desert wind
        const wave = Math.sin(Date.now() * 0.006) * 5 * scale;
        const topY = flagY - poleH + 8 * scale;

        const fGrad = ctx.createLinearGradient(flagX, topY, flagX + bannerW, topY);
        fGrad.addColorStop(0, '#dc2626'); // rich desert crimson
        fGrad.addColorStop(0.5, '#ea580c');
        fGrad.addColorStop(1, '#f59e0b'); // golden edge

        ctx.fillStyle = fGrad;
        ctx.beginPath();
        ctx.moveTo(flagX, topY);
        ctx.quadraticCurveTo(flagX + bannerW * 0.5, topY + wave, flagX + bannerW, topY + wave / 2);
        ctx.lineTo(flagX + bannerW, topY + bannerH + wave / 2);
        ctx.quadraticCurveTo(flagX + bannerW * 0.5, topY + bannerH + wave, flagX, topY + bannerH);
        ctx.closePath();
        ctx.fill();

        // Golden Sun Emblem on banner
        ctx.fillStyle = '#fef08a';
        ctx.font = `bold ${16 * scale}px sans-serif`;
        ctx.fillText('☀️', flagX + 10 * scale, topY + bannerH * 0.7 + wave / 2);

        ctx.restore();
    }

    function drawDesertWell(well, scale) {
        const drawX = (well.x - cameraX) * scale;
        const drawY = (well.y - cameraY) * scale;
        const drawW = (well.w || 96) * scale;
        const drawH = (well.h || 110) * scale;
        const halfW = drawW / 2;

        ctx.save();

        // 1. Damp sand / stone foundation shadow
        ctx.fillStyle = 'rgba(67, 20, 7, 0.45)';
        ctx.beginPath();
        ctx.ellipse(drawX, drawY + 2 * scale, halfW * 1.15, 12 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // 2. Stone Curb Basin (Cylindrical sandstone masonry)
        const basinH = 46 * scale;
        const basinY = drawY - basinH;

        // Outer circular stone wall gradient
        const curbGrad = ctx.createLinearGradient(drawX - halfW, 0, drawX + halfW, 0);
        curbGrad.addColorStop(0, '#78350f');
        curbGrad.addColorStop(0.2, '#b45309');
        curbGrad.addColorStop(0.5, '#d97706');
        curbGrad.addColorStop(0.8, '#b45309');
        curbGrad.addColorStop(1, '#451a03');
        ctx.fillStyle = curbGrad;
        ctx.beginPath();
        ctx.roundRect(drawX - halfW, basinY, drawW, basinH, 6 * scale);
        ctx.fill();

        // Stone ashlar seams on well basin
        ctx.strokeStyle = 'rgba(69, 26, 3, 0.45)';
        ctx.lineWidth = 1.8 * scale;
        // Horizontal stone courses
        ctx.beginPath();
        ctx.moveTo(drawX - halfW + 4 * scale, basinY + basinH * 0.33);
        ctx.lineTo(drawX + halfW - 4 * scale, basinY + basinH * 0.33);
        ctx.moveTo(drawX - halfW + 4 * scale, basinY + basinH * 0.66);
        ctx.lineTo(drawX + halfW - 4 * scale, basinY + basinH * 0.66);
        ctx.stroke();

        // Vertical block seams
        ctx.beginPath();
        ctx.moveTo(drawX - halfW * 0.4, basinY);
        ctx.lineTo(drawX - halfW * 0.4, basinY + basinH * 0.33);
        ctx.moveTo(drawX + halfW * 0.3, basinY);
        ctx.lineTo(drawX + halfW * 0.3, basinY + basinH * 0.33);
        ctx.moveTo(drawX, basinY + basinH * 0.33);
        ctx.lineTo(drawX, basinY + basinH * 0.66);
        ctx.moveTo(drawX - halfW * 0.5, basinY + basinH * 0.66);
        ctx.lineTo(drawX - halfW * 0.5, basinY + basinH);
        ctx.moveTo(drawX + halfW * 0.4, basinY + basinH * 0.66);
        ctx.lineTo(drawX + halfW * 0.4, basinY + basinH);
        ctx.stroke();

        // Basin Top Rim (lip)
        ctx.fillStyle = '#f59e0b';
        ctx.beginPath();
        ctx.ellipse(drawX, basinY, halfW, 11 * scale, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#78350f';
        ctx.lineWidth = 2 * scale;
        ctx.stroke();

        // Deep interior opening showing dark depth and cool blue shimmering water
        ctx.fillStyle = '#0f172a';
        ctx.beginPath();
        ctx.ellipse(drawX, basinY, halfW * 0.72, 7.5 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // Shimmering Turquoise Water Surface inside the well
        const waterPulse = Math.sin(Date.now() * 0.004) * 1.5 * scale;
        const waterGrad = ctx.createRadialGradient(drawX, basinY, 2 * scale, drawX, basinY, halfW * 0.7);
        waterGrad.addColorStop(0, '#67e8f9');
        waterGrad.addColorStop(0.4, '#06b6d4');
        waterGrad.addColorStop(0.8, '#0369a1');
        waterGrad.addColorStop(1, '#082f49');
        ctx.fillStyle = waterGrad;
        ctx.beginPath();
        ctx.ellipse(drawX, basinY + 1 * scale, halfW * 0.68 + waterPulse, 6.5 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // 3. Wooden Support Pillars
        const postW = 9 * scale;
        const postLeftX = drawX - halfW * 0.78;
        const postRightX = drawX + halfW * 0.78 - postW;
        const roofY = drawY - drawH;
        const roofH = 26 * scale;

        ctx.fillStyle = '#78350f';
        // Left pillar
        ctx.fillRect(postLeftX, roofY + roofH * 0.5, postW, basinY - roofY);
        // Right pillar
        ctx.fillRect(postRightX, roofY + roofH * 0.5, postW, basinY - roofY);

        // Pillar iron brackets
        ctx.fillStyle = '#334155';
        ctx.fillRect(postLeftX - 2 * scale, basinY - 8 * scale, postW + 4 * scale, 5 * scale);
        ctx.fillRect(postRightX - 2 * scale, basinY - 8 * scale, postW + 4 * scale, 5 * scale);

        // 4. Wooden Winch Spindle / Cylinder & Rope
        const spindleY = roofY + (basinY - roofY) * 0.42;
        const spindleW = postRightX - (postLeftX + postW);
        const spindleH = 14 * scale;

        // Wooden cross spindle
        ctx.fillStyle = '#b45309';
        ctx.fillRect(postLeftX + postW, spindleY - spindleH / 2, spindleW, spindleH);

        // Wound hemp rope coils
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 2.5 * scale;
        for (let rx = postLeftX + postW + 6 * scale; rx < postRightX - 6 * scale; rx += 4.5 * scale) {
            ctx.beginPath();
            ctx.moveTo(rx, spindleY - spindleH / 2);
            ctx.lineTo(rx, spindleY + spindleH / 2);
            ctx.stroke();
        }

        // Iron Crank Handle on the right
        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 3.5 * scale;
        ctx.beginPath();
        ctx.moveTo(postRightX + postW, spindleY);
        ctx.lineTo(postRightX + postW + 12 * scale, spindleY);
        ctx.lineTo(postRightX + postW + 12 * scale, spindleY + 14 * scale);
        ctx.stroke();
        ctx.fillStyle = '#94a3b8';
        ctx.beginPath();
        ctx.arc(postRightX + postW + 12 * scale, spindleY + 14 * scale, 3.5 * scale, 0, Math.PI * 2);
        ctx.fill();

        // Hanging Rope descending into well
        ctx.strokeStyle = '#b45309';
        ctx.lineWidth = 2.5 * scale;
        ctx.beginPath();
        ctx.moveTo(drawX, spindleY + spindleH / 2);
        const bucketDropY = basinY - 6 * scale;
        ctx.lineTo(drawX, bucketDropY - 14 * scale);
        ctx.stroke();

        // 5. Wooden Water Bucket dangling above the water
        const bucketX = drawX;
        const bucketY = bucketDropY;
        const bW = 16 * scale;
        const bH = 18 * scale;

        // Bucket metal handle
        ctx.strokeStyle = '#64748b';
        ctx.lineWidth = 2 * scale;
        ctx.beginPath();
        ctx.arc(bucketX, bucketY - bH + 5 * scale, bW * 0.45, Math.PI, 0, false);
        ctx.stroke();

        // Bucket body (tapered)
        ctx.fillStyle = '#92400e';
        ctx.beginPath();
        ctx.moveTo(bucketX - bW * 0.42, bucketY - bH + 5 * scale);
        ctx.lineTo(bucketX + bW * 0.42, bucketY - bH + 5 * scale);
        ctx.lineTo(bucketX + bW * 0.35, bucketY);
        ctx.lineTo(bucketX - bW * 0.35, bucketY);
        ctx.closePath();
        ctx.fill();

        // Iron hoops on bucket
        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 2 * scale;
        ctx.beginPath();
        ctx.moveTo(bucketX - bW * 0.4, bucketY - bH + 9 * scale);
        ctx.lineTo(bucketX + bW * 0.4, bucketY - bH + 9 * scale);
        ctx.moveTo(bucketX - bW * 0.36, bucketY - 3 * scale);
        ctx.lineTo(bucketX + bW * 0.36, bucketY - 3 * scale);
        ctx.stroke();

        // Water dripping from bucket
        const dripTime = (Date.now() * 0.003) % 1;
        ctx.fillStyle = '#38bdf8';
        ctx.beginPath();
        ctx.arc(bucketX, bucketY + dripTime * 12 * scale, 2 * scale, 0, Math.PI * 2);
        ctx.fill();

        // 6. Canopy Roof (Terracotta shaded tiles)
        const roofExtra = 12 * scale;
        const rLeft = drawX - halfW - roofExtra;
        const rRight = drawX + halfW + roofExtra;
        const rPeakY = roofY;
        const rEaveY = roofY + roofH;

        // Roof shadow underneath
        ctx.fillStyle = 'rgba(67, 20, 7, 0.4)';
        ctx.beginPath();
        ctx.moveTo(rLeft + 4 * scale, rEaveY);
        ctx.lineTo(rRight - 4 * scale, rEaveY);
        ctx.lineTo(drawX, rPeakY + 6 * scale);
        ctx.closePath();
        ctx.fill();

        // Roof gable triangle / hipped tiles
        const roofGrad = ctx.createLinearGradient(0, rPeakY, 0, rEaveY);
        roofGrad.addColorStop(0, '#ea580c');
        roofGrad.addColorStop(0.5, '#c2410c');
        roofGrad.addColorStop(1, '#9a3412');
        ctx.fillStyle = roofGrad;
        ctx.beginPath();
        ctx.moveTo(drawX, rPeakY);
        ctx.lineTo(rRight, rEaveY);
        ctx.lineTo(rLeft, rEaveY);
        ctx.closePath();
        ctx.fill();

        // Roof tile ridge lines
        ctx.strokeStyle = '#7c2d12';
        ctx.lineWidth = 2 * scale;
        for (let tx = rLeft + 8 * scale; tx <= rRight - 8 * scale; tx += 9 * scale) {
            ctx.beginPath();
            ctx.moveTo(drawX, rPeakY);
            ctx.lineTo(tx, rEaveY);
            ctx.stroke();
        }

        // Roof Peak Cap Finial
        ctx.fillStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(drawX, rPeakY - 2 * scale, 4 * scale, 0, Math.PI * 2);
        ctx.fill();

        // 7. Interactive Floating Prompt / Glow if Player is Near
        const distToPlayer = Math.abs(player.x - well.x);
        const isNear = distToPlayer < 75 && Math.abs(player.y - well.y) < 70;
        if (isNear && currentState === STATES.PLAYING) {
            const floatBob = Math.sin(Date.now() * 0.007) * 4 * scale;
            const badgeY = roofY - 22 * scale + floatBob;

            // Soft cyan water glow aura
            ctx.fillStyle = 'rgba(6, 182, 212, 0.25)';
            ctx.beginPath();
            ctx.ellipse(drawX, badgeY, 68 * scale, 16 * scale, 0, 0, Math.PI * 2);
            ctx.fill();

            // Glass badge
            ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
            ctx.beginPath();
            ctx.roundRect(drawX - 58 * scale, badgeY - 12 * scale, 116 * scale, 24 * scale, 8 * scale);
            ctx.fill();
            ctx.strokeStyle = '#38bdf8';
            ctx.lineWidth = 1.5 * scale;
            ctx.stroke();

            // Text
            ctx.fillStyle = '#ffffff';
            ctx.font = `bold ${11 * scale}px 'Outfit', sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('💧 [E] Напиться', drawX, badgeY);
        }

        ctx.restore();
    }

    // ==========================================
    // --- LEVEL 81 INTRO CUTSCENE (STEPPE -> JAPANESE TOWN -> GLOWING SAMURAI OUTFIT & KATANA) ---
    // ==========================================
    const cutsceneIntro81 = {
        active: false,
        timer: 0,
        phase: 'WALK_STEPPE', // 'WALK_STEPPE' -> 'ARRIVE_TOWN' -> 'GLOW_TRANSFORM' -> 'READY_POSE'
        townBorderX: 540,
        glowProgress: 0,
        glowIntensity: 0,
        glowRings: [],
        glowPetals: []
    };

    function startLevel81IntroCutscene() {
        currentState = STATES.CUTSCENE;
        cutsceneIntro81.active = true;
        cutsceneIntro81.timer = 0;
        cutsceneIntro81.phase = 'WALK_STEPPE';
        cutsceneIntro81.glowProgress = 0;
        cutsceneIntro81.glowIntensity = 0;
        cutsceneIntro81.glowRings = [];
        cutsceneIntro81.glowPetals = [];

        if (hudOverlay) hudOverlay.classList.add('hidden');
        if (inventoryHud) inventoryHud.classList.add('hidden');
        if (coldHud) coldHud.classList.add('hidden');
        if (healthHud) healthHud.classList.add('hidden');
        if (thirstHud) thirstHud.classList.add('hidden');

        if (cutsceneOverlay) {
            cutsceneOverlay.classList.remove('hidden');
        }
        if (cutsceneChapter) {
            cutsceneChapter.textContent = '🌸 СТРАНИЦА 5: ЦВЕТЕНИЕ САКУРЫ';
        }
        if (cutsceneText) {
            cutsceneText.textContent = 'Стикмен идет по бескрайней зеленой степи под ярким солнцем и облаками...';
        }

        // Start in the open steppe without the Japanese outfit/katana yet
        player.x = 100;
        player.y = 540;
        player.vx = 0;
        player.vy = 0;
        player.facing = 1;
        player.state = 'RUN';
        player.animTime = 0;
        player.cold = 0;
        player.health = 100;
        player.thirst = 100;
        player.hasSamuraiOutfit = false;

        cameraX = 0;
        cameraY = 0;
    }

    function updateCutsceneIntro81() {
        if (!cutsceneIntro81.active) return;

        cutsceneIntro81.timer += 0.016;
        updateAmbientSakura();

        // Update expanding glow rings
        for (let i = cutsceneIntro81.glowRings.length - 1; i >= 0; i--) {
            const r = cutsceneIntro81.glowRings[i];
            r.radius += r.speed;
            r.alpha -= 0.022;
            if (r.alpha <= 0) cutsceneIntro81.glowRings.splice(i, 1);
        }

        // Update swirling glow petals & golden sparks
        for (let i = cutsceneIntro81.glowPetals.length - 1; i >= 0; i--) {
            const p = cutsceneIntro81.glowPetals[i];
            p.angle += p.angSpeed;
            p.y -= p.vy;
            p.radius += p.radSpeed;
            p.x = player.x + Math.cos(p.angle) * p.radius;
            p.alpha -= 0.014;
            if (p.alpha <= 0) cutsceneIntro81.glowPetals.splice(i, 1);
        }

        if (cutsceneIntro81.phase === 'WALK_STEPPE') {
            // Walk across the open green steppe
            player.x += 2.4;
            player.vx = 2.4;
            player.facing = 1;
            player.state = 'WALK';
            player.animTime += 0.16;

            const targetCamX = Math.max(0, player.x - 320);
            cameraX += (targetCamX - cameraX) * 0.08;

            if (player.x >= cutsceneIntro81.townBorderX - 35) {
                cutsceneIntro81.phase = 'ARRIVE_TOWN';
                cutsceneIntro81.timer = 0;
                if (cutsceneChapter) {
                    cutsceneChapter.textContent = '⛩️ ДРЕВНИЙ ЯПОНСКИЙ ГОРОДОК';
                }
                if (cutsceneText) {
                    cutsceneText.textContent = 'Степь сменяется цветущим японским городком со святилищами и сакурой...';
                }
            }
        } else if (cutsceneIntro81.phase === 'ARRIVE_TOWN') {
            // Walk under the Torii gate into the town square
            if (player.x < 680) {
                player.x += 2.1;
                player.vx = 2.1;
                player.state = 'WALK';
                player.animTime += 0.14;
            } else {
                player.vx = 0;
                player.state = 'IDLE';
                player.animTime += 0.06;
            }

            const targetCamX = Math.max(0, player.x - 360);
            cameraX += (targetCamX - cameraX) * 0.08;

            if (cutsceneIntro81.timer >= 1.55) {
                cutsceneIntro81.phase = 'GLOW_TRANSFORM';
                cutsceneIntro81.timer = 0;
                cutsceneIntro81.glowProgress = 0;
                player.vx = 0;
                player.state = 'IDLE';
                playSound('sakuraGlow');

                // Initial ring burst
                cutsceneIntro81.glowRings.push({ radius: 10, speed: 4.2, alpha: 0.95, color: '#fef08a' });
                cutsceneIntro81.glowRings.push({ radius: 4, speed: 2.8, alpha: 0.9, color: '#f472b6' });

                if (cutsceneChapter) {
                    cutsceneChapter.textContent = '✨ СИЯЮЩЕЕ ПРЕОБРАЖЕНИЕ САМУРАЯ';
                }
                if (cutsceneText) {
                    cutsceneText.textContent = 'Внезапно в сиянии сакуры у героя появляется традиционная японская одежда и катана на поясе!';
                }
            }
        } else if (cutsceneIntro81.phase === 'GLOW_TRANSFORM') {
            cutsceneIntro81.glowProgress = Math.min(1, cutsceneIntro81.timer / 2.2);
            // Smooth bell curve glow intensity peaking around progress 0.5
            cutsceneIntro81.glowIntensity = Math.sin(cutsceneIntro81.glowProgress * Math.PI);

            // Spawn swirling golden sparks & sakura petals around the player
            if (Math.random() < 0.75) {
                cutsceneIntro81.glowPetals.push({
                    angle: Math.random() * Math.PI * 2,
                    angSpeed: 0.08 + Math.random() * 0.06,
                    radius: 12 + Math.random() * 28,
                    radSpeed: 0.35,
                    x: player.x,
                    y: player.y - 10 - Math.random() * 55,
                    vy: 1.2 + Math.random() * 1.6,
                    size: 3 + Math.random() * 4,
                    color: Math.random() < 0.55 ? '#fef08a' : (Math.random() < 0.5 ? '#f472b6' : '#fbcfe8'),
                    alpha: 0.95
                });
            }

            if (Math.floor(cutsceneIntro81.timer * 60) % 18 === 0) {
                cutsceneIntro81.glowRings.push({
                    radius: 12,
                    speed: 3.6,
                    alpha: 0.85,
                    color: Math.random() < 0.5 ? '#fde047' : '#f9a8d4'
                });
            }

            // Equip traditional Japanese clothing & waist katana at peak glow!
            if (cutsceneIntro81.glowProgress >= 0.48 && !player.hasSamuraiOutfit) {
                player.hasSamuraiOutfit = true;
                screenShake = 8;
                cutsceneIntro81.glowRings.push({ radius: 15, speed: 6.0, alpha: 1.0, color: '#ffffff' });
                cutsceneIntro81.glowRings.push({ radius: 8, speed: 4.5, alpha: 0.95, color: '#fbbf24' });
            }

            if (cutsceneIntro81.timer >= 2.3) {
                cutsceneIntro81.phase = 'READY_POSE';
                cutsceneIntro81.timer = 0;
                cutsceneIntro81.glowIntensity = 0.25;
                if (cutsceneText) {
                    cutsceneText.textContent = 'Облаченный в одеяние самурая с катаной на поясе, герой готов к паркуру по крышам и святилищам!';
                }
            }
        } else if (cutsceneIntro81.phase === 'READY_POSE') {
            cutsceneIntro81.glowIntensity = Math.max(0, 0.25 * (1 - cutsceneIntro81.timer / 1.4));
            if (cutsceneIntro81.timer >= 1.5) {
                finishLevel81IntroCutscene();
            }
        }
    }

    function finishLevel81IntroCutscene() {
        if (!cutsceneIntro81.active) return;
        cutsceneIntro81.active = false;
        cutsceneIntro81.glowIntensity = 0;
        if (cutsceneOverlay) {
            cutsceneOverlay.classList.add('hidden');
        }
        triggerFadeTransition(() => {
            loadLevel(81);
            player.reset();
            player.hasSamuraiOutfit = true;
            if (hudOverlay) hudOverlay.classList.remove('hidden');
            if (inventoryHud) inventoryHud.classList.add('hidden');
            if (coldHud) coldHud.classList.add('hidden');
            if (thirstHud) thirstHud.classList.add('hidden');
            if (healthHud) {
                healthHud.classList.remove('hidden');
                updateHealthHud();
            }
            currentState = STATES.PLAYING;
        });
    }

    function drawCutscene81Scene(scale) {
        const splitX = (cutsceneIntro81.townBorderX - cameraX) * scale;
        const groundY = (540 - cameraY) * scale;

        // 1. Sky Background (Bright Steppe Blue blending into Soft Warm Sakura Sky on the right)
        const skyGrad = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
        skyGrad.addColorStop(0, '#38bdf8');    // clear steppe sky blue
        skyGrad.addColorStop(0.45, '#7dd3fc'); // light azure
        skyGrad.addColorStop(0.75, '#fbcfe8'); // warm sakura pink horizon
        skyGrad.addColorStop(1, '#fde68a');    // golden morning glow
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Bright Sun in the sky (visible over steppe and town)
        const sunX = 240 * scale - cameraX * 0.12 * scale;
        const sunY = 115 * scale;
        const sunR = 46 * scale;
        const sunGlow = ctx.createRadialGradient(sunX, sunY, 8 * scale, sunX, sunY, sunR * 2.8);
        sunGlow.addColorStop(0, '#ffffff');
        sunGlow.addColorStop(0.25, '#fef08a');
        sunGlow.addColorStop(0.6, 'rgba(253, 224, 71, 0.35)');
        sunGlow.addColorStop(1, 'rgba(253, 224, 71, 0)');
        ctx.fillStyle = sunGlow;
        ctx.beginPath();
        ctx.arc(sunX, sunY, sunR * 2.8, 0, Math.PI * 2);
        ctx.fill();

        // 3. Fluffy White Steppe Clouds drifting across the sky
        const cloudPositions = [
            { x: 140, y: 95, s: 1.0 },
            { x: 390, y: 130, s: 0.85 },
            { x: 640, y: 85, s: 1.1 },
            { x: 920, y: 120, s: 0.9 }
        ];
        ctx.fillStyle = 'rgba(255, 255, 255, 0.88)';
        cloudPositions.forEach((cl, idx) => {
            const drift = (Date.now() * 0.012 * (idx % 2 === 0 ? 1 : 0.7)) % 1200;
            const cx = ((cl.x + drift * 0.05 - cameraX * 0.2) * scale);
            const cy = cl.y * scale;
            const cs = cl.s * scale;
            ctx.beginPath();
            ctx.arc(cx, cy, 24 * cs, 0, Math.PI * 2);
            ctx.arc(cx + 20 * cs, cy - 6 * cs, 20 * cs, 0, Math.PI * 2);
            ctx.arc(cx - 20 * cs, cy - 4 * cs, 18 * cs, 0, Math.PI * 2);
            ctx.arc(cx + 36 * cs, cy + 2 * cs, 15 * cs, 0, Math.PI * 2);
            ctx.fill();
        });

        // 4. LEFT SIDE: Open Green Steppe (Просто трава, облака и солнце)
        ctx.save();
        ctx.beginPath();
        ctx.rect(0, 0, Math.max(0, splitX), canvas.height);
        ctx.clip();

        // Gentle distant steppe grass hills (no trees or buildings — pure steppe!)
        ctx.fillStyle = '#86efac';
        ctx.beginPath();
        ctx.moveTo(0, groundY);
        ctx.quadraticCurveTo(180 * scale, groundY - 42 * scale, 380 * scale, groundY - 12 * scale);
        ctx.quadraticCurveTo(520 * scale, groundY - 28 * scale, splitX + 40 * scale, groundY);
        ctx.lineTo(0, groundY);
        ctx.fill();

        // Steppe Ground Soil & Lush Green Grass
        const steppeGrad = ctx.createLinearGradient(0, groundY, 0, canvas.height);
        steppeGrad.addColorStop(0, '#22c55e');
        steppeGrad.addColorStop(0.18, '#16a34a');
        steppeGrad.addColorStop(0.45, '#15803d');
        steppeGrad.addColorStop(1, '#14532d');
        ctx.fillStyle = steppeGrad;
        ctx.fillRect(0, groundY, Math.max(0, splitX), canvas.height - groundY);

        // Top vibrant grass turf strip
        ctx.fillStyle = '#4ade80';
        ctx.fillRect(0, groundY, Math.max(0, splitX), 8 * scale);

        // Steppe grass blades swaying in the breeze
        const windSway = Math.sin(Date.now() * 0.004) * 3 * scale;
        ctx.fillStyle = '#22c55e';
        for (let gx = 10; gx < cutsceneIntro81.townBorderX; gx += 14) {
            const sx = (gx - cameraX) * scale;
            const bh = (8 + (gx % 7)) * scale;
            ctx.beginPath();
            ctx.moveTo(sx - 2 * scale, groundY);
            ctx.lineTo(sx + windSway, groundY - bh);
            ctx.lineTo(sx + 2.5 * scale, groundY);
            ctx.fill();
        }
        ctx.restore();

        // 5. RIGHT SIDE: Japanese Town (Городок с сакурой, зданиями и святилищами)
        ctx.save();
        ctx.beginPath();
        ctx.rect(Math.max(0, splitX), 0, canvas.width - Math.max(0, splitX), canvas.height);
        ctx.clip();

        // Distant Mount Fuji silhouette on the horizon
        const fujiX = splitX + 430 * scale;
        const fujiBaseY = groundY;
        const fujiPeakY = 195 * scale;
        const fujiGrad = ctx.createLinearGradient(fujiX, fujiPeakY, fujiX, fujiBaseY);
        fujiGrad.addColorStop(0, '#6366f1');
        fujiGrad.addColorStop(0.5, '#818cf8');
        fujiGrad.addColorStop(1, 'rgba(199, 210, 254, 0.4)');
        ctx.fillStyle = fujiGrad;
        ctx.beginPath();
        ctx.moveTo(fujiX - 280 * scale, fujiBaseY);
        ctx.quadraticCurveTo(fujiX - 85 * scale, fujiPeakY + 45 * scale, fujiX - 28 * scale, fujiPeakY);
        ctx.lineTo(fujiX + 28 * scale, fujiPeakY);
        ctx.quadraticCurveTo(fujiX + 85 * scale, fujiPeakY + 45 * scale, fujiX + 280 * scale, fujiBaseY);
        ctx.closePath();
        ctx.fill();

        // Snow cap on Mount Fuji
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.moveTo(fujiX - 28 * scale, fujiPeakY);
        ctx.lineTo(fujiX + 28 * scale, fujiPeakY);
        ctx.lineTo(fujiX + 64 * scale, fujiPeakY + 75 * scale);
        ctx.lineTo(fujiX + 22 * scale, fujiPeakY + 58 * scale);
        ctx.lineTo(fujiX, fujiPeakY + 78 * scale);
        ctx.lineTo(fujiX - 22 * scale, fujiPeakY + 58 * scale);
        ctx.lineTo(fujiX - 64 * scale, fujiPeakY + 75 * scale);
        ctx.closePath();
        ctx.fill();

        // Town Background Sakura Trees
        const townTrees = [610, 790, 980, 1140];
        townTrees.forEach(tx => {
            const treeScreenX = (tx - cameraX) * scale;
            // Trunk
            ctx.fillStyle = '#451a03';
            ctx.fillRect(treeScreenX - 7 * scale, groundY - 125 * scale, 14 * scale, 125 * scale);
            // Blossoming pink canopy clouds
            ctx.fillStyle = '#f472b6';
            ctx.beginPath();
            ctx.arc(treeScreenX, groundY - 140 * scale, 48 * scale, 0, Math.PI * 2);
            ctx.arc(treeScreenX - 34 * scale, groundY - 122 * scale, 36 * scale, 0, Math.PI * 2);
            ctx.arc(treeScreenX + 34 * scale, groundY - 122 * scale, 36 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#fbcfe8';
            ctx.beginPath();
            ctx.arc(treeScreenX, groundY - 148 * scale, 34 * scale, 0, Math.PI * 2);
            ctx.arc(treeScreenX - 24 * scale, groundY - 130 * scale, 24 * scale, 0, Math.PI * 2);
            ctx.arc(treeScreenX + 24 * scale, groundY - 130 * scale, 24 * scale, 0, Math.PI * 2);
            ctx.fill();
        });

        // Town Entrance Vermilion Torii Gate (at x = 575)
        drawSakuraShrine({ x: 550, y: 380, w: 120, h: 160, shrineStyle: 'torii' }, scale);

        // Background Traditional Japanese Buildings & Pagoda in the Town Square
        drawSakuraBuilding({ x: 760, y: 340, w: 210, h: 200, buildingStyle: 'machiya' }, scale);
        drawSakuraShrine({ x: 1010, y: 240, w: 220, h: 300, shrineStyle: 'pagoda' }, scale);

        // Stone-paved Japanese Town Ground
        const townGroundGrad = ctx.createLinearGradient(0, groundY, 0, canvas.height);
        townGroundGrad.addColorStop(0, '#475569');
        townGroundGrad.addColorStop(0.25, '#334155');
        townGroundGrad.addColorStop(1, '#1e293b');
        ctx.fillStyle = townGroundGrad;
        ctx.fillRect(Math.max(0, splitX), groundY, canvas.width - Math.max(0, splitX), canvas.height - groundY);

        // Stone Flagstone Tiles & Fallen Sakura Petals on Town Road
        ctx.fillStyle = '#94a3b8';
        ctx.fillRect(Math.max(0, splitX), groundY, canvas.width - Math.max(0, splitX), 6 * scale);
        ctx.fillStyle = '#f9a8d4';
        for (let px = cutsceneIntro81.townBorderX + 10; px < cutsceneIntro81.townBorderX + 900; px += 28) {
            const spx = (px - cameraX) * scale;
            ctx.beginPath();
            ctx.ellipse(spx, groundY + 2 * scale, 4 * scale, 2 * scale, 0.2, 0, Math.PI * 2);
            ctx.fill();
        }

        // Falling Sakura Petals in the town
        drawAmbientSakura(scale);
        ctx.restore();

        // 6. Glowing Transformation Aura Effect around the Player (during GLOW_TRANSFORM & READY_POSE)
        if (cutsceneIntro81.glowIntensity > 0 || cutsceneIntro81.glowRings.length > 0 || cutsceneIntro81.glowPetals.length > 0) {
            const px = (player.x - cameraX) * scale;
            const py = (player.y - 34 - cameraY) * scale;

            ctx.save();
            if (cutsceneIntro81.glowIntensity > 0) {
                const gInt = cutsceneIntro81.glowIntensity;
                // Vertical celestial beam of light
                const beamGrad = ctx.createLinearGradient(px - 55 * scale, 0, px + 55 * scale, 0);
                beamGrad.addColorStop(0, 'rgba(251, 207, 232, 0)');
                beamGrad.addColorStop(0.3, `rgba(244, 114, 182, ${gInt * 0.45})`);
                beamGrad.addColorStop(0.5, `rgba(254, 240, 138, ${gInt * 0.85})`);
                beamGrad.addColorStop(0.7, `rgba(244, 114, 182, ${gInt * 0.45})`);
                beamGrad.addColorStop(1, 'rgba(251, 207, 232, 0)');
                ctx.fillStyle = beamGrad;
                ctx.fillRect(px - 55 * scale, 0, 110 * scale, groundY);

                // Radial golden-sakura aura sphere
                const auraR = (65 + gInt * 55) * scale;
                const auraGrad = ctx.createRadialGradient(px, py, 4 * scale, px, py, auraR);
                auraGrad.addColorStop(0, `rgba(255, 255, 255, ${Math.min(1, gInt * 1.1)})`);
                auraGrad.addColorStop(0.35, `rgba(253, 224, 71, ${gInt * 0.8})`);
                auraGrad.addColorStop(0.7, `rgba(244, 114, 182, ${gInt * 0.5})`);
                auraGrad.addColorStop(1, 'rgba(236, 72, 153, 0)');
                ctx.fillStyle = auraGrad;
                ctx.beginPath();
                ctx.arc(px, py, auraR, 0, Math.PI * 2);
                ctx.fill();
            }

            // Expanding light rings
            cutsceneIntro81.glowRings.forEach(r => {
                ctx.strokeStyle = r.color;
                ctx.globalAlpha = Math.max(0, r.alpha);
                ctx.lineWidth = 3 * scale;
                ctx.beginPath();
                ctx.arc(px, py, r.radius * scale, 0, Math.PI * 2);
                ctx.stroke();
            });

            // Swirling petals & golden sparks
            cutsceneIntro81.glowPetals.forEach(pt => {
                const ptx = (pt.x - cameraX) * scale;
                const pty = (pt.y - cameraY) * scale;
                ctx.globalAlpha = Math.max(0, pt.alpha);
                ctx.fillStyle = pt.color;
                ctx.beginPath();
                ctx.ellipse(ptx, pty, pt.size * scale, pt.size * 0.6 * scale, pt.angle, 0, Math.PI * 2);
                ctx.fill();
            });
            ctx.restore();
        }
    }

    // ==========================================
    // --- SAKURA BLOSSOM BIOME RENDERING (BUILDINGS, SHRINES, TREES, PETALS, KATANA) ---
    // ==========================================
    const ambientSakura = [];
    for (let i = 0; i < 95; i++) {
        ambientSakura.push({
            x: Math.random() * 2600,
            y: Math.random() * 675,
            vx: -0.9 - Math.random() * 1.5,
            vy: 0.8 + Math.random() * 1.3,
            size: 3.2 + Math.random() * 3.5,
            angle: Math.random() * Math.PI * 2,
            spinSpeed: (Math.random() - 0.5) * 0.06,
            swayPhase: Math.random() * Math.PI * 2,
            alpha: 0.55 + Math.random() * 0.4,
            color: Math.random() < 0.5 ? '#fbcfe8' : (Math.random() < 0.6 ? '#f9a8d4' : '#f472b6')
        });
    }

    function updateAmbientSakura() {
        for (let i = 0; i < ambientSakura.length; i++) {
            const p = ambientSakura[i];
            p.swayPhase += 0.035;
            p.x += p.vx + Math.sin(p.swayPhase) * 0.65;
            p.y += p.vy + Math.cos(p.swayPhase * 0.7) * 0.25;
            p.angle += p.spinSpeed;

            if (p.y > 685) {
                p.y = -12;
                p.x = Math.random() * 2600;
            }
            if (p.x < -30) {
                p.x = 2580;
                p.y = Math.random() * 660;
            }
        }
    }

    function drawAmbientSakura(scale) {
        ctx.save();
        for (let i = 0; i < ambientSakura.length; i++) {
            const p = ambientSakura[i];
            const sx = (p.x % (width + 200)) * scale;
            const sy = p.y * scale;
            if (sx < -20 || sx > canvas.width + 20) continue;

            ctx.save();
            ctx.translate(sx, sy);
            ctx.rotate(p.angle);
            ctx.globalAlpha = p.alpha;
            ctx.fillStyle = p.color;

            // Delicate notched sakura petal shape
            const r = p.size * scale;
            ctx.beginPath();
            ctx.moveTo(0, -r);
            ctx.bezierCurveTo(r * 0.85, -r * 0.6, r * 0.75, r * 0.6, 0, r);
            ctx.bezierCurveTo(-r * 0.75, r * 0.6, -r * 0.85, -r * 0.6, 0, -r * 0.35);
            ctx.closePath();
            ctx.fill();
            ctx.restore();
        }
        ctx.restore();
    }

    function drawSakuraChasms(scale) {
        if (!currentLevelData.chasms) return;
        const groundY = (currentLevelData.groundY - cameraY) * scale;
        const chasmBottom = canvas.height;

        currentLevelData.chasms.forEach(ch => {
            const startX = (ch.startX - cameraX) * scale;
            const endX = (ch.endX - cameraX) * scale;
            const chasmW = endX - startX;
            if (endX < -80 || startX > canvas.width + 80) return;

            ctx.save();
            // Deep Japanese mountain ravine sky/mist backdrop
            const mistGrad = ctx.createLinearGradient(0, groundY, 0, chasmBottom);
            mistGrad.addColorStop(0, '#475569');
            mistGrad.addColorStop(0.45, '#1e293b');
            mistGrad.addColorStop(0.78, '#0284c7'); // tranquil koi stream at bottom
            mistGrad.addColorStop(1, '#0369a1');
            ctx.fillStyle = mistGrad;
            ctx.fillRect(startX, groundY - 2 * scale, chasmW, chasmBottom - groundY + 4 * scale);

            // Shimmering water ripples & floating sakura petals at bottom of ravine
            const waterY = groundY + 75 * scale;
            if (waterY < canvas.height) {
                ctx.fillStyle = 'rgba(125, 211, 252, 0.35)';
                ctx.fillRect(startX, waterY, chasmW, 6 * scale);
                ctx.fillStyle = '#fbcfe8';
                for (let wx = ch.startX + 25; wx < ch.endX - 20; wx += 55) {
                    const drift = Math.sin(Date.now() * 0.003 + wx) * 8 * scale;
                    ctx.beginPath();
                    ctx.ellipse((wx - cameraX) * scale + drift, waterY + 4 * scale, 4 * scale, 2 * scale, 0, 0, Math.PI * 2);
                    ctx.fill();
                }
            }

            // Stone embankment walls on left and right edges
            ctx.fillStyle = '#334155';
            ctx.fillRect(startX - 8 * scale, groundY, 10 * scale, chasmBottom - groundY);
            ctx.fillRect(endX - 2 * scale, groundY, 10 * scale, chasmBottom - groundY);

            // Vermilion wooden railing posts at chasm edges
            ctx.fillStyle = '#dc2626';
            ctx.fillRect(startX - 10 * scale, groundY - 22 * scale, 7 * scale, 22 * scale);
            ctx.fillRect(endX + 3 * scale, groundY - 22 * scale, 7 * scale, 22 * scale);
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(startX - 11 * scale, groundY - 25 * scale, 9 * scale, 4 * scale);
            ctx.fillRect(endX + 2 * scale, groundY - 25 * scale, 9 * scale, 4 * scale);
            ctx.restore();
        });
    }

    function drawSakuraBuilding(box, scale) {
        const drawX = (box.x - cameraX) * scale;
        const drawY = (box.y - cameraY) * scale;
        const drawW = box.w * scale;
        const drawH = box.h * scale;
        if (drawX + drawW < -120 || drawX > canvas.width + 120) return;

        const style = box.buildingStyle || 'machiya';
        ctx.save();

        // 1. Stone Foundation Base (Ishigaki castle stone wall at bottom)
        const baseH = Math.min(36 * scale, drawH * 0.22);
        const baseY = drawY + drawH - baseH;

        // Main walls (White Japanese shikkui plaster or warm cedar wood)
        const wallGrad = ctx.createLinearGradient(drawX, drawY, drawX + drawW, drawY + drawH);
        if (style === 'castle') {
            wallGrad.addColorStop(0, '#f8fafc');
            wallGrad.addColorStop(0.65, '#e2e8f0');
            wallGrad.addColorStop(1, '#cbd5e1');
        } else if (style === 'teahouse') {
            wallGrad.addColorStop(0, '#78350f');
            wallGrad.addColorStop(0.5, '#92400e');
            wallGrad.addColorStop(1, '#451a03');
        } else {
            // machiya
            wallGrad.addColorStop(0, '#fef3c7');
            wallGrad.addColorStop(0.55, '#fde68a');
            wallGrad.addColorStop(1, '#d97706');
        }
        ctx.fillStyle = wallGrad;
        ctx.fillRect(drawX + 4 * scale, drawY + 12 * scale, drawW - 8 * scale, drawH - 12 * scale);

        // Stone foundation blocks at the bottom
        ctx.fillStyle = '#475569';
        ctx.fillRect(drawX + 2 * scale, baseY, drawW - 4 * scale, baseH);
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 1.5 * scale;
        for (let sx = drawX + 18 * scale; sx < drawX + drawW - 10 * scale; sx += 28 * scale) {
            ctx.beginPath();
            ctx.moveTo(sx, baseY);
            ctx.lineTo(sx - 4 * scale, baseY + baseH);
            ctx.stroke();
        }

        // Dark Timber Pillars & Crossbeams (Hashira & Nuki)
        ctx.fillStyle = '#291509';
        const pillarW = 7 * scale;
        ctx.fillRect(drawX + 4 * scale, drawY + 12 * scale, pillarW, drawH - baseH - 12 * scale);
        ctx.fillRect(drawX + drawW - 4 * scale - pillarW, drawY + 12 * scale, pillarW, drawH - baseH - 12 * scale);
        ctx.fillRect(drawX + 4 * scale, drawY + (drawH - baseH) * 0.52, drawW - 8 * scale, 6 * scale);

        // Glowing Shoji Paper Sliding Windows (Kumiko lattice)
        const winTopY = drawY + 26 * scale;
        const winH = Math.max(24 * scale, (drawH - baseH) * 0.34);
        const winCount = Math.max(2, Math.floor(box.w / 65));
        const winGap = 14 * scale;
        const totalWinW = drawW - 28 * scale;
        const singleWinW = (totalWinW - winGap * (winCount - 1)) / winCount;

        for (let w = 0; w < winCount; w++) {
            const wx = drawX + 14 * scale + w * (singleWinW + winGap);
            const shojiGrad = ctx.createLinearGradient(wx, winTopY, wx, winTopY + winH);
            shojiGrad.addColorStop(0, '#fef08a');
            shojiGrad.addColorStop(0.5, '#fde047');
            shojiGrad.addColorStop(1, '#f59e0b');
            ctx.fillStyle = shojiGrad;
            ctx.fillRect(wx, winTopY, singleWinW, winH);

            // Wooden shoji grid bars
            ctx.strokeStyle = '#451a03';
            ctx.lineWidth = 1.6 * scale;
            ctx.strokeRect(wx, winTopY, singleWinW, winH);
            ctx.beginPath();
            ctx.moveTo(wx + singleWinW * 0.5, winTopY);
            ctx.lineTo(wx + singleWinW * 0.5, winTopY + winH);
            ctx.moveTo(wx, winTopY + winH * 0.5);
            ctx.lineTo(wx + singleWinW, winTopY + winH * 0.5);
            ctx.stroke();
        }

        // Mid-tier secondary eave for tall castle/teahouse buildings
        if (box.h >= 240) {
            const midRoofY = drawY + (drawH - baseH) * 0.52;
            ctx.fillStyle = '#1e293b';
            ctx.beginPath();
            ctx.moveTo(drawX - 10 * scale, midRoofY + 8 * scale);
            ctx.quadraticCurveTo(drawX + drawW * 0.5, midRoofY - 4 * scale, drawX + drawW + 10 * scale, midRoofY + 8 * scale);
            ctx.lineTo(drawX + drawW + 4 * scale, midRoofY - 5 * scale);
            ctx.lineTo(drawX - 4 * scale, midRoofY - 5 * scale);
            ctx.closePath();
            ctx.fill();
        }

        // Hanging Red Chochin Paper Lanterns under the eaves
        const lanternY = drawY + 22 * scale;
        const lanternPositions = [drawX + 24 * scale, drawX + drawW - 24 * scale];
        lanternPositions.forEach(lx => {
            const sway = Math.sin(Date.now() * 0.004 + lx) * 2 * scale;
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1.5 * scale;
            ctx.beginPath();
            ctx.moveTo(lx, drawY + 12 * scale);
            ctx.lineTo(lx + sway, lanternY);
            ctx.stroke();

            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.ellipse(lx + sway, lanternY + 7 * scale, 6 * scale, 8 * scale, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#fef08a';
            ctx.beginPath();
            ctx.ellipse(lx + sway, lanternY + 7 * scale, 3 * scale, 5 * scale, 0, 0, Math.PI * 2);
            ctx.fill();
        });

        // 2. Traditional Curved Kawara Tiled Roof (Parkour Top Surface at drawY)
        const eaveOverhang = 16 * scale;
        const roofLeft = drawX - eaveOverhang;
        const roofRight = drawX + drawW + eaveOverhang;
        const roofTopY = drawY;
        const roofEaveY = drawY + 18 * scale;

        const roofGrad = ctx.createLinearGradient(0, roofTopY - 8 * scale, 0, roofEaveY);
        roofGrad.addColorStop(0, '#334155');
        roofGrad.addColorStop(0.5, '#1e293b');
        roofGrad.addColorStop(1, '#0f172a');
        ctx.fillStyle = roofGrad;

        ctx.beginPath();
        // Upturned left horn
        ctx.moveTo(roofLeft, roofEaveY - 8 * scale);
        ctx.quadraticCurveTo(drawX + 10 * scale, roofTopY + 2 * scale, drawX + 18 * scale, roofTopY);
        // Flat parkourable ridge across the top
        ctx.lineTo(drawX + drawW - 18 * scale, roofTopY);
        // Upturned right horn
        ctx.quadraticCurveTo(drawX + drawW - 10 * scale, roofTopY + 2 * scale, roofRight, roofEaveY - 8 * scale);
        ctx.lineTo(roofRight - 6 * scale, roofEaveY);
        ctx.lineTo(roofLeft + 6 * scale, roofEaveY);
        ctx.closePath();
        ctx.fill();

        // Roof tile ribbing & golden ridge trim
        ctx.strokeStyle = '#64748b';
        ctx.lineWidth = 1.5 * scale;
        for (let rx = drawX + 8 * scale; rx < drawX + drawW - 8 * scale; rx += 16 * scale) {
            ctx.beginPath();
            ctx.moveTo(rx, roofTopY + 2 * scale);
            ctx.lineTo(rx, roofEaveY - 2 * scale);
            ctx.stroke();
        }

        // Golden ridge beam & sakura blossom highlight along the walkable top edge
        ctx.fillStyle = (style === 'castle') ? '#fbbf24' : '#f472b6';
        ctx.fillRect(drawX + 8 * scale, roofTopY, drawW - 16 * scale, 3.5 * scale);

        // Fallen sakura petals resting on the roof
        ctx.fillStyle = '#fbcfe8';
        for (let px = box.x + 22; px < box.x + box.w - 22; px += 34) {
            ctx.beginPath();
            ctx.ellipse((px - cameraX) * scale, roofTopY + 1.5 * scale, 3.5 * scale, 1.8 * scale, 0, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.restore();
    }

    function drawSakuraShrine(box, scale) {
        const drawX = (box.x - cameraX) * scale;
        const drawY = (box.y - cameraY) * scale;
        const drawW = box.w * scale;
        const drawH = box.h * scale;
        if (drawX + drawW < -140 || drawX > canvas.width + 140) return;

        const style = box.shrineStyle || 'honden';
        ctx.save();

        if (style === 'torii') {
            // Iconic Vermilion Shinto Torii Gate (parkourable across top kasagi lintel!)
            const pillarW = Math.max(14 * scale, drawW * 0.09);
            const leftPillarX = drawX + drawW * 0.16;
            const rightPillarX = drawX + drawW * 0.84 - pillarW;

            // Black stone pillar bases (Kamebara)
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(leftPillarX - 4 * scale, drawY + drawH - 22 * scale, pillarW + 8 * scale, 22 * scale);
            ctx.fillRect(rightPillarX - 4 * scale, drawY + drawH - 22 * scale, pillarW + 8 * scale, 22 * scale);

            // Vermilion Cylindrical Pillars (Hashira)
            const vermGrad = ctx.createLinearGradient(leftPillarX, 0, leftPillarX + pillarW, 0);
            vermGrad.addColorStop(0, '#991b1b');
            vermGrad.addColorStop(0.4, '#ef4444');
            vermGrad.addColorStop(1, '#b91c1c');
            ctx.fillStyle = vermGrad;
            ctx.fillRect(leftPillarX, drawY + 10 * scale, pillarW, drawH - 30 * scale);
            ctx.fillRect(rightPillarX, drawY + 10 * scale, pillarW, drawH - 30 * scale);

            // Lower Tie Beam (Nuki)
            const nukiY = drawY + 34 * scale;
            ctx.fillStyle = '#dc2626';
            ctx.fillRect(drawX + 6 * scale, nukiY, drawW - 12 * scale, 11 * scale);
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(drawX + 4 * scale, nukiY, 6 * scale, 11 * scale);
            ctx.fillRect(drawX + drawW - 10 * scale, nukiY, 6 * scale, 11 * scale);

            // Center strut (Gakuzuka) & Golden Shrine Tablet
            const centerX = drawX + drawW * 0.5;
            ctx.fillStyle = '#b91c1c';
            ctx.fillRect(centerX - 6 * scale, drawY + 12 * scale, 12 * scale, 24 * scale);
            ctx.fillStyle = '#fbbf24';
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 2 * scale;
            ctx.fillRect(centerX - 11 * scale, drawY + 14 * scale, 22 * scale, 18 * scale);
            ctx.strokeRect(centerX - 11 * scale, drawY + 14 * scale, 22 * scale, 18 * scale);

            // Sacred Shimenawa Rope with White Shide Zigzag Papers
            ctx.strokeStyle = '#d97706';
            ctx.lineWidth = 4 * scale;
            ctx.beginPath();
            ctx.moveTo(leftPillarX + pillarW, nukiY + 14 * scale);
            ctx.quadraticCurveTo(centerX, nukiY + 26 * scale, rightPillarX, nukiY + 14 * scale);
            ctx.stroke();

            ctx.fillStyle = '#ffffff';
            for (let s = 1; s <= 3; s++) {
                const sx = leftPillarX + pillarW + (rightPillarX - leftPillarX - pillarW) * (s / 4);
                const sy = nukiY + 19 * scale;
                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx - 4 * scale, sy + 7 * scale);
                ctx.lineTo(sx + 2 * scale, sy + 7 * scale);
                ctx.lineTo(sx - 2 * scale, sy + 14 * scale);
                ctx.lineTo(sx + 4 * scale, sy + 8 * scale);
                ctx.closePath();
                ctx.fill();
            }

            // Top Curved Lintel (Kasagi & Shimaki - Parkourable Top at drawY)
            const overhang = 18 * scale;
            ctx.fillStyle = '#dc2626';
            ctx.fillRect(drawX - overhang * 0.5, drawY + 6 * scale, drawW + overhang, 8 * scale);

            ctx.fillStyle = '#0f172a';
            ctx.beginPath();
            ctx.moveTo(drawX - overhang, drawY - 5 * scale);
            ctx.quadraticCurveTo(centerX, drawY + 2 * scale, drawX + drawW + overhang, drawY - 5 * scale);
            ctx.lineTo(drawX + drawW + overhang * 0.7, drawY + 7 * scale);
            ctx.lineTo(drawX - overhang * 0.7, drawY + 7 * scale);
            ctx.closePath();
            ctx.fill();

            // Golden top highlight & sakura petals
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(drawX, drawY, drawW, 2.5 * scale);
        } else if (style === 'pagoda') {
            // Multi-Tiered Japanese Pagoda (Gojunoto)
            const tiers = box.h >= 320 ? 4 : 3;
            const tierH = (drawH - 24 * scale) / tiers;

            // Stone podium base
            ctx.fillStyle = '#475569';
            ctx.fillRect(drawX + 6 * scale, drawY + drawH - 24 * scale, drawW - 12 * scale, 24 * scale);

            for (let t = 0; t < tiers; t++) {
                const tTopY = drawY + t * tierH;
                const inset = (tiers - 1 - t) * 6 * scale;
                const tX = drawX + 10 * scale + inset;
                const tW = drawW - 20 * scale - inset * 2;

                // Vermilion & white walls of tier
                ctx.fillStyle = '#fef2f2';
                ctx.fillRect(tX, tTopY + 12 * scale, tW, tierH - 12 * scale);
                ctx.strokeStyle = '#dc2626';
                ctx.lineWidth = 3 * scale;
                ctx.strokeRect(tX, tTopY + 12 * scale, tW, tierH - 12 * scale);

                // Vertical vermilion lattice columns
                for (let cx = tX + 16 * scale; cx < tX + tW - 10 * scale; cx += 22 * scale) {
                    ctx.fillStyle = '#b91c1c';
                    ctx.fillRect(cx, tTopY + 12 * scale, 4 * scale, tierH - 12 * scale);
                }

                // Curved Dark Slate Pagoda Eave for each tier
                const eaveExt = (t === 0 ? 18 : 14) * scale;
                const rLeft = (t === 0 ? drawX - 12 * scale : tX - eaveExt);
                const rRight = (t === 0 ? drawX + drawW + 12 * scale : tX + tW + eaveExt);
                ctx.fillStyle = '#1e293b';
                ctx.beginPath();
                ctx.moveTo(rLeft, tTopY + 8 * scale);
                ctx.quadraticCurveTo(drawX + drawW * 0.5, tTopY - 2 * scale, rRight, tTopY + 8 * scale);
                ctx.lineTo(rRight - 6 * scale, tTopY + 16 * scale);
                ctx.lineTo(rLeft + 6 * scale, tTopY + 16 * scale);
                ctx.closePath();
                ctx.fill();

                // Gold bell ornaments hanging from eaves corners
                ctx.fillStyle = '#fbbf24';
                ctx.beginPath();
                ctx.arc(rLeft + 4 * scale, tTopY + 14 * scale, 3 * scale, 0, Math.PI * 2);
                ctx.arc(rRight - 4 * scale, tTopY + 14 * scale, 3 * scale, 0, Math.PI * 2);
                ctx.fill();
            }

            // Walkable Top Pagoda Ridge & Golden Sorin Spire
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(drawX + 6 * scale, drawY, drawW - 12 * scale, 3.5 * scale);
        } else {
            // Sacred Shinto Honden Sanctuary Shrine
            const baseH = 28 * scale;
            const baseY = drawY + drawH - baseH;

            // Stone foundation & steps
            ctx.fillStyle = '#64748b';
            ctx.fillRect(drawX + 4 * scale, baseY, drawW - 8 * scale, baseH);

            // White sacred plaster walls with vermilion timber frame
            ctx.fillStyle = '#fff1f2';
            ctx.fillRect(drawX + 8 * scale, drawY + 16 * scale, drawW - 16 * scale, drawH - baseH - 16 * scale);

            // Vermilion columns & beams
            ctx.fillStyle = '#dc2626';
            const colStep = Math.max(38 * scale, (drawW - 24 * scale) / 4);
            for (let cx = drawX + 8 * scale; cx <= drawX + drawW - 14 * scale; cx += colStep) {
                ctx.fillRect(cx, drawY + 16 * scale, 8 * scale, drawH - baseH - 16 * scale);
            }
            ctx.fillRect(drawX + 4 * scale, drawY + 20 * scale, drawW - 8 * scale, 8 * scale);
            ctx.fillRect(drawX + 4 * scale, baseY - 10 * scale, drawW - 8 * scale, 8 * scale);

            // Sacred Suzu Bell & Rope in center
            const midX = drawX + drawW * 0.5;
            ctx.strokeStyle = '#fde047';
            ctx.lineWidth = 4 * scale;
            ctx.beginPath();
            ctx.moveTo(midX, drawY + 28 * scale);
            ctx.lineTo(midX, baseY - 12 * scale);
            ctx.stroke();
            ctx.fillStyle = '#fbbf24';
            ctx.beginPath();
            ctx.arc(midX, drawY + 34 * scale, 7 * scale, 0, Math.PI * 2);
            ctx.fill();

            // Grand Shrine Roof with Golden Chigi Finials & Katsuogi Logs
            const rLeft = drawX - 18 * scale;
            const rRight = drawX + drawW + 18 * scale;
            const rGrad = ctx.createLinearGradient(0, drawY, 0, drawY + 20 * scale);
            rGrad.addColorStop(0, '#1e293b');
            rGrad.addColorStop(1, '#0f172a');
            ctx.fillStyle = rGrad;
            ctx.beginPath();
            ctx.moveTo(rLeft, drawY + 10 * scale);
            ctx.quadraticCurveTo(drawX + 16 * scale, drawY, drawX + 24 * scale, drawY);
            ctx.lineTo(drawX + drawW - 24 * scale, drawY);
            ctx.quadraticCurveTo(drawX + drawW - 16 * scale, drawY, rRight, drawY + 10 * scale);
            ctx.lineTo(rRight - 8 * scale, drawY + 20 * scale);
            ctx.lineTo(rLeft + 8 * scale, drawY + 20 * scale);
            ctx.closePath();
            ctx.fill();

            // Golden Katsuogi ridge billets & crimson/gold top highlight
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(drawX + 12 * scale, drawY, drawW - 24 * scale, 4 * scale);
            for (let kx = drawX + 28 * scale; kx < drawX + drawW - 28 * scale; kx += 32 * scale) {
                ctx.fillRect(kx - 5 * scale, drawY - 4 * scale, 10 * scale, 4 * scale);
            }
        }

        ctx.restore();
    }

    function drawSakuraLadder(lad, scale) {
        const drawX = (lad.x - cameraX) * scale;
        const drawTopY = (lad.topY - cameraY) * scale;
        const drawBotY = (lad.bottomY - cameraY) * scale;
        const drawW = (lad.w || 40) * scale;
        if (drawX + drawW < -60 || drawX - drawW > canvas.width + 60) return;

        const leftX = drawX - drawW / 2;
        const rightX = drawX + drawW / 2;

        ctx.save();
        // Green-Gold Bamboo Side Rails
        ctx.strokeStyle = '#65a30d';
        ctx.lineWidth = 5.5 * scale;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(leftX, drawTopY);
        ctx.lineTo(leftX, drawBotY);
        ctx.moveTo(rightX, drawTopY);
        ctx.lineTo(rightX, drawBotY);
        ctx.stroke();

        // Bamboo Highlight Core
        ctx.strokeStyle = '#a3e635';
        ctx.lineWidth = 2 * scale;
        ctx.beginPath();
        ctx.moveTo(leftX - 1 * scale, drawTopY);
        ctx.lineTo(leftX - 1 * scale, drawBotY);
        ctx.moveTo(rightX - 1 * scale, drawTopY);
        ctx.lineTo(rightX - 1 * scale, drawBotY);
        ctx.stroke();

        // Horizontal Bamboo Rungs with Crimson Cord Bindings
        const step = 22;
        for (let rY = lad.topY + 12; rY <= lad.bottomY - 8; rY += step) {
            const rungY = (rY - cameraY) * scale;
            ctx.strokeStyle = '#84cc16';
            ctx.lineWidth = 4 * scale;
            ctx.beginPath();
            ctx.moveTo(leftX - 2 * scale, rungY);
            ctx.lineTo(rightX + 2 * scale, rungY);
            ctx.stroke();

            // Crimson tie knots at corners
            ctx.fillStyle = '#dc2626';
            ctx.beginPath();
            ctx.arc(leftX, rungY, 3 * scale, 0, Math.PI * 2);
            ctx.arc(rightX, rungY, 3 * scale, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    }

    function drawSakuraTreeTurnik(tur, scale) {
        const drawX = (tur.x - cameraX) * scale;
        const drawY = (tur.y - cameraY) * scale;
        const groundY = ((tur.boxBottomY || currentLevelData.groundY) - cameraY) * scale;
        const barLen = (tur.length || 90) * scale;
        if (drawX + barLen < -150 || drawX - barLen > canvas.width + 150) return;

        ctx.save();
        const trunkX = drawX - barLen * 0.52;
        const crownY = drawY - 42 * scale;

        // 1. Gnarled Cherry Blossom Tree Trunk rising from the ravine/ground
        const trunkGrad = ctx.createLinearGradient(trunkX - 16 * scale, 0, trunkX + 16 * scale, 0);
        trunkGrad.addColorStop(0, '#291509');
        trunkGrad.addColorStop(0.5, '#5c240e');
        trunkGrad.addColorStop(1, '#3b1506');
        ctx.fillStyle = trunkGrad;
        ctx.beginPath();
        ctx.moveTo(trunkX - 18 * scale, groundY);
        ctx.quadraticCurveTo(trunkX - 10 * scale, (groundY + drawY) * 0.5, trunkX - 11 * scale, crownY);
        ctx.lineTo(trunkX + 11 * scale, crownY);
        ctx.quadraticCurveTo(trunkX + 12 * scale, (groundY + drawY) * 0.5, trunkX + 20 * scale, groundY);
        ctx.closePath();
        ctx.fill();

        // 2. Lush Blossoming Sakura Canopy Clouds above the branch
        const clusters = [
            { dx: 0, dy: -22, r: 46, c: '#ec4899' },
            { dx: -36, dy: -8, r: 36, c: '#f472b6' },
            { dx: 38, dy: -12, r: 40, c: '#f472b6' },
            { dx: 8, dy: -28, r: 34, c: '#fbcfe8' },
            { dx: -20, dy: -16, r: 28, c: '#fce7f3' }
        ];
        clusters.forEach(cl => {
            ctx.fillStyle = cl.c;
            ctx.beginPath();
            ctx.arc(trunkX + cl.dx * scale, crownY + cl.dy * scale, cl.r * scale, 0, Math.PI * 2);
            ctx.fill();
        });

        // 3. Horizontal Swingable Sakura Branch at (drawX, drawY)
        ctx.strokeStyle = '#451a03';
        ctx.lineWidth = 8 * scale;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(trunkX, drawY - 4 * scale);
        ctx.quadraticCurveTo(drawX - barLen * 0.25, drawY, drawX + barLen * 0.5, drawY);
        ctx.stroke();

        // Highlighted swing bar zone with glowing pink blossom buds
        ctx.strokeStyle = '#f472b6';
        ctx.lineWidth = 4 * scale;
        ctx.beginPath();
        ctx.moveTo(drawX - barLen * 0.45, drawY);
        ctx.lineTo(drawX + barLen * 0.45, drawY);
        ctx.stroke();

        // Small sakura blossoms along the branch ends
        ctx.fillStyle = '#fbcfe8';
        ctx.beginPath();
        ctx.arc(drawX - barLen * 0.48, drawY - 3 * scale, 6 * scale, 0, Math.PI * 2);
        ctx.arc(drawX + barLen * 0.5, drawY - 2 * scale, 7 * scale, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
    }

    function drawSakuraRope(rope, scale) {
        const anchorX = (rope.x - cameraX) * scale;
        const anchorY = (rope.anchorY - cameraY) * scale;
        const ropeLen = (rope.length || 180) * scale;
        if (anchorX < -120 || anchorX > canvas.width + 120) return;

        let currentAngle = 0;
        if ((player.state === 'ROPE' || player.state === 'ROPE_SWING') && player.activeRope && (player.activeRope === rope || player.activeRope.id === rope.id)) {
            currentAngle = player.ropeAngle;
        } else {
            currentAngle = Math.sin(Date.now() * 0.002 + rope.x) * 0.05;
        }

        const endX = anchorX + Math.sin(currentAngle) * ropeLen;
        const endY = anchorY + Math.cos(currentAngle) * ropeLen;

        ctx.save();
        // Overhead wooden shrine beam mount
        ctx.fillStyle = '#dc2626';
        ctx.fillRect(anchorX - 14 * scale, anchorY - 8 * scale, 28 * scale, 10 * scale);
        ctx.fillStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(anchorX, anchorY, 5 * scale, 0, Math.PI * 2);
        ctx.fill();

        // Braided Crimson & Gold Silk Shrine Cord
        ctx.strokeStyle = '#dc2626';
        ctx.lineWidth = 4.5 * scale;
        ctx.beginPath();
        ctx.moveTo(anchorX, anchorY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 1.8 * scale;
        ctx.setLineDash([5 * scale, 5 * scale]);
        ctx.beginPath();
        ctx.moveTo(anchorX, anchorY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
        ctx.setLineDash([]);

        // Glowing Red & Gold Japanese Paper Lantern (Chochin) at the grip knot
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        ctx.ellipse(endX, endY, 10 * scale, 13 * scale, -currentAngle, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#fef08a';
        ctx.beginPath();
        ctx.ellipse(endX, endY, 5 * scale, 8 * scale, -currentAngle, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(endX - 6 * scale, endY - 13 * scale, 12 * scale, 3 * scale);
        ctx.fillRect(endX - 6 * scale, endY + 10 * scale, 12 * scale, 3 * scale);
        ctx.restore();
    }

    function drawSakuraHazard(hz, scale) {
        const drawX = (hz.x - cameraX) * scale;
        const drawY = (hz.y - cameraY) * scale;
        const w = (hz.w || 38) * scale;
        const h = (hz.h || 50) * scale;
        if (drawX + w < -60 || drawX - w > canvas.width + 60) return;

        ctx.save();
        // Bundle of sharpened bamboo stakes bound with crimson cord
        const spikes = [-0.36, -0.18, 0, 0.18, 0.36];
        spikes.forEach((offset, idx) => {
            const sx = drawX + offset * w;
            const sh = h * (idx === 2 ? 1.0 : (idx % 2 === 1 ? 0.88 : 0.74));
            ctx.fillStyle = idx % 2 === 0 ? '#4d7c0f' : '#65a30d';
            ctx.beginPath();
            ctx.moveTo(sx - 4.5 * scale, drawY);
            ctx.lineTo(sx, drawY - sh);
            ctx.lineTo(sx + 4.5 * scale, drawY);
            ctx.closePath();
            ctx.fill();

            // Freshly cut sharp pale bamboo bevel tip
            ctx.fillStyle = '#fef08a';
            ctx.beginPath();
            ctx.moveTo(sx - 2.2 * scale, drawY - sh * 0.72);
            ctx.lineTo(sx, drawY - sh);
            ctx.lineTo(sx + 2.2 * scale, drawY - sh * 0.72);
            ctx.closePath();
            ctx.fill();
        });

        // Crimson binding band near the base
        ctx.fillStyle = '#dc2626';
        ctx.fillRect(drawX - w * 0.44, drawY - 14 * scale, w * 0.88, 6 * scale);
        ctx.restore();
    }

    function drawSakuraFlag(flag, scale) {
        const flagX = (flag.x - cameraX) * scale;
        const flagY = (flag.y - cameraY) * scale;
        const poleH = (flag.poleHeight || 115) * scale;
        const bannerW = (flag.bannerW || 46) * scale;
        const bannerH = (flag.bannerH || 32) * scale;

        ctx.save();
        // Red-lacquered Samurai Nobori Pole
        ctx.strokeStyle = '#991b1b';
        ctx.lineWidth = 5 * scale;
        ctx.beginPath();
        ctx.moveTo(flagX, flagY);
        ctx.lineTo(flagX, flagY - poleH);
        ctx.stroke();

        // Golden Crest Finial
        ctx.fillStyle = '#fbbf24';
        ctx.beginPath();
        ctx.arc(flagX, flagY - poleH, 7 * scale, 0, Math.PI * 2);
        ctx.fill();

        // Fluttering Sakura Pink & Crimson Silk Banner
        const wave = Math.sin(Date.now() * 0.006) * 5 * scale;
        const topY = flagY - poleH + 8 * scale;
        const fGrad = ctx.createLinearGradient(flagX, topY, flagX + bannerW, topY);
        fGrad.addColorStop(0, '#be185d');
        fGrad.addColorStop(0.5, '#ec4899');
        fGrad.addColorStop(1, '#fbcfe8');

        ctx.fillStyle = fGrad;
        ctx.beginPath();
        ctx.moveTo(flagX, topY);
        ctx.quadraticCurveTo(flagX + bannerW * 0.5, topY + wave, flagX + bannerW, topY + wave / 2);
        ctx.lineTo(flagX + bannerW, topY + bannerH + wave / 2);
        ctx.quadraticCurveTo(flagX + bannerW * 0.5, topY + bannerH + wave, flagX, topY + bannerH);
        ctx.closePath();
        ctx.fill();

        // Sakura Blossom Emblem on Banner
        ctx.fillStyle = '#ffffff';
        ctx.font = `bold ${16 * scale}px sans-serif`;
        ctx.fillText('🌸', flagX + 11 * scale, topY + bannerH * 0.72 + wave / 2);
        ctx.restore();
    }

    // --- SAKURA BAMBOO OBSTACLE & WORKING KATANA SYSTEM (LEVEL 81+) ---
    function resetBamboos() {
        if (!currentLevelData || !currentLevelData.bamboos) return;
        currentLevelData.bamboos.forEach(bam => {
            bam.isCut = false;
            bam.cutTimer = 0;
            bam.cutY = bam.y - 46;
            bam.cutDir = 1;
            bam.fallX = 0;
            bam.fallY = 0;
            bam.fallVx = 0;
            bam.fallVy = 0;
            bam.fallAngle = 0;
            bam.fallAngVel = 0;
            bam.alpha = 1;
        });
    }

    function playerKatanaSlash() {
        if (player.state === 'DEFEAT' || player.state === 'VICTORY' || player.state === 'VICTORY_IDLE' || currentState !== STATES.PLAYING) return;
        if (['HANG', 'CLIMB', 'LADDER', 'TURNIK', 'TURNIK_SWING', 'ROPE', 'FREEZE'].includes(player.state)) return;
        if (player.katanaCooldown && player.katanaCooldown > 0) return;

        player.katanaSlashTimer = 0.24;
        player.katanaCooldown = 0.28;
        player.katanaCombo = (player.katanaCombo === 1) ? -1 : 1;
        playSound('katanaSlash');

        // Spawn swift silver-sakura wind sparks along the slash arc
        for (let i = 0; i < 6; i++) {
            const ang = (-0.9 + (i / 5) * 1.8) * player.katanaCombo;
            particles.push({
                x: player.x + player.facing * (26 + Math.cos(ang) * 28),
                y: player.y - 44 + Math.sin(ang) * 28,
                vx: player.facing * (2.2 + Math.random() * 2.8),
                vy: (Math.random() - 0.5) * 2.2,
                size: 2.2 + Math.random() * 2.2,
                color: Math.random() < 0.55 ? '#ffffff' : '#f9a8d4',
                life: 0.28,
                decay: 0.04
            });
        }

        checkKatanaBambooHits();

        // Also allow basic LMB katana slash to hit the Level 100 Crimson Samurai Boss (3 dmg)
        if (currentLevelIndex === 100 && typeof samuraiBoss !== 'undefined' && samuraiBoss.active && !samuraiBoss.isFallen) {
            const dx = (samuraiBoss.x - player.x) * player.facing;
            if (dx >= -25 && dx <= 120 && Math.abs(player.y - samuraiBoss.y) < 92) {
                damageSamuraiBoss(3, 'lmb');
            }
        }
    }

    function checkKatanaBambooHits() {
        if (!currentLevelData || !currentLevelData.bamboos) return;
        currentLevelData.bamboos.forEach(bam => {
            if (bam.isCut) return;
            const halfW = (bam.w || 46) * 0.5;
            const dx = (bam.x - player.x) * player.facing;
            // Must be facing the bamboo within katana blade reach, and at/above the bamboo's base level
            const inHorizontalReach = (dx >= -25 && dx <= 108 + halfW);
            const inVerticalReach = (player.y <= bam.y + 28 && player.y - player.height >= -350);

            if (inHorizontalReach && inVerticalReach) {
                bam.isCut = true;
                bam.cutTimer = 0;
                bam.cutDir = player.facing;
                bam.cutY = Math.min(bam.y - 24, Math.max(bam.y - 125, player.y - 40));
                bam.fallX = 0;
                bam.fallY = 0;
                bam.fallVx = player.facing * 2.8;
                bam.fallVy = -1.6;
                bam.fallAngle = 0;
                bam.fallAngVel = player.facing * 0.026;
                bam.alpha = 1;

                playSound('bambooCut');
                screenShake = Math.max(screenShake, 7);

                // Burst of bamboo splinters, emerald leaves & sakura petals at the slice line
                for (let p = 0; p < 22; p++) {
                    const isPetal = Math.random() < 0.25;
                    particles.push({
                        x: bam.x + (Math.random() - 0.5) * (bam.w || 46),
                        y: bam.cutY + (Math.random() - 0.5) * 18,
                        vx: player.facing * (1.8 + Math.random() * 5.2) + (Math.random() - 0.5) * 2.4,
                        vy: -(1.5 + Math.random() * 4.8),
                        size: isPetal ? (3 + Math.random() * 2.5) : (2.5 + Math.random() * 3.8),
                        color: isPetal ? '#f9a8d4' : (Math.random() < 0.45 ? '#4ade80' : (Math.random() < 0.6 ? '#16a34a' : '#fef08a')),
                        life: 0.65 + Math.random() * 0.35,
                        decay: 0.024
                    });
                }
            }
        });
    }

    function updateSakuraBamboos() {
        if (!currentLevelData || !currentLevelData.bamboos) return;
        currentLevelData.bamboos.forEach(bam => {
            if (!bam.isCut) return;
            bam.cutTimer = (bam.cutTimer || 0) + 0.016;
            if (bam.alpha <= 0) return;

            if (bam.cutTimer < 0.07) {
                // Classic samurai iaijutsu clean diagonal slide right after the cleave
                bam.fallX += bam.cutDir * 1.1;
                bam.fallY += 0.45;
            } else {
                bam.fallVy += 0.38;
                bam.fallX += bam.fallVx;
                bam.fallY += bam.fallVy;
                bam.fallAngle += bam.fallAngVel;
                if (bam.cutTimer > 0.38) {
                    bam.alpha = Math.max(0, bam.alpha - 0.032);
                }
            }
        });
    }

    function drawSakuraBamboo(bam, scale) {
        const drawX = (bam.x - cameraX) * scale;
        const baseY = (bam.y - cameraY) * scale;
        const w = (bam.w || 46) * scale;
        const topWorldY = -350;
        const topY = (topWorldY - cameraY) * scale;

        if (drawX + w * 2.5 < -140 || drawX - w * 2.5 > canvas.width + 140) return;

        // 4 dense bamboo stalks forming an impassable thicket
        const stalks = [
            { ox: -0.34, thick: 11, main: '#15803d', light: '#4ade80', dark: '#14532d', sway: 0.8 },
            { ox: -0.11, thick: 13, main: '#16a34a', light: '#86efac', dark: '#166534', sway: -0.6 },
            { ox: 0.13, thick: 12, main: '#15803d', light: '#4ade80', dark: '#14532d', sway: 0.9 },
            { ox: 0.35, thick: 10.5, main: '#22c55e', light: '#bbf7d0', dark: '#15803d', sway: -0.7 }
        ];

        const drawBambooCluster = (yStart, yEnd, includeCutBevel, bevelAtTop) => {
            const segH = 38 * scale;
            const time = Date.now() * 0.0022;

            stalks.forEach((st, idx) => {
                const sx = drawX + st.ox * w;
                const stW = st.thick * scale;
                const halfStW = stW * 0.5;
                const slant = (bam.cutDir || 1) * 5 * scale;

                // Stalk body gradient
                const grad = ctx.createLinearGradient(sx - halfStW, 0, sx + halfStW, 0);
                grad.addColorStop(0, st.dark);
                grad.addColorStop(0.35, st.main);
                grad.addColorStop(0.68, st.light);
                grad.addColorStop(1, st.dark);

                ctx.fillStyle = grad;
                ctx.beginPath();
                if (includeCutBevel && bevelAtTop) {
                    ctx.moveTo(sx - halfStW, yStart + slant);
                    ctx.lineTo(sx + halfStW, yStart - slant);
                    ctx.lineTo(sx + halfStW, yEnd);
                    ctx.lineTo(sx - halfStW, yEnd);
                } else if (includeCutBevel && !bevelAtTop) {
                    ctx.moveTo(sx - halfStW, yStart);
                    ctx.lineTo(sx + halfStW, yStart);
                    ctx.lineTo(sx + halfStW, yEnd - slant);
                    ctx.lineTo(sx - halfStW, yEnd + slant);
                } else {
                    ctx.rect(sx - halfStW, yStart, stW, yEnd - yStart);
                }
                ctx.closePath();
                ctx.fill();

                ctx.strokeStyle = '#052e16';
                ctx.lineWidth = 1.2 * scale;
                ctx.stroke();

                // Bamboo internode rings & swaying bamboo leaves
                const firstNode = yEnd - ((yEnd - yStart) % segH) + segH * 0.5;
                for (let ny = yEnd - (18 + (idx % 2) * 14) * scale; ny > yStart + 10 * scale; ny -= segH) {
                    // Pale cream/dark bamboo joint ring
                    ctx.strokeStyle = '#052e16';
                    ctx.lineWidth = 2.4 * scale;
                    ctx.beginPath();
                    ctx.moveTo(sx - halfStW - 1 * scale, ny);
                    ctx.lineTo(sx + halfStW + 1 * scale, ny);
                    ctx.stroke();

                    ctx.strokeStyle = '#dcfce7';
                    ctx.lineWidth = 1.3 * scale;
                    ctx.beginPath();
                    ctx.moveTo(sx - halfStW, ny - 1.5 * scale);
                    ctx.lineTo(sx + halfStW, ny - 1.5 * scale);
                    ctx.stroke();

                    // Sprouting bamboo leaves on alternating nodes above player head
                    if (((Math.round(ny / segH) + idx) % 2 === 0) && ny < baseY - 68 * scale) {
                        const leafSide = (idx % 2 === 0) ? -1 : 1;
                        const leafSway = Math.sin(time + idx + ny * 0.01) * 0.14;
                        ctx.save();
                        ctx.translate(sx + leafSide * halfStW, ny);
                        ctx.rotate(leafSide * 0.55 + leafSway);
                        ctx.fillStyle = idx % 2 === 0 ? '#16a34a' : '#22c55e';
                        ctx.beginPath();
                        ctx.ellipse(leafSide * 12 * scale, -2 * scale, 13 * scale, 3.6 * scale, leafSide * -0.25, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.fillStyle = '#4ade80';
                        ctx.beginPath();
                        ctx.ellipse(leafSide * 10 * scale, 4 * scale, 10 * scale, 2.8 * scale, leafSide * 0.25, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.restore();
                    }
                }

                // Fresh pale hollow bamboo cut bevel surface
                if (includeCutBevel) {
                    const cutEdgeY = bevelAtTop ? yStart : yEnd;
                    ctx.fillStyle = '#fef08a';
                    ctx.strokeStyle = '#65a30d';
                    ctx.lineWidth = 1.4 * scale;
                    ctx.beginPath();
                    ctx.ellipse(sx, cutEdgeY, halfStW * 1.04, 3.8 * scale, -(bam.cutDir || 1) * 0.35, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();
                    // Hollow core
                    ctx.fillStyle = '#a3e635';
                    ctx.beginPath();
                    ctx.ellipse(sx, cutEdgeY, halfStW * 0.52, 1.8 * scale, -(bam.cutDir || 1) * 0.35, 0, Math.PI * 2);
                    ctx.fill();
                }
            });
        };

        ctx.save();
        // Ground/roof shadow under the bamboo thicket
        ctx.fillStyle = 'rgba(2, 6, 23, 0.35)';
        ctx.beginPath();
        ctx.ellipse(drawX, baseY + 1 * scale, w * 0.62, 5 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        if (!bam.isCut) {
            // Intact full-height bamboo wall
            drawBambooCluster(topY, baseY, false, false);

            // Traditional crimson binding cord near base
            ctx.fillStyle = '#b91c1c';
            ctx.fillRect(drawX - w * 0.5, baseY - 22 * scale, w, 6 * scale);
            ctx.strokeStyle = '#fbbf24';
            ctx.lineWidth = 1.4 * scale;
            ctx.strokeRect(drawX - w * 0.5, baseY - 22 * scale, w, 6 * scale);

            // Subtle shimmering diagonal katana cut-guide when the player approaches
            const distToPlayer = Math.abs(player.x - bam.x);
            if (distToPlayer < 210 && player.y <= bam.y + 30) {
                const pulse = 0.45 + 0.45 * Math.sin(Date.now() * 0.01);
                const markY = baseY - 46 * scale;
                ctx.save();
                ctx.strokeStyle = `rgba(254, 240, 138, ${pulse})`;
                ctx.shadowColor = '#f472b6';
                ctx.shadowBlur = 10 * scale;
                ctx.lineWidth = 2.6 * scale;
                ctx.setLineDash([6 * scale, 4 * scale]);
                ctx.beginPath();
                ctx.moveTo(drawX - w * 0.62, markY + 14 * scale);
                ctx.lineTo(drawX + w * 0.62, markY - 14 * scale);
                ctx.stroke();
                ctx.setLineDash([]);
                ctx.restore();
            }
        } else {
            const cutScreenY = ((bam.cutY || (bam.y - 46)) - cameraY) * scale;

            // 1. Stationary freshly-sliced bottom stumps
            drawBambooCluster(cutScreenY, baseY, true, true);

            // Crimson binding cord remains around stumps
            ctx.fillStyle = '#b91c1c';
            ctx.fillRect(drawX - w * 0.5, baseY - 22 * scale, w, 6 * scale);

            // 2. Toppling severed upper bamboo section
            if ((bam.alpha || 0) > 0.01) {
                ctx.save();
                ctx.globalAlpha = bam.alpha;
                ctx.translate(drawX + (bam.fallX || 0) * scale, cutScreenY + (bam.fallY || 0) * scale);
                ctx.rotate(bam.fallAngle || 0);
                ctx.translate(-drawX, -cutScreenY);
                drawBambooCluster(topY, cutScreenY, true, false);
                ctx.restore();
            }

            // 3. Crisp bright samurai cleave flash line right on cut impact
            if ((bam.cutTimer || 0) < 0.16) {
                const flashAlpha = 1 - (bam.cutTimer / 0.16);
                ctx.save();
                ctx.strokeStyle = `rgba(255, 255, 255, ${flashAlpha})`;
                ctx.shadowColor = '#f472b6';
                ctx.shadowBlur = 16 * scale;
                ctx.lineWidth = (5.5 * flashAlpha) * scale;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(drawX - w * 1.1, cutScreenY + 24 * scale * (bam.cutDir || 1));
                ctx.lineTo(drawX + w * 1.1, cutScreenY - 24 * scale * (bam.cutDir || 1));
                ctx.stroke();
                ctx.restore();
            }
        }
        ctx.restore();
    }

    // ==========================================
    // --- LEVEL 60: BOSS YETI SYSTEM ---
    // ==========================================
    const yeti = {
        active: false,
        health: 250,
        maxHealth: 250,
        x: 19000,
        y: 440,
        baseY: 440,
        w: 130,
        h: 150,
        state: 'INACTIVE', // 'INTRO', 'IDLE', 'ICE_BOULDER_FORM', 'ICE_BOULDER_THROW', 'AVALANCHE_WINDUP', 'AVALANCHE_SURGE', 'GIANT_SNOWBALLS_PREP', 'GIANT_SNOWBALLS_ROLL', 'DEFEATED'
        timer: 0,
        attackIndex: 0,
        attackList: ['ICE_BOULDER', 'AVALANCHE', 'GIANT_SNOWBALLS'],
        hitFlashTimer: 0,
        eyeGlow: 1.0,
        isFallen: false,
        fallAngle: 0,
        arenaLeft: 17620,
        arenaRight: 19550,
        introPlayed: false,
        shoveTimer: 0,
        roarArms: 0,
        mouthOpen: 0,
        roarShockwaves: [],
        lastDefeatReason: '', // 'BOULDER', 'AVALANCHE', 'SNOWBALL'

        // Attack 1: Ice Boulder
        iceBoulderFormProg: 0,
        iceBoulderTarget: null, // { x, y, timer: 1.0, radius: 110 }
        iceBoulderBomb: null,   // { thrown, x, y, startX, startY, targetX, targetY, progress, radius, rot }

        // Attack 2: Avalanche
        avalancheWave: null,    // { x, y, w, h, vx, progress, active, sweptPlayer }

        // Attack 3: Giant Snowballs
        giantSnowballs: [],     // [{ x, y, radius, vx, rot, active, clearedPlayer }]
        giantSnowballQueue: 0,
        giantSnowballTimer: 0,

        // Win Mechanic: Snowballs & Dropped Stones
        arenaStones: [],        // [{ id, x, y, bobTimer }]
        playerSnowballs: []     // [{ x, y, startX, startY, targetX, targetY, t, rot, isStone, damage }]
    };

    const yetiIntroCutscene = {
        active: false,
        phase: 'NONE', // 'APPROACH', 'EYES', 'EMERGE', 'ROAR'
        timer: 0,
        rumbleInterval: 0,
        eyeAlpha: 0
    };

    const yetiDefeatCutscene = {
        active: false,
        phase: 'NONE',
        timer: 0,
        confetti: []
    };

    function startYetiIntroCutscene() {
        if (yeti.introPlayed || yetiIntroCutscene.active || yeti.active || yeti.isFallen) return;
        currentState = STATES.CUTSCENE;
        yetiIntroCutscene.active = true;
        yetiIntroCutscene.phase = 'APPROACH';
        yetiIntroCutscene.timer = 0;
        yetiIntroCutscene.rumbleInterval = 0;
        yetiIntroCutscene.eyeAlpha = 0;

        // Cold bar is completely removed and cold ceases to affect the player
        if (coldHud) coldHud.classList.add('hidden');
        player.cold = 0;

        yeti.x = 19300; // Deep inside the dark cave interior
        yeti.y = currentLevelData.groundY - 75;
        yeti.baseY = currentLevelData.groundY - 75;
        yeti.shoveTimer = 0;
        yeti.roarArms = 0;
        yeti.mouthOpen = 0;
        yeti.roarShockwaves = [];
        yeti.eyeGlow = 0;
        yeti.state = 'INACTIVE';

        player.state = 'RUN';
        player.facing = 1;
        player.grounded = true;
        player.y = currentLevelData.groundY;
        player.vy = 0;
        player.vx = 3.6;

        if (bossHud) bossHud.classList.add('hidden');
        if (cutsceneOverlay) cutsceneOverlay.classList.remove('hidden');
        if (cutsceneChapter) cutsceneChapter.textContent = '❄️ УРОВЕНЬ 60: ТАИНСТВЕННАЯ ЛЕДЯНАЯ ПЕЩЕРА';
        if (cutsceneText) cutsceneText.textContent = 'Стикмен подходит ближе к древней заснеженной пещере...';

        playSound('coldWind');
    }

    function updateYetiIntroCutscene() {
        yetiIntroCutscene.timer += 0.016;

        // Update roar shockwaves
        for (let i = yeti.roarShockwaves.length - 1; i >= 0; i--) {
            const sw = yeti.roarShockwaves[i];
            sw.radius += 16;
            sw.alpha -= 0.022;
            if (sw.alpha <= 0 || sw.radius >= sw.maxRadius) {
                yeti.roarShockwaves.splice(i, 1);
            }
        }

        if (yetiIntroCutscene.phase === 'APPROACH') {
            player.x += player.vx;
            player.y = currentLevelData.groundY;
            player.grounded = true;
            const targetCamX = Math.min(yeti.arenaLeft + 80, player.x - 260);
            cameraX += (targetCamX - cameraX) * 0.08;

            if (player.x >= 18650) {
                player.vx = 0;
                player.state = 'IDLE';
                yetiIntroCutscene.phase = 'EYES';
                yetiIntroCutscene.timer = 0;
                if (cutsceneChapter) cutsceneChapter.textContent = '❄️ ЛЕДЯНАЯ ПЕЩЕРА: СИЯЮЩИЕ ГЛАЗА';
                if (cutsceneText) cutsceneText.textContent = 'В непроглядной тьме пещеры загораются зловещие синие глаза!';
                playSound('freeze');
                screenShake = 6;
            }
        } else if (yetiIntroCutscene.phase === 'EYES') {
            player.y = currentLevelData.groundY;
            player.grounded = true;
            const targetCamX = 18450;
            cameraX += (targetCamX - cameraX) * 0.05;

            yetiIntroCutscene.eyeAlpha = Math.min(1.0, yetiIntroCutscene.timer / 0.8);
            yeti.eyeGlow = yetiIntroCutscene.eyeAlpha;

            if (Math.random() < 0.6) {
                particles.push({
                    x: yeti.x + (Math.random() - 0.5) * 50,
                    y: yeti.y - 45 + (Math.random() - 0.5) * 35,
                    vx: -(2 + Math.random() * 4),
                    vy: (Math.random() - 0.5) * 2,
                    size: 4 + Math.random() * 7,
                    color: Math.random() < 0.6 ? '#38bdf8' : '#e0f2fe',
                    life: 0.8,
                    decay: 0.03
                });
            }

            if (yetiIntroCutscene.timer >= 2.2) {
                yetiIntroCutscene.phase = 'EMERGE';
                yetiIntroCutscene.timer = 0;
                if (cutsceneChapter) cutsceneChapter.textContent = '❄️ ПРОБУЖДЕНИЕ: ВЫХОД ЙЕТИ';
                if (cutsceneText) cutsceneText.textContent = 'Из глубин пещеры величественно выходит исполинский Снежный Йети!';
                playSound('slam');
                screenShake = 14;
            }
        } else if (yetiIntroCutscene.phase === 'EMERGE') {
            player.y = currentLevelData.groundY;
            player.grounded = true;
            const emergeProgress = Math.min(1.0, yetiIntroCutscene.timer / 2.0);
            yeti.x = 19300 - emergeProgress * 300;
            yeti.eyeGlow = 1.0;

            const targetCamX = 18480;
            cameraX += (targetCamX - cameraX) * 0.05;

            if (Math.random() < 0.4) {
                spawnDust(yeti.x, currentLevelData.groundY);
            }

            if (yetiIntroCutscene.timer >= 2.0) {
                yetiIntroCutscene.phase = 'ROAR';
                yetiIntroCutscene.timer = 0;
                yeti.x = 19000;
                if (cutsceneChapter) cutsceneChapter.textContent = '❄️ МОГУЧИЙ РЁВ ЙЕТИ';
                if (cutsceneText) cutsceneText.textContent = 'Йети издает оглушительный морозный рёв! Начинается битва!';
                playSound('yetiRoar');
                playSound('slam');
                screenShake = 26;

                yeti.roarShockwaves.push({
                    x: yeti.x,
                    y: yeti.y - 45,
                    radius: 20,
                    maxRadius: 420,
                    alpha: 0.95
                });
            }
        } else if (yetiIntroCutscene.phase === 'ROAR') {
            yeti.roarArms = Math.min(1.0, yeti.roarArms + 0.08);
            yeti.mouthOpen = Math.min(1.0, yeti.mouthOpen + 0.09);
            screenShake = Math.max(screenShake, 16);

            if (yetiIntroCutscene.timer > 0.4 && yeti.roarShockwaves.length < 3) {
                yeti.roarShockwaves.push({
                    x: yeti.x,
                    y: yeti.y - 45,
                    radius: 20,
                    maxRadius: 420,
                    alpha: 0.9
                });
            }

            for (let k = 0; k < 3; k++) {
                particles.push({
                    x: yeti.x - 30,
                    y: yeti.y - 50 + (Math.random() - 0.5) * 30,
                    vx: -(7 + Math.random() * 9),
                    vy: (Math.random() - 0.5) * 6,
                    size: 3 + Math.random() * 5,
                    color: Math.random() < 0.5 ? '#ffffff' : '#38bdf8',
                    life: 0.9,
                    decay: 0.03
                });
            }

            if (yetiIntroCutscene.timer >= 2.2) {
                finishYetiIntroCutscene();
            }
        }
    }

    function finishYetiIntroCutscene() {
        if (!yetiIntroCutscene.active) return;
        yetiIntroCutscene.active = false;
        yeti.introPlayed = true;
        yeti.x = 19000;
        yeti.roarArms = 0;
        yeti.mouthOpen = 0;
        yeti.eyeGlow = 1.0;

        player.state = 'IDLE';
        player.vx = 0;
        player.vy = 0;
        player.facing = 1;
        player.grounded = true;
        player.y = currentLevelData.groundY;
        player.cold = 0;

        if (cutsceneOverlay) cutsceneOverlay.classList.add('hidden');
        if (hudOverlay) hudOverlay.classList.remove('hidden');
        if (coldHud) coldHud.classList.add('hidden');

        currentState = STATES.PLAYING;
        startYetiFight();
    }

    function startYetiFight() {
        if (yeti.active) return;
        yeti.active = true;
        yeti.health = 250;
        yeti.maxHealth = 250;
        yeti.x = 19000;
        yeti.y = currentLevelData.groundY - 75;
        yeti.baseY = currentLevelData.groundY - 75;
        yeti.state = 'IDLE';
        yeti.timer = 0;
        yeti.attackIndex = 0;
        yeti.hitFlashTimer = 0;
        yeti.eyeGlow = 1.0;
        yeti.isFallen = false;
        yeti.fallAngle = 0;
        yeti.mouthOpen = 0;
        yeti.roarArms = 0;
        yeti.shoveTimer = 0;
        yeti.lastDefeatReason = '';
        yeti.iceBoulderTarget = null;
        yeti.iceBoulderBomb = null;
        yeti.avalancheWave = null;
        yeti.giantSnowballs = [];
        yeti.arenaStones = [];
        yeti.playerSnowballs = [];

        player.isBossMode = false;
        player.cold = 0;
        player.hasStone = false;
        player.snowballCooldown = 0;

        if (coldHud) coldHud.classList.add('hidden');

        if (bossHud) {
            bossHud.classList.remove('hidden');
        }
        if (bossName) {
            bossName.textContent = '❄️ ДРЕВНИЙ СНЕЖНЫЙ ЙЕТИ';
        }
        if (bossHealthBar) {
            bossHealthBar.style.width = '100%';
            bossHealthBar.style.background = 'linear-gradient(90deg, #0284c7 0%, #38bdf8 50%, #e0f2fe 100%)';
        }
        if (bossPhaseText) {
            bossPhaseText.textContent = 'БОСС: 250 / 250 | [E / Клик] Слепить снежок!';
        }

        playSound('slam');
        screenShake = 16;
        spawnDust(yeti.x, currentLevelData.groundY);
    }

    function resetYeti() {
        yeti.active = false;
        yeti.health = 250;
        yeti.state = 'INACTIVE';
        yeti.timer = 0;
        yeti.attackIndex = 0;
        yeti.hitFlashTimer = 0;
        yeti.eyeGlow = 1.0;
        yeti.isFallen = false;
        yeti.fallAngle = 0;
        yeti.mouthOpen = 0;
        yeti.roarArms = 0;
        yeti.shoveTimer = 0;
        yeti.introPlayed = false;
        yeti.lastDefeatReason = '';
        yeti.iceBoulderTarget = null;
        yeti.iceBoulderBomb = null;
        yeti.avalancheWave = null;
        yeti.giantSnowballs = [];
        yeti.arenaStones = [];
        yeti.playerSnowballs = [];
        yetiIntroCutscene.active = false;
        yetiIntroCutscene.phase = 'NONE';
        yetiDefeatCutscene.active = false;
        yetiDefeatCutscene.phase = 'NONE';

        player.hasStone = false;
        player.snowballCooldown = 0;

        if (currentLevelIndex === 60 && bossHud) {
            bossHud.classList.add('hidden');
        }
    }

    function playerThrowSnowball() {
        if (!yeti.active || yeti.health <= 0 || player.state === 'DEFEAT') return;
        if (player.snowballCooldown && player.snowballCooldown > 0) return;

        player.snowballCooldown = 0.38;
        const hasStone = !!player.hasStone;
        player.hasStone = false;

        const dmg = hasStone ? 10 : 5;
        const startX = player.facing >= 0 ? player.x + 16 : player.x - 16;
        const startY = player.y - 38;

        yeti.playerSnowballs.push({
            x: startX,
            y: startY,
            startX: startX,
            startY: startY,
            targetX: yeti.x + (Math.random() - 0.5) * 30,
            targetY: yeti.y - 45 + (Math.random() - 0.5) * 30,
            t: 0,
            rot: 0,
            isStone: hasStone,
            damage: dmg
        });

        playSound('snowCraft');
        playSound('airBoost');

        for (let k = 0; k < 6; k++) {
            particles.push({
                x: startX + (Math.random() - 0.5) * 12,
                y: currentLevelData.groundY - 5,
                vx: (Math.random() - 0.5) * 3,
                vy: -Math.random() * 3.5 - 1,
                size: 2.5 + Math.random() * 3,
                color: hasStone ? '#64748b' : '#ffffff',
                life: 0.5,
                decay: 0.05
            });
        }
    }

    function updateYeti() {
        if (!yeti.active) return;
        if (player.state === 'DEFEAT') return;

        // Keep player strictly bounded within Yeti arena
        if (player.x < yeti.arenaLeft + 30) {
            player.x = yeti.arenaLeft + 30;
            if (player.vx < 0) player.vx = 0;
        }
        if (player.x > yeti.arenaRight - 30) {
            player.x = yeti.arenaRight - 30;
            if (player.vx > 0) player.vx = 0;
        }

        yeti.timer += 0.016;
        if (yeti.hitFlashTimer > 0) yeti.hitFlashTimer -= 0.016;
        if (yeti.shoveTimer > 0) yeti.shoveTimer -= 0.016;
        if (player.snowballCooldown > 0) player.snowballCooldown -= 0.016;

        // Screen shake decay
        if (screenShake > 0) {
            screenShake *= 0.88;
            if (screenShake < 0.2) screenShake = 0;
        }

        // 1. Arena Stones Collection (dropped from ice boulder)
        for (let i = yeti.arenaStones.length - 1; i >= 0; i--) {
            const st = yeti.arenaStones[i];
            st.bobTimer += 0.05;
            if (Math.abs(player.x - st.x) < 40 && player.y >= currentLevelData.groundY - 45) {
                player.hasStone = true;
                yeti.arenaStones.splice(i, 1);
                playSound('warmUp');
                playSound('land');
                spawnDust(st.x, currentLevelData.groundY);

                if (bossPhaseText) {
                    bossPhaseText.textContent = `БОСС: ${yeti.health} / 250 | 🪨 Снежок с камнем готов! (10 урона)`;
                }
            }
        }

        // 2. Update Thrown Player Snowballs
        for (let i = yeti.playerSnowballs.length - 1; i >= 0; i--) {
            const pb = yeti.playerSnowballs[i];
            pb.t += 0.062;
            pb.rot += 0.25;
            pb.x = pb.startX + (pb.targetX - pb.startX) * pb.t;
            pb.y = pb.startY + (pb.targetY - pb.startY) * pb.t - Math.sin(pb.t * Math.PI) * 75;

            // Trail particles
            if (Math.random() < 0.5) {
                particles.push({
                    x: pb.x,
                    y: pb.y,
                    vx: (Math.random() - 0.5) * 1.5,
                    vy: (Math.random() - 0.5) * 1.5,
                    size: 2 + Math.random() * 2.5,
                    color: pb.isStone ? '#94a3b8' : '#ffffff',
                    life: 0.35,
                    decay: 0.07
                });
            }

            if (pb.t >= 1.0) {
                // Impact on Yeti!
                yeti.playerSnowballs.splice(i, 1);
                yeti.health = Math.max(0, yeti.health - pb.damage);
                yeti.hitFlashTimer = 0.22;
                screenShake = pb.isStone ? 8 : 4;
                playSound(pb.isStone ? 'rockHit' : 'snowHit');

                // Burst particles at impact spot
                for (let k = 0; k < (pb.isStone ? 12 : 8); k++) {
                    particles.push({
                        x: yeti.x + (Math.random() - 0.5) * 40,
                        y: yeti.y - 40 + (Math.random() - 0.5) * 40,
                        vx: (Math.random() - 0.5) * 7,
                        vy: (Math.random() - 0.5) * 7,
                        size: 3 + Math.random() * 4,
                        color: pb.isStone ? (Math.random() < 0.5 ? '#64748b' : '#e0f2fe') : '#ffffff',
                        life: 0.7,
                        decay: 0.04
                    });
                }

                if (bossHealthBar) {
                    bossHealthBar.style.width = Math.max(0, (yeti.health / yeti.maxHealth) * 100) + '%';
                }
                if (bossPhaseText) {
                    bossPhaseText.textContent = `БОСС: ${yeti.health} / 250 | ` + (player.hasStone ? '🪨 Снежок с камнем (10 урона)' : '❄️ Снежок (5 урона) [E/Клик]');
                }

                if (yeti.health <= 0) {
                    startYetiDefeatCutscene();
                    return;
                }
            }
        }

        // 3. Attack State Machine
        if (yeti.state === 'IDLE') {
            yeti.y = yeti.baseY + Math.sin(Date.now() * 0.003) * 4;
            if (yeti.timer >= 1.15) {
                const nextAttack = yeti.attackList[yeti.attackIndex % yeti.attackList.length];
                yeti.timer = 0;

                if (nextAttack === 'ICE_BOULDER') {
                    yeti.state = 'ICE_BOULDER_FORM';
                    const targetX = Math.max(yeti.arenaLeft + 80, Math.min(yeti.arenaRight - 150, player.x));
                    yeti.iceBoulderTarget = { x: targetX, y: currentLevelData.groundY, timer: 1.0, radius: 110 };
                    playSound('warning');
                } else if (nextAttack === 'AVALANCHE') {
                    yeti.state = 'AVALANCHE_WINDUP';
                    playSound('coldWind');
                    screenShake = 6;
                } else if (nextAttack === 'GIANT_SNOWBALLS') {
                    yeti.state = 'GIANT_SNOWBALLS_PREP';
                    yeti.giantSnowballQueue = 3;
                    yeti.giantSnowballTimer = 0;
                    playSound('warning');
                }
            }
            return;
        }

        // --- ATTACK 1: ICE BOULDER (Глыбы льда из рук) ---
        if (yeti.state === 'ICE_BOULDER_FORM') {
            yeti.iceBoulderFormProg = Math.min(1.0, yeti.timer / 1.0);
            if (yeti.timer >= 1.0) {
                yeti.state = 'ICE_BOULDER_THROW';
                yeti.timer = 0;
                yeti.iceBoulderBomb = {
                    thrown: true,
                    x: yeti.x - 35,
                    y: yeti.y - 70,
                    startX: yeti.x - 35,
                    startY: yeti.y - 70,
                    targetX: yeti.iceBoulderTarget ? yeti.iceBoulderTarget.x : player.x,
                    targetY: currentLevelData.groundY - 15,
                    progress: 0,
                    radius: 36,
                    rot: 0
                };
                playSound('airBoost');
            }
            return;
        }

        if (yeti.state === 'ICE_BOULDER_THROW') {
            if (!yeti.iceBoulderBomb) {
                yeti.state = 'IDLE';
                yeti.timer = 0;
                return;
            }
            const bomb = yeti.iceBoulderBomb;
            bomb.progress += 0.016 / 0.58; // flight time
            const p = Math.min(1.0, bomb.progress);
            bomb.x = bomb.startX + (bomb.targetX - bomb.startX) * p;
            bomb.y = bomb.startY + (bomb.targetY - bomb.startY) * p - Math.sin(p * Math.PI) * 140;
            bomb.rot += 0.12;

            if (Math.abs(player.x - bomb.x) < 36 && Math.abs(player.y - bomb.y) < 36) {
                yeti.lastDefeatReason = 'BOULDER';
                triggerDefeat();
                return;
            }

            if (bomb.progress >= 1.0) {
                const hitX = bomb.targetX;
                bomb.x = hitX;
                bomb.y = currentLevelData.groundY - 15;

                // Ground damage check within large warning radius (110px)
                if (Math.abs(player.x - hitX) < 110 && player.y >= currentLevelData.groundY - 45) {
                    yeti.lastDefeatReason = 'BOULDER';
                    triggerDefeat();
                }

                playSound('slam');
                playSound('crack');
                screenShake = 22;
                spawnDust(hitX, currentLevelData.groundY);

                // Ice shards explosion
                for (let k = 0; k < 22; k++) {
                    particles.push({
                        x: hitX + (Math.random() - 0.5) * 35,
                        y: currentLevelData.groundY - 10,
                        vx: (Math.random() - 0.5) * 14,
                        vy: -(3 + Math.random() * 9),
                        size: 4 + Math.random() * 6,
                        color: Math.random() < 0.5 ? '#38bdf8' : '#e0f2fe',
                        life: 0.8,
                        decay: 0.03
                    });
                }

                // Shatters and drops 1 to 2 pickable stones on the ground
                const dropCount = Math.random() < 0.6 ? 2 : 1;
                for (let s = 0; s < dropCount; s++) {
                    const offset = (s === 0 ? -1 : 1) * (70 + Math.random() * 80);
                    const stoneX = Math.max(yeti.arenaLeft + 70, Math.min(yeti.x - 100, hitX + offset));
                    yeti.arenaStones.push({
                        id: Math.random(),
                        x: stoneX,
                        y: currentLevelData.groundY,
                        bobTimer: Math.random() * Math.PI * 2
                    });
                }

                yeti.iceBoulderBomb = null;
                yeti.iceBoulderTarget = null;
                yeti.attackIndex++;
                yeti.state = 'IDLE';
                yeti.timer = 0;
            }
            return;
        }

        // --- ATTACK 2: AVALANCHE (Лавина - волна снега) ---
        if (yeti.state === 'AVALANCHE_WINDUP') {
            screenShake = Math.max(screenShake, 5);
            if (yeti.timer >= 0.8) {
                yeti.state = 'AVALANCHE_SURGE';
                yeti.timer = 0;
                yeti.avalancheWave = {
                    x: yeti.x - 45,
                    y: currentLevelData.groundY - 65,
                    w: 160,
                    h: 70,
                    vx: -14,
                    active: true,
                    sweptPlayer: false
                };
                playSound('yetiRoar');
                playSound('coldWind');
                screenShake = 16;
            }
            return;
        }

        if (yeti.state === 'AVALANCHE_SURGE') {
            if (!yeti.avalancheWave) {
                yeti.state = 'IDLE';
                yeti.timer = 0;
                return;
            }
            const wave = yeti.avalancheWave;
            wave.x += wave.vx;
            screenShake = Math.max(screenShake, 4);

            // Spray blizzard particles from surging wave
            if (Math.random() < 0.7) {
                particles.push({
                    x: wave.x + (Math.random() - 0.5) * 40,
                    y: currentLevelData.groundY - 20 - Math.random() * 45,
                    vx: -(4 + Math.random() * 8),
                    vy: -(1 + Math.random() * 4),
                    size: 3 + Math.random() * 5,
                    color: Math.random() < 0.5 ? '#ffffff' : '#bae6fd',
                    life: 0.5,
                    decay: 0.05
                });
            }

            // Dodge check: Player must crouch or slide to avoid the avalanche!
            if (Math.abs(player.x - wave.x) < 55 && !wave.sweptPlayer) {
                const isDucking = player.isCrouching || player.state === 'ROLL';
                if (!isDucking) {
                    wave.sweptPlayer = true;
                    yeti.lastDefeatReason = 'AVALANCHE';
                    triggerDefeat();
                    return;
                } else {
                    // Harmless snow spray over ducking player
                    for (let s = 0; s < 4; s++) {
                        particles.push({
                            x: player.x + (Math.random() - 0.5) * 20,
                            y: player.y - 30,
                            vx: -(3 + Math.random() * 4),
                            vy: -(2 + Math.random() * 3),
                            size: 2.5 + Math.random() * 3,
                            color: '#e0f2fe',
                            life: 0.4,
                            decay: 0.06
                        });
                    }
                }
            }

            if (wave.x <= yeti.arenaLeft - 50) {
                yeti.avalancheWave = null;
                yeti.attackIndex++;
                yeti.state = 'IDLE';
                yeti.timer = 0;
            }
            return;
        }

        // --- ATTACK 3: GIANT SNOWBALLS (Огромные снежки) ---
        if (yeti.state === 'GIANT_SNOWBALLS_PREP') {
            yeti.giantSnowballTimer += 0.016;

            if (yeti.giantSnowballQueue > 0 && yeti.giantSnowballTimer >= 1.05) {
                yeti.giantSnowballTimer = 0;
                yeti.giantSnowballQueue--;
                yeti.giantSnowballs.push({
                    x: yeti.x - 45,
                    y: currentLevelData.groundY - 34,
                    radius: 34,
                    vx: -8.8,
                    rot: 0,
                    active: true,
                    clearedPlayer: false
                });
                playSound('slam');
                playSound('airBoost');
                screenShake = 9;
            }

            // Update active rolling giant snowballs
            for (let i = yeti.giantSnowballs.length - 1; i >= 0; i--) {
                const sb = yeti.giantSnowballs[i];
                sb.x += sb.vx;
                sb.rot += sb.vx * 0.035;

                // Snow dust trail
                if (Math.random() < 0.45) {
                    particles.push({
                        x: sb.x + 20,
                        y: currentLevelData.groundY - 5,
                        vx: 1 + Math.random() * 3,
                        vy: -Math.random() * 3,
                        size: 3 + Math.random() * 3,
                        color: '#f8fafc',
                        life: 0.45,
                        decay: 0.06
                    });
                }

                // Dodge check: Player must jump over them!
                if (Math.abs(player.x - sb.x) < 32 && sb.active) {
                    const isJumpedOver = (player.y < currentLevelData.groundY - 48);
                    if (!isJumpedOver) {
                        yeti.lastDefeatReason = 'SNOWBALL';
                        triggerDefeat();
                        return;
                    } else {
                        sb.clearedPlayer = true;
                    }
                }

                if (sb.x <= yeti.arenaLeft - 20) {
                    playSound('snowHit');
                    for (let k = 0; k < 12; k++) {
                        particles.push({
                            x: yeti.arenaLeft,
                            y: currentLevelData.groundY - 20 + (Math.random() - 0.5) * 30,
                            vx: 2 + Math.random() * 5,
                            vy: -(2 + Math.random() * 5),
                            size: 3 + Math.random() * 4,
                            color: '#ffffff',
                            life: 0.6,
                            decay: 0.04
                        });
                    }
                    yeti.giantSnowballs.splice(i, 1);
                }
            }

            if (yeti.giantSnowballQueue <= 0 && yeti.giantSnowballs.length === 0) {
                yeti.attackIndex++;
                yeti.state = 'IDLE';
                yeti.timer = 0;
            }
            return;
        }
    }

    // ==========================================
    // --- YETI DEFEAT CUTSCENE & VICTORY ---
    // ==========================================
    function startYetiDefeatCutscene() {
        if (yetiDefeatCutscene.active || yeti.isFallen) return;
        currentState = STATES.CUTSCENE;
        yetiDefeatCutscene.active = true;
        yetiDefeatCutscene.phase = 'ROAR_FALL';
        yetiDefeatCutscene.timer = 0;

        yeti.state = 'DEFEATED';
        yeti.isFallen = true;
        yeti.fallAngle = 0;
        yeti.shoveTimer = 0;
        yeti.iceBoulderTarget = null;
        yeti.iceBoulderBomb = null;
        yeti.avalancheWave = null;
        yeti.giantSnowballs = [];

        player.state = 'IDLE';
        player.vx = 0;
        player.vy = 0;

        if (bossHud) bossHud.classList.add('hidden');
        if (cutsceneOverlay) cutsceneOverlay.classList.remove('hidden');
        if (cutsceneChapter) cutsceneChapter.textContent = '🏆 ПОБЕДА: СОКРУШЕНИЕ ВЕЛИКОГО ЙЕТИ';
        if (cutsceneText) cutsceneText.textContent = 'Могучий Йети повержен снежками и падает в мягкий снег!';

        playSound('yetiRoar');
        playSound('victoryFanfare');
        screenShake = 20;

        // Sparkling celebratory snow particles
        for (let i = 0; i < 60; i++) {
            yetiDefeatCutscene.confetti.push({
                x: yeti.x + (Math.random() - 0.5) * 120,
                y: yeti.y - 60 + (Math.random() - 0.5) * 80,
                vx: (Math.random() - 0.5) * 8,
                vy: -(3 + Math.random() * 8),
                size: 3 + Math.random() * 5,
                color: ['#38bdf8', '#0284c7', '#ffffff', '#fbbf24', '#facc15'][Math.floor(Math.random() * 5)],
                rot: Math.random() * Math.PI * 2,
                rotSpeed: (Math.random() - 0.5) * 0.2
            });
        }
    }

    function updateYetiDefeatCutscene() {
        yetiDefeatCutscene.timer += 0.016;

        const targetCamX = yeti.x - 380;
        cameraX += (targetCamX - cameraX) * 0.06;

        yetiDefeatCutscene.confetti.forEach(c => {
            c.x += c.vx;
            c.y += c.vy;
            c.vy += 0.15;
            c.rot += c.rotSpeed;
        });

        if (yetiDefeatCutscene.phase === 'ROAR_FALL') {
            yeti.fallAngle = Math.min(Math.PI * 0.45, yeti.fallAngle + 0.035);
            if (yeti.fallAngle >= Math.PI * 0.45 && yetiDefeatCutscene.timer >= 1.6) {
                yetiDefeatCutscene.phase = 'COLLAPSE';
                playSound('slam');
                screenShake = 16;
                spawnDust(yeti.x, currentLevelData.groundY);
            }
        } else if (yetiDefeatCutscene.phase === 'COLLAPSE') {
            if (yetiDefeatCutscene.timer >= 2.6) {
                finishYetiDefeatCutscene();
            }
        }
    }

    function finishYetiDefeatCutscene() {
        if (!yetiDefeatCutscene.active) return;
        yetiDefeatCutscene.active = false;

        if (cutsceneOverlay) cutsceneOverlay.classList.add('hidden');
        currentState = STATES.VICTORY;

        unlockedPage4Levels = Math.max(unlockedPage4Levels, 61);
        generateLevelsGrid();

        if (victoryTitle) victoryTitle.textContent = 'Уровень 60 пройден!';
        if (victorySubtext) victorySubtext.textContent = 'ВЕЛИКИЙ ЙЕТИ ПОБЕЖДЁН! Вы покорили Вечный Холод! Впереди неизведанная пустыня "Исохшая земля"!';

        if (btnNextLevel) {
            btnNextLevel.classList.remove('hidden');
            btnNextLevel.innerHTML = '<span class="btn-icon">🏜️</span> Исохшая земля: Уровень 61';
        }
        if (btnReplay) btnReplay.innerHTML = '<span class="btn-icon">🔄</span> Пройти снова';
        if (btnToMenu) btnToMenu.innerHTML = '<span class="btn-icon">🏠</span> В меню уровней';

        victoryScreen.classList.remove('hidden');
        victoryScreen.classList.add('screen-active');
        player.state = 'VICTORY_IDLE';
    }

    // ==========================================
    // --- DRAW YETI, CAVE & HAZARDS ---
    // ==========================================
    function drawYetiCave(scale) {
        if (currentLevelIndex !== 60) return;
        const caveX = (currentLevelData && currentLevelData.yetiCave) ? currentLevelData.yetiCave.x : 19000;
        const caveY = (currentLevelData && currentLevelData.yetiCave) ? currentLevelData.yetiCave.y : 120;
        const caveW = (currentLevelData && currentLevelData.yetiCave) ? currentLevelData.yetiCave.w : 640;
        const caveH = (currentLevelData && currentLevelData.yetiCave) ? currentLevelData.yetiCave.h : 420;

        const drawX = (caveX - cameraX) * scale;
        const drawY = (caveY - cameraY) * scale;
        const drawW = caveW * scale;
        const drawH = caveH * scale;

        if (drawX < -drawW - 100 || drawX > canvas.width + 100) return;

        ctx.save();

        // 1. Massive Glacial Mountain Arch
        ctx.beginPath();
        ctx.moveTo(drawX - 60 * scale, drawY + drawH);
        ctx.lineTo(drawX - 20 * scale, drawY - 40 * scale);
        ctx.lineTo(drawX + drawW * 0.5, drawY - 90 * scale);
        ctx.lineTo(drawX + drawW + 60 * scale, drawY - 30 * scale);
        ctx.lineTo(drawX + drawW + 90 * scale, drawY + drawH);
        ctx.closePath();

        const mountainGrad = ctx.createLinearGradient(0, drawY - 90 * scale, 0, drawY + drawH);
        mountainGrad.addColorStop(0, '#e2e8f0');
        mountainGrad.addColorStop(0.3, '#94a3b8');
        mountainGrad.addColorStop(1, '#334155');
        ctx.fillStyle = mountainGrad;
        ctx.fill();

        // 2. Dark Cavern Rock Interior
        ctx.beginPath();
        ctx.moveTo(drawX, drawY + drawH);
        ctx.quadraticCurveTo(drawX + 20 * scale, drawY + 30 * scale, drawX + drawW * 0.5, drawY + 20 * scale);
        ctx.quadraticCurveTo(drawX + drawW - 20 * scale, drawY + 30 * scale, drawX + drawW, drawY + drawH);
        ctx.closePath();

        const caveGrad = ctx.createLinearGradient(0, drawY + 20 * scale, 0, drawY + drawH);
        caveGrad.addColorStop(0, '#020617');
        caveGrad.addColorStop(0.7, '#070f20');
        caveGrad.addColorStop(1, '#0f172a');
        ctx.fillStyle = caveGrad;
        ctx.fill();

        // 3. Huge Hanging Icicles along the cave mouth
        const iciclePts = [
            { rx: 0.12, len: 48 },
            { rx: 0.25, len: 75 },
            { rx: 0.38, len: 52 },
            { rx: 0.52, len: 85 },
            { rx: 0.65, len: 60 },
            { rx: 0.78, len: 78 },
            { rx: 0.90, len: 42 }
        ];
        iciclePts.forEach(ic => {
            const ix = drawX + drawW * ic.rx;
            const archY = drawY + 25 * scale + Math.pow(Math.abs(ic.rx - 0.5) * 2, 2) * (drawH * 0.15);
            const iLen = ic.len * scale;

            ctx.fillStyle = 'rgba(224, 242, 254, 0.92)';
            ctx.beginPath();
            ctx.moveTo(ix - 7 * scale, archY);
            ctx.lineTo(ix, archY + iLen);
            ctx.lineTo(ix + 7 * scale, archY);
            ctx.closePath();
            ctx.fill();
        });

        // 4. Glowing Blue Eyes inside the dark cave during cutscene (before Yeti emerges!)
        if (typeof yetiIntroCutscene !== 'undefined' && yetiIntroCutscene && yetiIntroCutscene.active && yetiIntroCutscene.phase === 'EYES') {
            const eyeAlpha = yetiIntroCutscene.eyeAlpha;
            const eyeY = (yeti.y - 45 - cameraY) * scale;
            const eyeX1 = (yeti.x - 14 - cameraX) * scale;
            const eyeX2 = (yeti.x + 14 - cameraX) * scale;

            ctx.save();
            ctx.shadowColor = '#00f0ff';
            ctx.shadowBlur = 28 * eyeAlpha * scale;

            // Cyan eye glow rings & piercing pupil
            [eyeX1, eyeX2].forEach(ex => {
                const eyeGlow = ctx.createRadialGradient(ex, eyeY, 1.5 * scale, ex, eyeY, 20 * scale);
                eyeGlow.addColorStop(0, `rgba(255, 255, 255, ${eyeAlpha})`);
                eyeGlow.addColorStop(0.35, `rgba(0, 240, 255, ${eyeAlpha * 0.95})`);
                eyeGlow.addColorStop(0.7, `rgba(56, 189, 248, ${eyeAlpha * 0.4})`);
                eyeGlow.addColorStop(1, 'rgba(0, 240, 255, 0)');
                ctx.fillStyle = eyeGlow;
                ctx.beginPath();
                ctx.arc(ex, eyeY, 20 * scale, 0, Math.PI * 2);
                ctx.fill();

                // Piercing sharp pupil
                ctx.fillStyle = `rgba(255, 255, 255, ${eyeAlpha})`;
                ctx.beginPath();
                ctx.ellipse(ex, eyeY, 3.5 * scale, 7 * scale, 0, 0, Math.PI * 2);
                ctx.fill();
            });
            ctx.restore();
        }

        ctx.restore();
    }

    function drawYetiHazards() {
        if (currentLevelIndex !== 60) return;
        const scale = canvas.height / 675;

        // 1. Ice Boulder Warning Zone on Ground
        if (yeti.iceBoulderTarget) {
            const tgX = (yeti.iceBoulderTarget.x - cameraX) * scale;
            const tgY = (yeti.iceBoulderTarget.y - cameraY) * scale;
            const tgR = yeti.iceBoulderTarget.radius * scale;

            ctx.save();
            // Pulsing red-cyan aura
            const pulse = (Math.sin(Date.now() * 0.015) + 1) * 0.5;
            const grad = ctx.createRadialGradient(tgX, tgY, 0, tgX, tgY, tgR);
            grad.addColorStop(0, `rgba(239, 68, 68, ${0.45 + pulse * 0.25})`);
            grad.addColorStop(0.7, `rgba(239, 68, 68, ${0.2 + pulse * 0.15})`);
            grad.addColorStop(1, 'rgba(56, 189, 248, 0)');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(tgX, tgY, tgR, 20 * scale, 0, 0, Math.PI * 2);
            ctx.fill();

            // Dashed outer ring
            ctx.strokeStyle = `rgba(239, 68, 68, ${0.8 + pulse * 0.2})`;
            ctx.lineWidth = 3 * scale;
            ctx.setLineDash([8 * scale, 5 * scale]);
            ctx.beginPath();
            ctx.ellipse(tgX, tgY, tgR, 20 * scale, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);

            // Warning text label
            ctx.font = `bold ${12 * scale}px Outfit, sans-serif`;
            ctx.fillStyle = '#fee2e2';
            ctx.textAlign = 'center';
            ctx.fillText('⚠️ ЗОНА ПАДЕНИЯ ЛЕДЯНОЙ ГЛЫБЫ! ⚠️', tgX, tgY - 26 * scale);
            ctx.restore();
        }

        // 2. Flying Ice Boulder Bomb
        if (yeti.iceBoulderBomb) {
            const bomb = yeti.iceBoulderBomb;
            const bX = (bomb.x - cameraX) * scale;
            const bY = (bomb.y - cameraY) * scale;
            const bR = bomb.radius * scale;

            ctx.save();
            ctx.translate(bX, bY);
            ctx.rotate(bomb.rot);

            ctx.shadowColor = '#38bdf8';
            ctx.shadowBlur = 18 * scale;

            // Jagged multifaceted crystalline ice boulder
            ctx.beginPath();
            const numSides = 7;
            for (let i = 0; i < numSides; i++) {
                const angle = (i / numSides) * Math.PI * 2;
                const r = bR * (0.8 + 0.35 * Math.sin(i * 2.5));
                const px = Math.cos(angle) * r;
                const py = Math.sin(angle) * r;
                if (i === 0) ctx.moveTo(px, py);
                else ctx.lineTo(px, py);
            }
            ctx.closePath();

            const iceGrad = ctx.createLinearGradient(-bR, -bR, bR, bR);
            iceGrad.addColorStop(0, '#ffffff');
            iceGrad.addColorStop(0.4, '#bae6fd');
            iceGrad.addColorStop(0.8, '#38bdf8');
            iceGrad.addColorStop(1, '#0284c7');
            ctx.fillStyle = iceGrad;
            ctx.fill();

            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2.5 * scale;
            ctx.stroke();

            ctx.restore();
        }

        // 3. Avalanche Surge Wave
        if (yeti.avalancheWave) {
            const wave = yeti.avalancheWave;
            const wX = (wave.x - cameraX) * scale;
            const wY = (wave.y - cameraY) * scale;
            const wW = wave.w * scale;
            const wH = wave.h * scale;

            ctx.save();
            // Wave crest & rolling wall
            ctx.beginPath();
            ctx.moveTo(wX + wW, wY + wH);
            ctx.lineTo(wX, wY + wH);
            ctx.quadraticCurveTo(wX - 25 * scale, wY + wH * 0.4, wX + 15 * scale, wY);
            ctx.quadraticCurveTo(wX + wW * 0.5, wY - 10 * scale, wX + wW, wY + wH);
            ctx.closePath();

            const avGrad = ctx.createLinearGradient(0, wY, 0, wY + wH);
            avGrad.addColorStop(0, '#ffffff');
            avGrad.addColorStop(0.3, '#e0f2fe');
            avGrad.addColorStop(0.7, '#7dd3fc');
            avGrad.addColorStop(1, '#0284c7');
            ctx.fillStyle = avGrad;
            ctx.fill();

            // Frothy foam crest
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 5 * scale;
            ctx.stroke();

            // Avalanche warning banner
            ctx.font = `bold ${13 * scale}px Outfit, sans-serif`;
            ctx.fillStyle = '#fef08a';
            ctx.textAlign = 'center';
            ctx.fillText('⚠️ ЛАВИНА! ПРИСЯДЬТЕ [CTRL / C / ПОДКАТ] ⚠️', wX + wW * 0.5, wY - 22 * scale);

            ctx.restore();
        }

        // 4. Giant Rolling Snowballs
        yeti.giantSnowballs.forEach(sb => {
            const sX = (sb.x - cameraX) * scale;
            const sY = (sb.y - cameraY) * scale;
            const sR = sb.radius * scale;

            ctx.save();
            ctx.translate(sX, sY);
            ctx.rotate(sb.rot);

            ctx.shadowColor = '#bae6fd';
            ctx.shadowBlur = 12 * scale;

            // Snowball sphere
            ctx.beginPath();
            ctx.arc(0, 0, sR, 0, Math.PI * 2);
            const ballGrad = ctx.createRadialGradient(-sR * 0.35, -sR * 0.35, sR * 0.1, 0, 0, sR);
            ballGrad.addColorStop(0, '#ffffff');
            ballGrad.addColorStop(0.65, '#e2e8f0');
            ballGrad.addColorStop(1, '#94a3b8');
            ctx.fillStyle = ballGrad;
            ctx.fill();

            ctx.strokeStyle = '#cbd5e1';
            ctx.lineWidth = 2 * scale;
            ctx.stroke();

            // Inner surface snow clumps
            ctx.fillStyle = '#cbd5e1';
            ctx.beginPath();
            ctx.arc(-sR * 0.3, sR * 0.2, sR * 0.22, 0, Math.PI * 2);
            ctx.arc(sR * 0.35, -sR * 0.25, sR * 0.18, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();

            // Warning hint above snowball
            ctx.save();
            ctx.font = `bold ${11 * scale}px Outfit, sans-serif`;
            ctx.fillStyle = '#38bdf8';
            ctx.textAlign = 'center';
            ctx.fillText('❄️ ПЕРЕПРЫГИВАЙТЕ! [ПРОБЕЛ]', sX, sY - sR - 12 * scale);
            ctx.restore();
        });

        // 5. Arena Pickable Stones
        yeti.arenaStones.forEach(st => {
            const stX = (st.x - cameraX) * scale;
            const stY = (st.y - cameraY) * scale;
            const bob = Math.sin(st.bobTimer) * 5 * scale;

            ctx.save();
            // Magical blue pedestal glow
            const glow = ctx.createRadialGradient(stX, stY, 0, stX, stY, 26 * scale);
            glow.addColorStop(0, 'rgba(56, 189, 248, 0.65)');
            glow.addColorStop(1, 'rgba(56, 189, 248, 0)');
            ctx.fillStyle = glow;
            ctx.beginPath();
            ctx.ellipse(stX, stY, 26 * scale, 8 * scale, 0, 0, Math.PI * 2);
            ctx.fill();

            // Faceted Solid Stone
            ctx.fillStyle = '#475569';
            ctx.strokeStyle = '#94a3b8';
            ctx.lineWidth = 2 * scale;
            ctx.beginPath();
            ctx.moveTo(stX - 12 * scale, stY - 4 * scale + bob);
            ctx.lineTo(stX - 6 * scale, stY - 22 * scale + bob);
            ctx.lineTo(stX + 8 * scale, stY - 20 * scale + bob);
            ctx.lineTo(stX + 14 * scale, stY - 5 * scale + bob);
            ctx.lineTo(stX, stY + 2 * scale + bob);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // Floating indicator prompt
            ctx.font = `bold ${10 * scale}px Outfit, sans-serif`;
            ctx.fillStyle = '#f8fafc';
            ctx.textAlign = 'center';
            ctx.fillText('🪨 [E] Камень', stX, stY - 28 * scale + bob);

            ctx.restore();
        });

        // 6. Thrown Player Snowballs
        yeti.playerSnowballs.forEach(pb => {
            const pbX = (pb.x - cameraX) * scale;
            const pbY = (pb.y - cameraY) * scale;
            const pbR = (pb.isStone ? 11 : 8) * scale;

            ctx.save();
            ctx.translate(pbX, pbY);
            ctx.rotate(pb.rot);

            ctx.shadowColor = pb.isStone ? '#64748b' : '#38bdf8';
            ctx.shadowBlur = 10 * scale;

            ctx.beginPath();
            ctx.arc(0, 0, pbR, 0, Math.PI * 2);
            const sGrad = ctx.createRadialGradient(-pbR * 0.3, -pbR * 0.3, pbR * 0.1, 0, 0, pbR);
            if (pb.isStone) {
                sGrad.addColorStop(0, '#f1f5f9');
                sGrad.addColorStop(0.5, '#94a3b8');
                sGrad.addColorStop(1, '#334155');
            } else {
                sGrad.addColorStop(0, '#ffffff');
                sGrad.addColorStop(0.7, '#e2e8f0');
                sGrad.addColorStop(1, '#bae6fd');
            }
            ctx.fillStyle = sGrad;
            ctx.fill();

            ctx.strokeStyle = pb.isStone ? '#cbd5e1' : '#ffffff';
            ctx.lineWidth = 1.8 * scale;
            ctx.stroke();

            ctx.restore();
        });

        // 7. Yeti Defeat Confetti Sparkles
        if (typeof yetiDefeatCutscene !== 'undefined' && yetiDefeatCutscene.active) {
            yetiDefeatCutscene.confetti.forEach(c => {
                const cx = (c.x - cameraX) * scale;
                const cy = (c.y - cameraY) * scale;
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(c.rot);
                ctx.fillStyle = c.color;
                ctx.fillRect(-c.size * scale * 0.5, -c.size * scale * 0.5, c.size * scale, c.size * scale);
                ctx.restore();
            });
        }
    }

    function drawYeti() {
        if (currentLevelIndex !== 60) return;
        const scale = canvas.height / 675;

        // Draw Yeti Cave in background
        drawYetiCave(scale);

        if (!yeti.active && !yeti.isFallen) {
            if (!yetiIntroCutscene.active) return;
            // During intro cutscene: Yeti body is completely HIDDEN during APPROACH and EYES!
            // First his glowing blue eyes appear in the cave, and ONLY in EMERGE does Yeti step out!
            if (yetiIntroCutscene.phase === 'APPROACH' || yetiIntroCutscene.phase === 'EYES') {
                return;
            }
        }

        const drawX = (yeti.x - cameraX) * scale;
        const drawY = (yeti.y - cameraY) * scale;

        ctx.save();
        ctx.translate(drawX, drawY);

        // Smooth transition: Yeti emerges from dark cave shadows into the light
        if (yetiIntroCutscene.active && yetiIntroCutscene.phase === 'EMERGE') {
            const emergeProg = Math.min(1.0, yetiIntroCutscene.timer / 2.0);
            ctx.globalAlpha = Math.min(1.0, 0.2 + emergeProg * 0.8);
        }

        if (yeti.isFallen) {
            ctx.rotate(yeti.fallAngle);
        }

        const isFlashing = yeti.hitFlashTimer > 0;
        const furWhite = isFlashing ? '#ffffff' : '#f8fafc';
        const furShadow = isFlashing ? '#e0f2fe' : '#cbd5e1';
        const furDark = isFlashing ? '#bae6fd' : '#94a3b8';
        const iceBlue = isFlashing ? '#ffffff' : '#38bdf8';
        const deepNavy = isFlashing ? '#ffffff' : '#0f172a';

        // 1. Yeti Legs & Huge Paws
        ctx.fillStyle = furShadow;
        // Left Leg
        ctx.beginPath();
        ctx.ellipse(-26 * scale, 55 * scale, 18 * scale, 28 * scale, 0, 0, Math.PI * 2);
        ctx.fill();
        // Right Leg
        ctx.beginPath();
        ctx.ellipse(26 * scale, 55 * scale, 18 * scale, 28 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // Left Paw
        ctx.fillStyle = furDark;
        ctx.beginPath();
        ctx.ellipse(-28 * scale, 75 * scale, 24 * scale, 12 * scale, 0, 0, Math.PI * 2);
        ctx.fill();
        // Right Paw
        ctx.beginPath();
        ctx.ellipse(28 * scale, 75 * scale, 24 * scale, 12 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // 2. Colossal Muscular Torso with Thick Fur
        ctx.fillStyle = furShadow;
        ctx.beginPath();
        ctx.ellipse(0, 5 * scale, 48 * scale, 55 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // Fluffy Chest Plate
        ctx.fillStyle = furWhite;
        ctx.beginPath();
        ctx.ellipse(0, -6 * scale, 34 * scale, 40 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // Shaggy fur tufts on shoulders and torso
        ctx.fillStyle = furWhite;
        [-38, -20, 0, 20, 38].forEach(fx => {
            ctx.beginPath();
            ctx.moveTo(fx * scale, -28 * scale);
            ctx.lineTo((fx - 7) * scale, -8 * scale);
            ctx.lineTo((fx + 7) * scale, -8 * scale);
            ctx.closePath();
            ctx.fill();
        });

        // 3. Yeti Arms
        let lArmRot = 0;
        let rArmRot = 0;
        if (yeti.roarArms > 0) {
            lArmRot = -Math.PI * 0.7 * yeti.roarArms;
            rArmRot = Math.PI * 0.7 * yeti.roarArms;
        } else if (yeti.state === 'ICE_BOULDER_FORM') {
            lArmRot = -Math.PI * 0.65 * yeti.iceBoulderFormProg;
            rArmRot = Math.PI * 0.65 * yeti.iceBoulderFormProg;
        } else if (yeti.state === 'AVALANCHE_WINDUP') {
            lArmRot = -Math.PI * 0.35;
            rArmRot = Math.PI * 0.35;
        } else if (yeti.shoveTimer > 0) {
            lArmRot = -Math.PI * 0.45;
        }

        // Left Arm
        ctx.save();
        ctx.translate(-42 * scale, -18 * scale);
        ctx.rotate(lArmRot);
        ctx.fillStyle = furShadow;
        ctx.beginPath();
        ctx.ellipse(0, 30 * scale, 16 * scale, 36 * scale, 0.15, 0, Math.PI * 2);
        ctx.fill();

        // Left Paw & Claws
        ctx.fillStyle = furDark;
        ctx.beginPath();
        ctx.ellipse(-4 * scale, 62 * scale, 18 * scale, 15 * scale, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = iceBlue;
        for (let c = -2; c <= 2; c++) {
            ctx.beginPath();
            ctx.moveTo((-4 + c * 6) * scale, 70 * scale);
            ctx.lineTo((-4 + c * 6) * scale, 82 * scale);
            ctx.lineTo((-1 + c * 6) * scale, 70 * scale);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();

        // Right Arm
        ctx.save();
        ctx.translate(42 * scale, -18 * scale);
        ctx.rotate(rArmRot);
        ctx.fillStyle = furShadow;
        ctx.beginPath();
        ctx.ellipse(0, 30 * scale, 16 * scale, 36 * scale, -0.15, 0, Math.PI * 2);
        ctx.fill();

        // Right Paw & Claws
        ctx.fillStyle = furDark;
        ctx.beginPath();
        ctx.ellipse(4 * scale, 62 * scale, 18 * scale, 15 * scale, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = iceBlue;
        for (let c = -2; c <= 2; c++) {
            ctx.beginPath();
            ctx.moveTo((4 + c * 6) * scale, 70 * scale);
            ctx.lineTo((4 + c * 6) * scale, 82 * scale);
            ctx.lineTo((7 + c * 6) * scale, 70 * scale);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();

        // Forming Ice Boulder in Hands
        if (yeti.state === 'ICE_BOULDER_FORM') {
            const bR = 38 * yeti.iceBoulderFormProg * scale;
            ctx.save();
            ctx.translate(0, -95 * scale);
            ctx.shadowColor = '#00f0ff';
            ctx.shadowBlur = 24 * scale;

            ctx.beginPath();
            ctx.arc(0, 0, bR, 0, Math.PI * 2);
            const bGrad = ctx.createRadialGradient(-bR * 0.3, -bR * 0.3, bR * 0.1, 0, 0, bR);
            bGrad.addColorStop(0, '#ffffff');
            bGrad.addColorStop(0.4, '#bae6fd');
            bGrad.addColorStop(0.8, '#38bdf8');
            bGrad.addColorStop(1, '#0284c7');
            ctx.fillStyle = bGrad;
            ctx.fill();

            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 3 * scale;
            ctx.stroke();
            ctx.restore();
        }

        // 4. Yeti Head
        ctx.fillStyle = furWhite;
        ctx.beginPath();
        ctx.ellipse(0, -48 * scale, 32 * scale, 28 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // Curved Icy Horns
        ctx.fillStyle = iceBlue;
        ctx.strokeStyle = '#bae6fd';
        ctx.lineWidth = 2 * scale;
        // Left Horn
        ctx.beginPath();
        ctx.moveTo(-24 * scale, -58 * scale);
        ctx.quadraticCurveTo(-46 * scale, -80 * scale, -52 * scale, -52 * scale);
        ctx.quadraticCurveTo(-38 * scale, -60 * scale, -18 * scale, -52 * scale);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        // Right Horn
        ctx.beginPath();
        ctx.moveTo(24 * scale, -58 * scale);
        ctx.quadraticCurveTo(46 * scale, -80 * scale, 52 * scale, -52 * scale);
        ctx.quadraticCurveTo(38 * scale, -60 * scale, 18 * scale, -52 * scale);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Menacing Furry Brow Ridge
        ctx.fillStyle = furDark;
        ctx.beginPath();
        ctx.moveTo(-24 * scale, -54 * scale);
        ctx.lineTo(0, -48 * scale);
        ctx.lineTo(24 * scale, -54 * scale);
        ctx.lineTo(16 * scale, -42 * scale);
        ctx.lineTo(-16 * scale, -42 * scale);
        ctx.closePath();
        ctx.fill();

        // 5. Piercing Glowing Blue Eyes
        const eyeColor = isFlashing ? '#ffffff' : '#00f0ff';
        [-12, 12].forEach(ex => {
            ctx.save();
            ctx.shadowColor = '#00f0ff';
            ctx.shadowBlur = 16 * yeti.eyeGlow * scale;

            ctx.fillStyle = eyeColor;
            ctx.beginPath();
            ctx.arc(ex * scale, -45 * scale, 5.5 * scale, 0, Math.PI * 2);
            ctx.fill();

            // Pupil
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(ex * scale, -45 * scale, 2 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });

        // 6. Mouth & Sharp Fangs
        const mouthH = (8 + yeti.mouthOpen * 24) * scale;
        ctx.fillStyle = deepNavy;
        ctx.beginPath();
        ctx.ellipse(0, -32 * scale + (yeti.mouthOpen * 6) * scale, 16 * scale, mouthH, 0, 0, Math.PI * 2);
        ctx.fill();

        // White Fangs
        ctx.fillStyle = '#ffffff';
        // Upper fangs
        ctx.beginPath();
        ctx.moveTo(-9 * scale, -32 * scale);
        ctx.lineTo(-6 * scale, -24 * scale);
        ctx.lineTo(-3 * scale, -32 * scale);
        ctx.moveTo(3 * scale, -32 * scale);
        ctx.lineTo(6 * scale, -24 * scale);
        ctx.lineTo(9 * scale, -32 * scale);
        ctx.closePath();
        ctx.fill();
        // Lower fangs
        ctx.beginPath();
        ctx.moveTo(-7 * scale, -30 * scale + mouthH);
        ctx.lineTo(-5 * scale, -38 * scale + mouthH);
        ctx.lineTo(-3 * scale, -30 * scale + mouthH);
        ctx.moveTo(3 * scale, -30 * scale + mouthH);
        ctx.lineTo(5 * scale, -38 * scale + mouthH);
        ctx.lineTo(7 * scale, -30 * scale + mouthH);
        ctx.closePath();
        ctx.fill();

        // 7. Roar Shockwaves
        yeti.roarShockwaves.forEach(sw => {
            ctx.save();
            ctx.strokeStyle = `rgba(56, 189, 248, ${sw.alpha})`;
            ctx.lineWidth = 4 * scale;
            ctx.beginPath();
            ctx.arc(0, -40 * scale, sw.radius * scale, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        });

        ctx.restore();
    }

