    function playerPunch() {
        if (player.state === 'DEFEAT' || currentState !== STATES.PLAYING) return;
        if (player.punchTimer && player.punchTimer > 0.08) return;

        player.punchTimer = 0.22;
        playSound('punch');

        // Check melee hit against any active minions
        if (currentLevelIndex === 80 && typeof mummy !== 'undefined' && mummy.minions) {
            mummy.minions.forEach(minion => {
                if (!minion.active) return;
                const dist = Math.abs(player.x - minion.x);
                const facingMatches = (player.facing > 0 && minion.x >= player.x - 20) || (player.facing < 0 && minion.x <= player.x + 20);
                if (dist < 80 && Math.abs(player.y - minion.y) < 60 && facingMatches) {
                    minion.hp -= 1;
                    minion.hitTimer = 0.25;
                    minion.x += player.facing * 30; // knockback
                    playSound('mummyHit');
                    screenShake = 6;

                    // Sand puff particles
                    for (let p = 0; p < 12; p++) {
                        particles.push({
                            x: minion.x + (Math.random() - 0.5) * 16,
                            y: minion.y - 25 + (Math.random() - 0.5) * 20,
                            vx: player.facing * (2 + Math.random() * 3),
                            vy: -(1 + Math.random() * 3),
                            size: 2 + Math.random() * 3,
                            color: Math.random() < 0.6 ? '#f59e0b' : '#d97706',
                            life: 0.45,
                            decay: 0.03
                        });
                    }

                    if (minion.hp <= 0) {
                        minion.active = false;
                        // Crumble explosion
                        for (let p = 0; p < 24; p++) {
                            particles.push({
                                x: minion.x + (Math.random() - 0.5) * 20,
                                y: minion.y - 25 + (Math.random() - 0.5) * 25,
                                vx: (Math.random() - 0.5) * 6,
                                vy: -(2 + Math.random() * 5),
                                size: 2.5 + Math.random() * 3.5,
                                color: Math.random() < 0.5 ? '#f59e0b' : '#b45309',
                                life: 0.6,
                                decay: 0.025
                            });
                        }
                    }
                }
            });
        }
    }

    function handleMummyQteClick() {
        if (!mummy.active || !mummy.qteActive || mummy.qteResolved) return;
        mummy.qteResolved = true;

        if (mummy.qteSlider >= mummy.qteGreenMin && mummy.qteSlider <= mummy.qteGreenMax) {
            // SUCCESS! Player holds balance
            mummy.qteSuccess = true;
            mummy.qteActive = false;
            playSound('victory');
            screenShake = 12;

            // Golden shielding burst
            for (let p = 0; p < 36; p++) {
                const angle = Math.random() * Math.PI * 2;
                const spd = 3 + Math.random() * 5;
                particles.push({
                    x: player.x,
                    y: player.y - 38,
                    vx: Math.cos(angle) * spd,
                    vy: Math.sin(angle) * spd,
                    size: 3 + Math.random() * 4,
                    color: Math.random() < 0.5 ? '#facc15' : '#fbbf24',
                    life: 0.7,
                    decay: 0.025
                });
            }

            // Disperse tornado
            mummy.tornadoActive = false;
            mummy.timer = 0;
            mummy.state = 'IDLE';
        } else {
            // FAILURE! Missed or hit red zone -> Sucked into tornado (lethal)
            mummy.qteSuccess = false;
            mummy.qteActive = false;
            mummy.lastDefeatReason = 'TORNADO';

            triggerDefeat(false);
            player.vy = -18;
            player.vx = -12;
            screenShake = 24;
            playSound('sandTornado');
        }
    }

    function updateMummy() {
        if (!mummy.active || mummy.health <= 0) return;

        // Arena boundary enforcement (cannot leave boss chamber or pass through mummy)
        if (player.x < mummy.arenaLeft + 30) {
            player.x = mummy.arenaLeft + 30;
            if (player.vx < 0) player.vx = 0;
        }
        if (!mummy.isFallen && mummy.state !== 'DEFEAT') {
            if (player.x > mummy.x - 80) {
                player.x = mummy.x - 80;
                if (player.vx > 0) player.vx = 0;
            }
        } else {
            if (player.x > mummy.arenaRight - 30) {
                player.x = mummy.arenaRight - 30;
                if (player.vx > 0) player.vx = 0;
            }
        }

        mummy.hitFlashTimer = Math.max(0, mummy.hitFlashTimer - 0.016);
        if (mummy.shoveTimer > 0) mummy.shoveTimer = Math.max(0, mummy.shoveTimer - 0.016);
        mummy.sandInEyesTimer = Math.max(0, mummy.sandInEyesTimer - 0.016);

        // --- SPAWN GOLDEN PYRAMIDS (DAMAGE MECHANIC) ---
        mummy.pyramidSpawnTimer -= 0.016;
        const activePyramids = mummy.pyramids.filter(p => !p.collected);
        if (mummy.pyramidSpawnTimer <= 0 && activePyramids.length < 2 && mummy.state !== 'DEFEAT') {
            mummy.pyramidSpawnTimer = 4.2;
            const floorY = (currentLevelData && currentLevelData.groundY ? currentLevelData.groundY : 540) - 35; // 505: hovers right above ground floor
            const spawnSpots = [
                { x: 13480, y: floorY },
                { x: 13700, y: floorY },
                { x: 13920, y: floorY },
                { x: 14140, y: floorY },
                { x: 14360, y: floorY },
                { x: 14580, y: floorY }
            ];
            const availableSpots = spawnSpots.filter(s => !activePyramids.some(p => Math.abs(p.x - s.x) < 150));
            const spotsToUse = availableSpots.length > 0 ? availableSpots : spawnSpots;
            const spot = spotsToUse[Math.floor(Math.random() * spotsToUse.length)];
            mummy.pyramids.push({
                id: 'pyr_' + Date.now(),
                x: spot.x,
                y: spot.y,
                baseY: spot.y,
                bobTimer: Math.random() * Math.PI * 2,
                collected: false
            });
        }

        // --- UPDATE PYRAMIDS & PLAYER PICKUP ---
        for (let i = mummy.pyramids.length - 1; i >= 0; i--) {
            const pyr = mummy.pyramids[i];
            if (pyr.collected) continue;
            pyr.bobTimer += 0.04;
            pyr.y = pyr.baseY + Math.sin(pyr.bobTimer) * 7;

            // Check pickup by player
            const dx = Math.abs(player.x - pyr.x);
            const dy = Math.abs((player.y - 36) - pyr.y);
            if (dx < 36 && dy < 48 && player.state !== 'DEFEAT' && currentState === STATES.PLAYING) {
                pyr.collected = true;
                playSound('pyramidCollect');

                // Launch brilliant solar ray from player to Mummy
                mummy.pyramidBeams.push({
                    startX: player.x,
                    startY: player.y - 35,
                    curX: player.x,
                    curY: player.y - 35,
                    targetX: mummy.x - 20,
                    targetY: mummy.y - 110,
                    t: 0,
                    active: true
                });
            }
        }

        // --- UPDATE PYRAMID SOLAR BEAMS ---
        for (let i = mummy.pyramidBeams.length - 1; i >= 0; i--) {
            const beam = mummy.pyramidBeams[i];
            beam.t += 0.07;
            beam.curX = beam.startX + (beam.targetX - beam.startX) * Math.min(1.0, beam.t);
            beam.curY = beam.startY + (beam.targetY - beam.startY) * Math.min(1.0, beam.t);

            if (beam.t >= 1.0) {
                beam.active = false;
                mummy.pyramidBeams.splice(i, 1);

                // DAMAGE MUMMY: -25 HP
                mummy.health = Math.max(0, mummy.health - 25);
                mummy.hitFlashTimer = 0.35;
                screenShake = 14;
                playSound('mummyHit');

                // Energy burst on Mummy
                for (let p = 0; p < 28; p++) {
                    const ang = Math.random() * Math.PI * 2;
                    const spd = 2 + Math.random() * 5;
                    particles.push({
                        x: mummy.x - 20,
                        y: mummy.y - 110,
                        vx: Math.cos(ang) * spd,
                        vy: Math.sin(ang) * spd,
                        size: 3 + Math.random() * 4,
                        color: Math.random() < 0.6 ? '#f59e0b' : '#fbbf24',
                        life: 0.6,
                        decay: 0.025
                    });
                }

                if (bossHealthBar) {
                    bossHealthBar.style.width = (mummy.health / 500 * 100) + '%';
                }
                if (bossPhaseText) {
                    bossPhaseText.textContent = `БОСС: ${mummy.health} / 500 (Собирайте пирамиды!)`;
                }

                if (mummy.health <= 0) {
                    startMummyDefeatCutscene();
                    return;
                }
            }
        }

        // --- MUMMY STATE MACHINE & ATTACK CYCLES ---
        mummy.timer += 0.016;

        if (mummy.state === 'IDLE') {
            if (mummy.timer > 2.4) {
                mummy.timer = 0;
                const attacks = ['ATTACK_SPIKES', 'ATTACK_MINIONS', 'ATTACK_SAND_IN_EYES', 'ATTACK_ANUBIS', 'ATTACK_SANDSTORM'];
                mummy.state = attacks[mummy.attackIndex];
                mummy.attackIndex = (mummy.attackIndex + 1) % attacks.length;

                if (mummy.state === 'ATTACK_SPIKES') {
                    mummy.spikeWarning = true;
                    mummy.spikeWarningTimer = 1.0;
                    playSound('warning');

                    // 3 Trajectory projection lines across arena
                    const originX = mummy.x - 30;
                    const originY = mummy.y - 110;
                    mummy.spikeTrajectories = [
                        { startX: originX, startY: originY, angle: -2.85, length: 1600 },
                        { startX: originX, startY: originY, angle: -3.05, length: 1600 },
                        { startX: originX, startY: originY, angle: -3.25, length: 1600 }
                    ];
                } else if (mummy.state === 'ATTACK_MINIONS') {
                    // Spawn 5 lesser mummies from the ground
                    mummy.minions = [];
                    const spawnXPositions = [mummy.x - 180, mummy.x - 340, mummy.x - 500, mummy.x - 660, mummy.x - 820];
                    spawnXPositions.forEach((sx, idx) => {
                        mummy.minions.push({
                            id: 'minion_' + idx,
                            x: sx,
                            y: currentLevelData.groundY,
                            hp: 2 + (idx % 2), // 2 to 3 hits
                            maxHp: 3,
                            vx: -1.7,
                            facing: -1,
                            hitTimer: 0,
                            animTime: Math.random() * 5,
                            attackCooldown: 0,
                            active: true
                        });
                    });
                    playSound('slam');
                    screenShake = 12;
                } else if (mummy.state === 'ATTACK_SAND_IN_EYES') {
                    // Launch tracking sand cloud with homing capability
                    mummy.sandCloud = {
                        x: mummy.x - 40,
                        y: mummy.y - 120,
                        vx: -5,
                        vy: -2,
                        speed: 7.2,
                        radius: 32,
                        lifetime: 6.0,
                        active: true
                    };
                    playSound('sandTornado');
                } else if (mummy.state === 'ATTACK_ANUBIS') {
                    mummy.staffActive = true;
                    mummy.staffSlamsRemaining = 5;
                    mummy.staffSlamTimer = 0.6;
                    playSound('mummyRoar');
                } else if (mummy.state === 'ATTACK_SANDSTORM') {
                    mummy.tornadoActive = true;
                    mummy.tornadoTimer = 0;
                    mummy.qteActive = true;
                    mummy.qteSlider = 0.15;
                    mummy.qteDirection = 1;
                    mummy.qteSpeed = 1.9;
                    mummy.qteGreenMin = 0.36;
                    mummy.qteGreenMax = 0.64;
                    mummy.qteResolved = false;
                    mummy.qteSuccess = false;
                    mummy.qteTimeout = 4.5;
                    playSound('sandTornado');
                    screenShake = 16;
                }
            }
        }

        // --- ATTACK 1: SPIKES UPDATE ---
        if (mummy.state === 'ATTACK_SPIKES') {
            if (mummy.spikeWarning) {
                mummy.spikeWarningTimer -= 0.016;
                if (mummy.spikeWarningTimer <= 0) {
                    mummy.spikeWarning = false;
                    playSound('slam');
                    screenShake = 10;

                    // Shoot 3 spikes along trajectories (15 dmg each)
                    mummy.spikeTrajectories.forEach(traj => {
                        const spd = 16;
                        mummy.spikes.push({
                            x: traj.startX,
                            y: traj.startY,
                            vx: Math.cos(traj.angle) * spd,
                            vy: Math.sin(traj.angle) * spd,
                            rot: traj.angle,
                            damage: 15,
                            active: true
                        });
                    });
                }
            } else {
                // Update flying spikes
                let anyActive = false;
                for (let i = mummy.spikes.length - 1; i >= 0; i--) {
                    const spk = mummy.spikes[i];
                    if (!spk.active) continue;
                    anyActive = true;
                    spk.x += spk.vx;
                    spk.y += spk.vy;

                    // Check player collision
                    const pDist = Math.hypot(player.x - spk.x, (player.y - 36) - spk.y);
                    if (pDist < 26 && player.state !== 'DEFEAT' && currentState === STATES.PLAYING) {
                        mummy.lastDefeatReason = 'SPIKES';
                        playerTakeDamage(spk.damage, 'mummySpike');
                        spk.active = false;
                    }

                    if (spk.x < mummy.arenaLeft - 100 || spk.y > currentLevelData.groundY + 10) {
                        spk.active = false;
                    }
                }

                if (!anyActive && mummy.timer > 2.0) {
                    mummy.timer = 0;
                    mummy.state = 'IDLE';
                }
            }
        }

        // --- ATTACK 2: MINIONS UPDATE ---
        if (mummy.state === 'ATTACK_MINIONS') {
            let livingCount = 0;
            mummy.minions.forEach(minion => {
                if (!minion.active) return;
                livingCount++;
                minion.animTime += 0.04;
                minion.hitTimer = Math.max(0, minion.hitTimer - 0.016);
                minion.attackCooldown = Math.max(0, minion.attackCooldown - 0.016);

                // March towards player
                minion.facing = player.x < minion.x ? -1 : 1;
                minion.x += minion.facing * 1.8;

                // Attack player on touch (5 dmg per hit)
                const dist = Math.abs(player.x - minion.x);
                if (dist < 34 && Math.abs(player.y - minion.y) < 30 && minion.attackCooldown <= 0 && player.state !== 'DEFEAT' && currentState === STATES.PLAYING) {
                    minion.attackCooldown = 1.1;
                    mummy.lastDefeatReason = 'MINIONS';
                    playerTakeDamage(5, 'mummyMinion');
                }
            });

            if (livingCount === 0 || mummy.timer > 11.0) {
                mummy.minions.forEach(m => m.active = false);
                mummy.timer = 0;
                mummy.state = 'IDLE';
            }
        }

        // --- ATTACK 3: HOMING SAND CLOUD & BLINDNESS UPDATE ---
        if (mummy.sandCloud && mummy.sandCloud.active) {
            const sc = mummy.sandCloud;
            sc.lifetime -= 0.016;

            // Target player center
            const targetX = player.x;
            const targetY = player.y - 35;
            const dx = targetX - sc.x;
            const dy = targetY - sc.y;
            const dist = Math.hypot(dx, dy);

            // Smooth homing tracking towards player
            if (dist > 0) {
                const desiredVx = (dx / dist) * sc.speed;
                const desiredVy = (dy / dist) * sc.speed;
                sc.vx += (desiredVx - sc.vx) * 0.12;
                sc.vy += (desiredVy - sc.vy) * 0.12;
            }

            sc.x += sc.vx;
            sc.y += sc.vy;

            // Spawn trailing sand particles while in flight
            if (Math.random() < 0.65) {
                particles.push({
                    x: sc.x + (Math.random() - 0.5) * 20,
                    y: sc.y + (Math.random() - 0.5) * 20,
                    vx: -sc.vx * 0.25 + (Math.random() - 0.5) * 2.5,
                    vy: -sc.vy * 0.25 + (Math.random() - 0.5) * 2.5,
                    size: 3 + Math.random() * 4.5,
                    color: Math.random() < 0.6 ? '#f59e0b' : '#fbbf24',
                    life: 0.45,
                    decay: 0.035
                });
            }

            // Proximity hit: when close to player, cloud bursts and applies 7-second blindness
            if (dist < 48 && player.state !== 'DEFEAT' && currentState === STATES.PLAYING) {
                sc.active = false;
                mummy.sandInEyesTimer = 7.0; // 7 seconds blindness duration!
                playSound('rustle');
                playSound('airBoost');
                screenShake = 10;

                // Dense sand burst explosion around player
                for (let p = 0; p < 36; p++) {
                    const ang = Math.random() * Math.PI * 2;
                    const spd = 2 + Math.random() * 5.5;
                    particles.push({
                        x: player.x + (Math.random() - 0.5) * 24,
                        y: player.y - 36 + (Math.random() - 0.5) * 24,
                        vx: Math.cos(ang) * spd,
                        vy: Math.sin(ang) * spd - 1.5,
                        size: 3 + Math.random() * 5,
                        color: Math.random() < 0.5 ? '#f59e0b' : (Math.random() < 0.5 ? '#d97706' : '#fef3c7'),
                        life: 0.85,
                        decay: 0.025
                    });
                }
            } else if (sc.lifetime <= 0) {
                sc.active = false;
            }
        }

        if (mummy.state === 'ATTACK_SAND_IN_EYES') {
            if ((!mummy.sandCloud || !mummy.sandCloud.active || mummy.timer > 3.2) && mummy.timer > 1.4) {
                mummy.timer = 0;
                mummy.state = 'IDLE';
            }
        }

        // --- ATTACK 4: STAFF OF ANUBIS UPDATE ---
        if (mummy.state === 'ATTACK_ANUBIS') {
            mummy.staffSlamTimer -= 0.016;

            if (mummy.staffSlamsRemaining > 0 && mummy.staffSlamTimer <= 0) {
                mummy.staffSlamsRemaining--;
                mummy.staffSlamTimer = 1.1; // rhythm slam every 1.1s
                playSound('anubisSlam');
                screenShake = 15;

                // Send rolling shockwave across arena floor (20 dmg, avoid by jumping)
                mummy.shockwaves.push({
                    x: mummy.x - 40,
                    y: currentLevelData.groundY,
                    vx: -11.5,
                    w: 38,
                    h: 46,
                    damage: 20,
                    active: true
                });
            }

            // Update shockwaves
            for (let i = mummy.shockwaves.length - 1; i >= 0; i--) {
                const sw = mummy.shockwaves[i];
                if (!sw.active) continue;
                sw.x += sw.vx;

                // Hit player if player is touching the ground
                if (Math.abs(player.x - sw.x) < 28 && player.grounded && player.y >= currentLevelData.groundY - 14 && player.state !== 'DEFEAT' && currentState === STATES.PLAYING) {
                    mummy.lastDefeatReason = 'ANUBIS';
                    playerTakeDamage(sw.damage, 'anubisWave');
                    sw.active = false;
                }

                if (sw.x < mummy.arenaLeft - 80) {
                    sw.active = false;
                }
            }

            if (mummy.staffSlamsRemaining <= 0 && mummy.shockwaves.every(s => !s.active) && mummy.timer > 6.5) {
                mummy.staffActive = false;
                mummy.timer = 0;
                mummy.state = 'IDLE';
            }
        }

        // --- ATTACK 5: SANDSTORM TORNADO & QTE UPDATE ---
        if (mummy.state === 'ATTACK_SANDSTORM') {
            if (mummy.qteActive && !mummy.qteResolved) {
                mummy.qteSlider += mummy.qteDirection * mummy.qteSpeed * 0.016;
                if (mummy.qteSlider > 0.98) {
                    mummy.qteSlider = 0.98;
                    mummy.qteDirection = -1;
                } else if (mummy.qteSlider < 0.02) {
                    mummy.qteSlider = 0.02;
                    mummy.qteDirection = 1;
                }

                mummy.qteTimeout -= 0.016;
                if (mummy.qteTimeout <= 0) {
                    // Time expired without hitting balance -> Fatal defeat
                    handleMummyQteClick();
                }
            }

            if (mummy.qteSuccess && mummy.timer > 2.5) {
                mummy.tornadoActive = false;
                mummy.timer = 0;
                mummy.state = 'IDLE';
            }
        }
    }

    function startMummyDefeatCutscene() {
        mummy.state = 'DEFEAT';
        mummy.active = false;
        mummy.isFallen = true;
        currentState = STATES.CUTSCENE;
        mummyDefeatCutscene.active = true;
        mummyDefeatCutscene.phase = 'CRACK';
        mummyDefeatCutscene.timer = 0;
        mummyDefeatCutscene.confetti = [];

        if (bossHud) bossHud.classList.add('hidden');
        if (cutsceneOverlay) cutsceneOverlay.classList.remove('hidden');
        if (cutsceneChapter) cutsceneChapter.textContent = '🏺 ВЕЛИКАЯ МУМИЯ ПОВЕРЖЕНА!';
        if (cutsceneText) cutsceneText.textContent = 'Древний владыка рассыпается в священный золотой песок!';

        playSound('victory');
        screenShake = 22;

        // Golden sand burst
        for (let i = 0; i < 90; i++) {
            const angle = Math.random() * Math.PI * 2;
            const spd = 2 + Math.random() * 8;
            mummyDefeatCutscene.confetti.push({
                x: mummy.x - 20,
                y: mummy.y - 100,
                vx: Math.cos(angle) * spd,
                vy: Math.sin(angle) * spd,
                size: 3 + Math.random() * 6,
                color: ['#f59e0b', '#fbbf24', '#facc15', '#b45309', '#e0e7ff'][Math.floor(Math.random() * 5)],
                rot: Math.random() * Math.PI * 2,
                rotSpd: (Math.random() - 0.5) * 0.2
            });
        }
    }

    function updateMummyDefeatCutscene() {
        mummyDefeatCutscene.timer += 0.016;
        mummyDefeatCutscene.confetti.forEach(c => {
            c.x += c.vx;
            c.y += c.vy;
            c.vy += 0.12; // gravity
            c.rot += c.rotSpd;
        });

        if (mummyDefeatCutscene.timer > 3.2) {
            finishMummyDefeatCutscene();
        }
    }

    function finishMummyDefeatCutscene() {
        if (!mummyDefeatCutscene.active) return;
        mummyDefeatCutscene.active = false;
        if (cutsceneOverlay) cutsceneOverlay.classList.add('hidden');

        currentState = STATES.VICTORY;
        unlockedPage4Levels = Math.max(unlockedPage4Levels, 80);
        unlockedPage5Levels = Math.max(unlockedPage5Levels, 81);
        generateLevelsGrid();

        if (victoryTitle) victoryTitle.textContent = '🏆 80 Уровень пройден!';
        if (victorySubtext) victorySubtext.textContent = 'ВЕЛИКАЯ ДРЕВНЯЯ МУМИЯ ПОВЕРЖЕНА! Открыта 5 страница — Цветение сакуры!';

        if (btnNextLevel) {
            if (levelsData[81]) {
                btnNextLevel.classList.remove('hidden');
                btnNextLevel.innerHTML = '<span class="btn-icon">🌸</span> Цветение сакуры: Уровень 81';
            } else {
                btnNextLevel.classList.add('hidden');
            }
        }
        if (btnReplay) btnReplay.innerHTML = '<span class="btn-icon">🔄</span> Пройти снова';
        if (btnToMenu) btnToMenu.innerHTML = '<span class="btn-icon">🏠</span> В меню уровней';

        if (victoryScreen) {
            victoryScreen.classList.remove('hidden');
            victoryScreen.classList.add('screen-active');
        }
        player.state = 'VICTORY_IDLE';
        playSound('victory');
    }

    // Helper to draw swirling 3D sand cyclone during intro cutscene
    function drawMummySandVortex(ctx, mx, my, camX, camY, scale, radius, alpha) {
        if (alpha <= 0) return;
        const cx = (mx - camX) * scale;
        const cy = (my - camY) * scale;
        const time = Date.now() * 0.007;

        ctx.save();
        ctx.globalAlpha = Math.min(1.0, alpha);

        // Ground sand dust burst
        const baseGrad = ctx.createRadialGradient(cx, cy, 10 * scale, cx, cy, radius * 1.3 * scale);
        baseGrad.addColorStop(0, 'rgba(251, 191, 36, 0.7)');
        baseGrad.addColorStop(0.5, 'rgba(217, 119, 6, 0.4)');
        baseGrad.addColorStop(1, 'rgba(180, 83, 9, 0)');
        ctx.fillStyle = baseGrad;
        ctx.beginPath();
        ctx.ellipse(cx, cy, radius * 1.3 * scale, radius * 0.35 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        // 8 Spiraling 3D Sand Cyclone Funnel Rings rising up into the sky
        for (let ring = 0; ring < 8; ring++) {
            const hOffset = -ring * 25 * scale;
            const rWidth = (radius * (0.35 + ring * 0.1)) * scale;
            const rHeight = rWidth * 0.28;
            const sway = Math.sin(time + ring * 0.8) * 14 * scale;

            ctx.strokeStyle = (ring % 2 === 0) ? '#fbbf24' : '#d97706';
            ctx.lineWidth = (2.5 + (8 - ring) * 0.4) * scale;
            ctx.beginPath();
            ctx.ellipse(cx + sway, cy + hOffset, rWidth, rHeight, Math.sin(time * 0.7 + ring) * 0.15, 0, Math.PI * 2);
            ctx.stroke();
        }
        ctx.restore();
    }

    // --- DRAW MUMMY BOSS ---
    function drawMummy(scale) {
        if (!mummy.active && !mummy.introPlayed && !mummyDefeatCutscene.active && (!mummyIntroCutscene || !mummyIntroCutscene.active)) return;
        if (mummyDefeatCutscene.active && mummyDefeatCutscene.timer > 2.5) return;

        let drawY = mummy.y;
        let mummyAlpha = 1.0;

        if (mummyIntroCutscene && mummyIntroCutscene.active) {
            if (mummyIntroCutscene.phase === 'STORM_RISE') {
                drawMummySandVortex(ctx, mummy.x, mummy.y, cameraX, cameraY, scale, mummyIntroCutscene.vortexRadius, mummyIntroCutscene.sandVortexAlpha);
                drawY = mummy.y + 110;
                mummyAlpha = 0.3 * mummyIntroCutscene.sandVortexAlpha;
            } else if (mummyIntroCutscene.phase === 'EMERGE') {
                const emergeProg = Math.min(1.0, mummyIntroCutscene.timer / 2.0);
                drawMummySandVortex(ctx, mummy.x, mummy.y, cameraX, cameraY, scale, 180, Math.max(0.3, 1.0 - emergeProg * 0.5));
                drawY = mummy.y + (1.0 - emergeProg) * 110;
                mummyAlpha = Math.min(1.0, 0.4 + emergeProg * 0.6);
            } else if (mummyIntroCutscene.phase === 'ROAR') {
                drawMummySandVortex(ctx, mummy.x, mummy.y, cameraX, cameraY, scale, 130, 0.35);
                drawY = mummy.y;
                mummyAlpha = 1.0;
            }
        }

        const screenX = (mummy.x - cameraX) * scale;
        const screenY = (drawY - cameraY) * scale;

        ctx.save();
        ctx.translate(screenX, screenY);
        ctx.globalAlpha = mummyAlpha;

        // Disintegration fade on defeat
        if (mummyDefeatCutscene.active) {
            ctx.globalAlpha = Math.max(0, 1.0 - mummyDefeatCutscene.timer / 2.5);
        }

        // Damage flash
        const isHit = mummy.hitFlashTimer > 0;
        const linenBase = isHit ? '#ffffff' : '#fef3c7';
        const linenShadow = isHit ? '#f87171' : '#d97706';
        const goldAccent = isHit ? '#ffffff' : '#fbbf24';
        const royalBlue = isHit ? '#ef4444' : '#1e3a8a';

        // 1. Sand Aura Particles orbiting Mummy
        const auraTime = Date.now() * 0.003;
        for (let i = 0; i < 16; i++) {
            const aAng = auraTime + i * (Math.PI / 8);
            const aRadX = 55 * scale;
            const aRadY = 95 * scale;
            const ax = Math.cos(aAng) * aRadX;
            const ay = -95 * scale + Math.sin(aAng) * aRadY;
            ctx.fillStyle = (i % 2 === 0) ? 'rgba(245, 158, 11, 0.7)' : 'rgba(251, 191, 36, 0.5)';
            ctx.beginPath();
            ctx.arc(ax, ay, (2 + (i % 3)) * scale, 0, Math.PI * 2);
            ctx.fill();
        }

        // 2. Colossal Mummy Body (Wrapped Torso & Robes)
        ctx.fillStyle = linenBase;
        ctx.strokeStyle = linenShadow;
        ctx.lineWidth = 2.5 * scale;

        // Legs / Skirt base
        ctx.beginPath();
        ctx.moveTo(-35 * scale, 0);
        ctx.lineTo(-40 * scale, -90 * scale);
        ctx.lineTo(40 * scale, -90 * scale);
        ctx.lineTo(35 * scale, 0);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Horizontal Bandage Wraps across Lower Body
        for (let b = 1; b <= 6; b++) {
            const by = -b * 14 * scale;
            ctx.beginPath();
            ctx.moveTo(-38 * scale, by);
            ctx.quadraticCurveTo(0, by + 5 * scale, 38 * scale, by);
            ctx.stroke();
        }

        // Torso
        ctx.beginPath();
        ctx.moveTo(-45 * scale, -90 * scale);
        ctx.lineTo(-50 * scale, -150 * scale);
        ctx.lineTo(50 * scale, -150 * scale);
        ctx.lineTo(45 * scale, -90 * scale);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Diagonal Bandage Wraps across Torso
        ctx.beginPath();
        ctx.moveTo(-48 * scale, -140 * scale);
        ctx.lineTo(44 * scale, -100 * scale);
        ctx.moveTo(-44 * scale, -100 * scale);
        ctx.lineTo(48 * scale, -140 * scale);
        ctx.moveTo(-46 * scale, -120 * scale);
        ctx.lineTo(46 * scale, -120 * scale);
        ctx.stroke();

        // 3. Ornate Pharaoh Golden Pectoral Collar (Усех)
        ctx.fillStyle = goldAccent;
        ctx.beginPath();
        ctx.arc(0, -150 * scale, 42 * scale, 0, Math.PI);
        ctx.fill();
        ctx.strokeStyle = royalBlue;
        ctx.lineWidth = 3 * scale;
        ctx.stroke();

        // 4. Arms
        // Left Arm (bent holding staff, charging, thrusting out in shove, or raised roaring)
        ctx.fillStyle = linenBase;
        ctx.strokeStyle = linenShadow;
        ctx.lineWidth = 2.5 * scale;
        ctx.beginPath();
        if (mummy.shoveTimer && mummy.shoveTimer > 0) {
            ctx.moveTo(-50 * scale, -140 * scale);
            ctx.lineTo(-95 * scale, -140 * scale);
            ctx.lineTo(-95 * scale, -115 * scale);
            ctx.lineTo(-44 * scale, -115 * scale);
        } else if (mummyIntroCutscene && mummyIntroCutscene.active && mummyIntroCutscene.phase === 'ROAR') {
            ctx.moveTo(-50 * scale, -145 * scale);
            ctx.lineTo(-85 * scale, -175 * scale);
            ctx.lineTo(-70 * scale, -195 * scale);
            ctx.lineTo(-44 * scale, -155 * scale);
        } else {
            ctx.moveTo(-50 * scale, -145 * scale);
            ctx.lineTo(-75 * scale, -115 * scale);
            ctx.lineTo(-58 * scale, -85 * scale);
            ctx.lineTo(-44 * scale, -95 * scale);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Right Arm
        ctx.beginPath();
        if (mummyIntroCutscene && mummyIntroCutscene.active && mummyIntroCutscene.phase === 'ROAR') {
            ctx.moveTo(50 * scale, -145 * scale);
            ctx.lineTo(85 * scale, -175 * scale);
            ctx.lineTo(70 * scale, -195 * scale);
            ctx.lineTo(44 * scale, -155 * scale);
        } else {
            ctx.moveTo(50 * scale, -145 * scale);
            ctx.lineTo(75 * scale, -115 * scale);
            ctx.lineTo(58 * scale, -85 * scale);
            ctx.lineTo(44 * scale, -95 * scale);
        }
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // 5. Staff of Anubis (When Active or Attacking)
        if (mummy.staffActive || mummy.state === 'ATTACK_ANUBIS') {
            const staffX = -75 * scale;
            const staffY = -140 * scale;

            ctx.save();
            // Golden shaft
            const sGrad = ctx.createLinearGradient(staffX - 5 * scale, 0, staffX + 5 * scale, 0);
            sGrad.addColorStop(0, '#fef08a');
            sGrad.addColorStop(0.5, '#f59e0b');
            sGrad.addColorStop(1, '#b45309');
            ctx.fillStyle = sGrad;
            ctx.fillRect(staffX - 4 * scale, staffY, 8 * scale, 170 * scale);
            ctx.strokeStyle = '#78350f';
            ctx.lineWidth = 1.5 * scale;
            ctx.strokeRect(staffX - 4 * scale, staffY, 8 * scale, 170 * scale);

            // Jackal Head of Anubis at top
            ctx.fillStyle = '#0f172a'; // Obsidian black
            ctx.beginPath();
            ctx.moveTo(staffX, staffY - 35 * scale);
            ctx.lineTo(staffX - 16 * scale, staffY - 12 * scale);
            ctx.lineTo(staffX + 16 * scale, staffY - 12 * scale);
            ctx.closePath();
            ctx.fill();

            // Pointed Jackal Ears
            ctx.beginPath();
            ctx.moveTo(staffX - 12 * scale, staffY - 12 * scale);
            ctx.lineTo(staffX - 22 * scale, staffY - 45 * scale);
            ctx.lineTo(staffX - 6 * scale, staffY - 26 * scale);
            ctx.closePath();
            ctx.fill();

            ctx.beginPath();
            ctx.moveTo(staffX + 12 * scale, staffY - 12 * scale);
            ctx.lineTo(staffX + 22 * scale, staffY - 45 * scale);
            ctx.lineTo(staffX + 6 * scale, staffY - 26 * scale);
            ctx.closePath();
            ctx.fill();

            // Glowing Turquoise Jackal Eyes
            ctx.fillStyle = '#38bdf8';
            ctx.beginPath();
            ctx.arc(staffX - 6 * scale, staffY - 20 * scale, 2.5 * scale, 0, Math.PI * 2);
            ctx.arc(staffX + 6 * scale, staffY - 20 * scale, 2.5 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }

        // 6. Pharaoh Head & Nemes Headdress
        const headCenterY = -175 * scale;

        // Nemes Flaps (Golden & Royal Blue Striped headdress wings)
        ctx.fillStyle = goldAccent;
        ctx.beginPath();
        ctx.moveTo(-28 * scale, headCenterY - 28 * scale);
        ctx.lineTo(-48 * scale, headCenterY + 22 * scale);
        ctx.lineTo(-24 * scale, headCenterY + 20 * scale);
        ctx.lineTo(-20 * scale, headCenterY);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = royalBlue;
        ctx.lineWidth = 3 * scale;
        ctx.stroke();

        ctx.fillStyle = goldAccent;
        ctx.beginPath();
        ctx.moveTo(28 * scale, headCenterY - 28 * scale);
        ctx.lineTo(48 * scale, headCenterY + 22 * scale);
        ctx.lineTo(24 * scale, headCenterY + 20 * scale);
        ctx.lineTo(20 * scale, headCenterY);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Head Base
        ctx.fillStyle = linenBase;
        ctx.strokeStyle = linenShadow;
        ctx.lineWidth = 2.5 * scale;
        ctx.beginPath();
        ctx.ellipse(0, headCenterY, 26 * scale, 30 * scale, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();

        // Bandages around Head
        ctx.beginPath();
        ctx.moveTo(-22 * scale, headCenterY - 10 * scale);
        ctx.lineTo(22 * scale, headCenterY - 10 * scale);
        ctx.moveTo(-24 * scale, headCenterY + 8 * scale);
        ctx.lineTo(24 * scale, headCenterY + 8 * scale);
        ctx.stroke();

        // Braided Pharaoh Beard (Осирисова бородка)
        ctx.fillStyle = goldAccent;
        ctx.fillRect(-5 * scale, headCenterY + 26 * scale, 10 * scale, 24 * scale);
        ctx.strokeStyle = royalBlue;
        ctx.strokeRect(-5 * scale, headCenterY + 26 * scale, 10 * scale, 24 * scale);

        // 7. Glowing Ancient Amber Eyes
        const eyeAlpha = mummy.eyeGlow;
        ctx.fillStyle = `rgba(245, 158, 11, ${eyeAlpha})`;
        ctx.beginPath();
        ctx.ellipse(-10 * scale, headCenterY - 4 * scale, 5 * scale, 3.5 * scale, 0, 0, Math.PI * 2);
        ctx.ellipse(10 * scale, headCenterY - 4 * scale, 5 * scale, 3.5 * scale, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        ctx.arc(-10 * scale, headCenterY - 4 * scale, 2 * scale, 0, Math.PI * 2);
        ctx.arc(10 * scale, headCenterY - 4 * scale, 2 * scale, 0, Math.PI * 2);
        ctx.fill();

        // Eye glow rays
        ctx.strokeStyle = `rgba(251, 191, 36, ${0.45 * eyeAlpha})`;
        ctx.lineWidth = 2 * scale;
        ctx.beginPath();
        ctx.moveTo(-10 * scale, headCenterY - 4 * scale);
        ctx.lineTo(-24 * scale, headCenterY - 4 * scale);
        ctx.moveTo(10 * scale, headCenterY - 4 * scale);
        ctx.lineTo(24 * scale, headCenterY - 4 * scale);
        ctx.stroke();

        // Frayed trailing bandage ribbons drifting behind
        const ribbonWave = Math.sin(Date.now() * 0.005);
        ctx.strokeStyle = 'rgba(254, 243, 199, 0.7)';
        ctx.lineWidth = 3 * scale;
        ctx.beginPath();
        ctx.moveTo(-45 * scale, -130 * scale);
        ctx.quadraticCurveTo(-75 * scale + ribbonWave * 12 * scale, -120 * scale, -95 * scale, -90 * scale);
        ctx.moveTo(45 * scale, -130 * scale);
        ctx.quadraticCurveTo(75 * scale + ribbonWave * 12 * scale, -120 * scale, 95 * scale, -90 * scale);
        ctx.stroke();

        ctx.restore();
    }

    // --- DRAW MUMMY HAZARDS (SPIKES, MINIONS, SHOCKWAVES, TORNADO, PYRAMIDS) ---
    function drawMummyHazards(scale) {
        if (currentLevelIndex !== 80) return;

        // 1. Attack 1 Warning Trajectory Lines (Translucent Red Dashed Lines)
        if (mummy.active && mummy.spikeWarning && mummy.spikeTrajectories) {
            ctx.save();
            ctx.strokeStyle = 'rgba(239, 68, 68, 0.55)';
            ctx.lineWidth = 2.5 * scale;
            ctx.setLineDash([12 * scale, 8 * scale]);

            mummy.spikeTrajectories.forEach(traj => {
                const sx = (traj.startX - cameraX) * scale;
                const sy = (traj.startY - cameraY) * scale;
                const ex = (traj.startX + Math.cos(traj.angle) * traj.length - cameraX) * scale;
                const ey = (traj.startY + Math.sin(traj.angle) * traj.length - cameraY) * scale;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(ex, ey);
                ctx.stroke();

                // Warning target indicator
                ctx.fillStyle = 'rgba(239, 68, 68, 0.75)';
                ctx.beginPath();
                ctx.arc(ex, ey, 6 * scale, 0, Math.PI * 2);
                ctx.fill();
            });
            ctx.restore();
        }

        // 2. Attack 1 Flying Sand Spikes
        if (mummy.spikes && mummy.spikes.length > 0) {
            mummy.spikes.forEach(spk => {
                if (!spk.active) return;
                const sx = (spk.x - cameraX) * scale;
                const sy = (spk.y - cameraY) * scale;

                ctx.save();
                ctx.translate(sx, sy);
                ctx.rotate(spk.rot);

                // Sharp crystalline dried sand spike
                ctx.fillStyle = '#d97706';
                ctx.strokeStyle = '#fef3c7';
                ctx.lineWidth = 2 * scale;
                ctx.beginPath();
                ctx.moveTo(22 * scale, 0);
                ctx.lineTo(-18 * scale, -8 * scale);
                ctx.lineTo(-12 * scale, 0);
                ctx.lineTo(-18 * scale, 8 * scale);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();

                // Golden trail particles
                ctx.fillStyle = 'rgba(251, 191, 36, 0.6)';
                ctx.beginPath();
                ctx.arc(-22 * scale, 0, 4 * scale, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            });
        }

        // 3. Attack 2 Lesser Mummies (5 Minions)
        if (mummy.minions && mummy.minions.length > 0) {
            mummy.minions.forEach(minion => {
                if (!minion.active) return;
                const mx = (minion.x - cameraX) * scale;
                const my = (minion.y - cameraY) * scale;

                ctx.save();
                ctx.translate(mx, my);

                const isHit = minion.hitTimer > 0;
                ctx.fillStyle = isHit ? '#ffffff' : '#fef3c7';
                ctx.strokeStyle = isHit ? '#ef4444' : '#b45309';
                ctx.lineWidth = 2 * scale;

                // Little mummy body
                const walkCycle = Math.sin(minion.animTime * 6);
                ctx.beginPath();
                ctx.ellipse(0, -22 * scale, 10 * scale, 18 * scale, 0, 0, Math.PI * 2);
                ctx.fill();
                ctx.stroke();

                // Feet
                ctx.beginPath();
                ctx.moveTo(-6 * scale, -4 * scale);
                ctx.lineTo(-6 * scale + walkCycle * 6 * scale, 0);
                ctx.moveTo(6 * scale, -4 * scale);
                ctx.lineTo(6 * scale - walkCycle * 6 * scale, 0);
                ctx.stroke();

                // Head
                ctx.beginPath();
                ctx.arc(0, -42 * scale, 8.5 * scale, 0, Math.PI * 2);
                ctx.fill();
                ctx.stroke();

                // Glowing red eyes
                ctx.fillStyle = '#ef4444';
                ctx.beginPath();
                ctx.arc(minion.facing * 3 * scale - 2 * scale, -42 * scale, 2 * scale, 0, Math.PI * 2);
                ctx.arc(minion.facing * 3 * scale + 2 * scale, -42 * scale, 2 * scale, 0, Math.PI * 2);
                ctx.fill();

                // Health pips above minion
                for (let h = 0; h < minion.maxHp; h++) {
                    ctx.fillStyle = (h < minion.hp) ? '#22c55e' : '#64748b';
                    ctx.fillRect((-10 + h * 8) * scale, -56 * scale, 6 * scale, 3 * scale);
                }

                ctx.restore();
            });
        }

        // 4. Attack 3 Sand Cloud In Flight (Swirling Homing Sacred Orb)
        if (mummy.sandCloud && mummy.sandCloud.active) {
            const sc = mummy.sandCloud;
            const cx = (sc.x - cameraX) * scale;
            const cy = (sc.y - cameraY) * scale;
            const r = sc.radius * scale;

            ctx.save();
            // Swirling sand vortex core
            const sGrad = ctx.createRadialGradient(cx, cy, r * 0.12, cx, cy, r);
            sGrad.addColorStop(0, 'rgba(254, 240, 138, 0.95)');
            sGrad.addColorStop(0.4, 'rgba(245, 158, 11, 0.85)');
            sGrad.addColorStop(0.75, 'rgba(217, 119, 6, 0.6)');
            sGrad.addColorStop(1, 'rgba(180, 83, 9, 0)');
            ctx.fillStyle = sGrad;
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.fill();

            // Swirling inner energy rings
            const rotTime = Date.now() * 0.012;
            ctx.strokeStyle = 'rgba(254, 243, 199, 0.75)';
            ctx.lineWidth = 2 * scale;
            for (let ring = 0; ring < 3; ring++) {
                ctx.beginPath();
                ctx.ellipse(cx, cy, r * (0.45 + ring * 0.2), r * (0.22 + ring * 0.12), rotTime + ring * 1.3, 0, Math.PI * 2);
                ctx.stroke();
            }
            ctx.restore();
        }

        // 5. Attack 4 Ground Shockwaves (Staff of Anubis)
        if (mummy.shockwaves && mummy.shockwaves.length > 0) {
            mummy.shockwaves.forEach(sw => {
                if (!sw.active) return;
                const wx = (sw.x - cameraX) * scale;
                const wy = (sw.y - cameraY) * scale;

                ctx.save();
                ctx.translate(wx, wy);

                // Rolling sand crest
                const wGrad = ctx.createLinearGradient(0, -sw.h * scale, 0, 0);
                wGrad.addColorStop(0, '#fef08a');
                wGrad.addColorStop(0.5, '#f59e0b');
                wGrad.addColorStop(1, '#78350f');
                ctx.fillStyle = wGrad;

                ctx.beginPath();
                ctx.moveTo(-sw.w * 0.5 * scale, 0);
                ctx.quadraticCurveTo(0, -sw.h * scale, sw.w * 0.5 * scale, 0);
                ctx.closePath();
                ctx.fill();

                ctx.strokeStyle = '#fde68a';
                ctx.lineWidth = 2.5 * scale;
                ctx.stroke();
                ctx.restore();
            });
        }

        // 6. Attack 5 Arena Tornado Vortex
        if (mummy.tornadoActive) {
            ctx.save();
            const tTime = Date.now() * 0.008;
            const vortexW = 120 * scale;
            const centerX = canvas.width / 2;

            // Swirling conical tornado spanning from ground to sky
            for (let yStep = 0; yStep < 18; yStep++) {
                const yPos = canvas.height - yStep * 32 * scale;
                const ringW = (35 + yStep * 14) * scale;
                const offX = Math.sin(tTime * 3 + yStep * 0.4) * 28 * scale;

                ctx.fillStyle = (yStep % 2 === 0) ? 'rgba(245, 158, 11, 0.22)' : 'rgba(217, 119, 6, 0.28)';
                ctx.beginPath();
                ctx.ellipse(centerX + offX, yPos, ringW, 14 * scale, 0, 0, Math.PI * 2);
                ctx.fill();
            }
            ctx.restore();
        }

        // 7. Collectible Golden Pyramids
        if (mummy.pyramids && mummy.pyramids.length > 0) {
            mummy.pyramids.forEach(pyr => {
                if (pyr.collected) return;
                const px = (pyr.x - cameraX) * scale;
                const py = (pyr.y - cameraY) * scale;
                const size = 18 * scale;

                ctx.save();
                ctx.translate(px, py);

                // Glowing halo ring
                const halo = ctx.createRadialGradient(0, 0, 4 * scale, 0, 0, 28 * scale);
                halo.addColorStop(0, 'rgba(253, 224, 71, 0.75)');
                halo.addColorStop(0.5, 'rgba(245, 158, 11, 0.35)');
                halo.addColorStop(1, 'rgba(245, 158, 11, 0)');
                ctx.fillStyle = halo;
                ctx.beginPath();
                ctx.arc(0, 0, 28 * scale, 0, Math.PI * 2);
                ctx.fill();

                // 3D Shaded Pyramid Faces
                // Left face (illuminated)
                ctx.fillStyle = '#fde047';
                ctx.beginPath();
                ctx.moveTo(0, -size);
                ctx.lineTo(-size, size * 0.7);
                ctx.lineTo(0, size * 0.85);
                ctx.closePath();
                ctx.fill();

                // Right face (shaded)
                ctx.fillStyle = '#d97706';
                ctx.beginPath();
                ctx.moveTo(0, -size);
                ctx.lineTo(0, size * 0.85);
                ctx.lineTo(size, size * 0.7);
                ctx.closePath();
                ctx.fill();

                // Golden outlines & Capstone
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.6 * scale;
                ctx.stroke();

                // Mini capstone gleam
                ctx.fillStyle = '#ffffff';
                ctx.beginPath();
                ctx.arc(0, -size * 0.8, 2.5 * scale, 0, Math.PI * 2);
                ctx.fill();

                ctx.restore();
            });
        }

        // 8. Pyramid Solar Beams to Mummy
        if (mummy.pyramidBeams && mummy.pyramidBeams.length > 0) {
            mummy.pyramidBeams.forEach(bm => {
                if (!bm.active) return;
                const sx = (bm.startX - cameraX) * scale;
                const sy = (bm.startY - cameraY) * scale;
                const cx = (bm.curX - cameraX) * scale;
                const cy = (bm.curY - cameraY) * scale;

                ctx.save();
                ctx.strokeStyle = '#fef08a';
                ctx.lineWidth = 5 * scale;
                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(cx, cy);
                ctx.stroke();

                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2.5 * scale;
                ctx.stroke();

                // Head burst
                ctx.fillStyle = '#fbbf24';
                ctx.beginPath();
                ctx.arc(cx, cy, 7 * scale, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            });
        }

        // 9. Mummy Defeat Confetti & Sand Explosion
        if (mummyDefeatCutscene.active && mummyDefeatCutscene.confetti) {
            ctx.save();
            mummyDefeatCutscene.confetti.forEach(c => {
                const cx = (c.x - cameraX) * scale;
                const cy = (c.y - cameraY) * scale;
                ctx.save();
                ctx.translate(cx, cy);
                ctx.rotate(c.rot);
                ctx.fillStyle = c.color;
                ctx.fillRect(-c.size * scale * 0.5, -c.size * scale * 0.5, c.size * scale, c.size * scale);
                ctx.restore();
            });
            ctx.restore();
        }
    }

    // --- DRAW ATTACK 3 SAND IN EYES OVERLAY ---
    function drawSandInEyesOverlay(scale) {
        if (currentLevelIndex !== 80 || !mummy.sandInEyesTimer || mummy.sandInEyesTimer <= 0) return;

        ctx.save();
        const intensity = Math.min(1.0, mummy.sandInEyesTimer / 2.5);

        // 1. Full-screen warm sandy blur veil
        ctx.fillStyle = `rgba(217, 119, 6, ${0.32 * intensity})`;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Heavy blurry sandy vignette (substantially blinds the view)
        const maxR = Math.max(canvas.width, canvas.height) * 0.75;
        const sVig = ctx.createRadialGradient(canvas.width / 2, canvas.height / 2, maxR * 0.1, canvas.width / 2, canvas.height / 2, maxR);
        sVig.addColorStop(0, `rgba(245, 158, 11, ${0.38 * intensity})`);
        sVig.addColorStop(0.35, `rgba(217, 119, 6, ${0.68 * intensity})`);
        sVig.addColorStop(0.7, `rgba(180, 83, 9, ${0.88 * intensity})`);
        sVig.addColorStop(1, `rgba(120, 53, 15, ${0.96 * intensity})`);
        ctx.fillStyle = sVig;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 3. Dense drifting sand dust specks across screen
        const dTime = Date.now() * 0.0035;
        ctx.fillStyle = 'rgba(254, 243, 199, 0.75)';
        for (let s = 0; s < 75; s++) {
            const sx = (Math.sin(s * 73 + dTime * (1 + (s % 3) * 0.4)) * 0.5 + 0.5) * canvas.width;
            const sy = (Math.cos(s * 41 + dTime * (1.2 + (s % 2) * 0.5)) * 0.5 + 0.5) * canvas.height;
            ctx.beginPath();
            ctx.arc(sx, sy, (1.8 + (s % 4)) * scale, 0, Math.PI * 2);
            ctx.fill();
        }

        // 4. Timer badge at top with progress bar
        const badgeW = 240 * scale;
        const badgeH = 32 * scale;
        const badgeX = canvas.width / 2 - badgeW / 2;
        const badgeY = 28 * scale;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.85)';
        ctx.fillRect(badgeX, badgeY, badgeW, badgeH);

        // Timer progress fill (7.0s max)
        const prog = Math.max(0, Math.min(1.0, mummy.sandInEyesTimer / 7.0));
        ctx.fillStyle = 'rgba(245, 158, 11, 0.35)';
        ctx.fillRect(badgeX, badgeY, badgeW * prog, badgeH);

        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 2 * scale;
        ctx.strokeRect(badgeX, badgeY, badgeW, badgeH);

        ctx.fillStyle = '#fef08a';
        ctx.font = `bold ${13 * scale}px Outfit, sans-serif`;
        ctx.textAlign = 'center';
        ctx.fillText(`⏳ ПЕСОК В ГЛАЗАХ (${mummy.sandInEyesTimer.toFixed(1)}с)`, canvas.width / 2, badgeY + 21 * scale);

        ctx.restore();
    }

    // --- DRAW ATTACK 5 QTE BALANCE BAR ---
    function drawQteBalanceBar(scale) {
        if (currentLevelIndex !== 80 || !mummy.qteActive) return;

        ctx.save();
        const barW = 340 * scale;
        const barH = 26 * scale;
        const barX = canvas.width / 2 - barW / 2;
        const barY = 82 * scale;

        // Container panel
        ctx.fillStyle = 'rgba(15, 23, 42, 0.88)';
        ctx.fillRect(barX - 16 * scale, barY - 26 * scale, barW + 32 * scale, barH + 52 * scale);
        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 2.5 * scale;
        ctx.strokeRect(barX - 16 * scale, barY - 26 * scale, barW + 32 * scale, barH + 52 * scale);

        // Title text
        ctx.fillStyle = '#fef08a';
        ctx.font = `900 ${12 * scale}px "Russo One", sans-serif`;
        ctx.textAlign = 'center';
        ctx.fillText('⚖️ УДЕРЖИВАЙТЕ РАВНОВЕСИЕ В ТОРНАДО!', canvas.width / 2, barY - 8 * scale);

        // Bar track background (Red hazard zones)
        ctx.fillStyle = '#ef4444';
        ctx.fillRect(barX, barY, barW, barH);

        // Green safe zone in center (0.36 to 0.64)
        const greenX = barX + mummy.qteGreenMin * barW;
        const greenW = (mummy.qteGreenMax - mummy.qteGreenMin) * barW;
        ctx.fillStyle = '#22c55e';
        ctx.fillRect(greenX, barY, greenW, barH);

        // Safe zone border & stripes
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2 * scale;
        ctx.strokeRect(greenX, barY, greenW, barH);

        // Track frame
        ctx.strokeStyle = '#0f172a';
        ctx.lineWidth = 2 * scale;
        ctx.strokeRect(barX, barY, barW, barH);

        // Oscillating Balance Needle
        const needleX = barX + mummy.qteSlider * barW;
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.moveTo(needleX, barY - 5 * scale);
        ctx.lineTo(needleX - 6 * scale, barY - 14 * scale);
        ctx.lineTo(needleX + 6 * scale, barY - 14 * scale);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 3.5 * scale;
        ctx.beginPath();
        ctx.moveTo(needleX, barY - 4 * scale);
        ctx.lineTo(needleX, barY + barH + 4 * scale);
        ctx.stroke();

        // Prompt hint
        ctx.fillStyle = '#e2e8f0';
        ctx.font = `600 ${11 * scale}px Outfit, sans-serif`;
        ctx.fillText('Нажмите [ ПРОБЕЛ ] или [ ЛКМ ] в зелёной зоне!', canvas.width / 2, barY + barH + 18 * scale);

        ctx.restore();
    }

    if (btnSkipCutscene) {
        btnSkipCutscene.addEventListener('click', () => {
            if (typeof cutsceneIntro81 !== 'undefined' && cutsceneIntro81 && cutsceneIntro81.active) {
                finishLevel81IntroCutscene();
            } else if (typeof cutsceneIntro61 !== 'undefined' && cutsceneIntro61 && cutsceneIntro61.active) {
                finishLevel61IntroCutscene();
            } else if (cutsceneIntro21 && cutsceneIntro21.active) {
                finishLevel21IntroCutscene();
            } else if (cutsceneIntro41 && cutsceneIntro41.active) {
                finishLevel41IntroCutscene();
            } else if (typeof golemCutscene !== 'undefined' && golemCutscene && golemCutscene.active) {
                finishGolemDefeatCutscene();
            } else if (typeof golemIntroCutscene !== 'undefined' && golemIntroCutscene && golemIntroCutscene.active) {
                finishGolemIntroCutscene();
            } else if (typeof yetiIntroCutscene !== 'undefined' && yetiIntroCutscene && yetiIntroCutscene.active) {
                finishYetiIntroCutscene();
            } else if (typeof yetiDefeatCutscene !== 'undefined' && yetiDefeatCutscene && yetiDefeatCutscene.active) {
                finishYetiDefeatCutscene();
            } else if (typeof mummyIntroCutscene !== 'undefined' && mummyIntroCutscene && mummyIntroCutscene.active) {
                finishMummyIntroCutscene();
            } else if (typeof mummyDefeatCutscene !== 'undefined' && mummyDefeatCutscene && mummyDefeatCutscene.active) {
                finishMummyDefeatCutscene();
            } else if (typeof samuraiIntroCutscene !== 'undefined' && samuraiIntroCutscene && samuraiIntroCutscene.active) {
                finishSamuraiIntroCutscene();
            } else if (typeof samuraiDefeatCutscene !== 'undefined' && samuraiDefeatCutscene && samuraiDefeatCutscene.active) {
                finishSamuraiDefeatCutscene();
            } else if (typeof cutsceneIntro101 !== 'undefined' && cutsceneIntro101 && cutsceneIntro101.active) {
                finishLevel101IntroCutscene();
            }
        });
    }

    // =========================================================================
    // --- PAGE 6: SKY ISLANDS (НЕБЕСНЫЕ ОСТРОВА) INTRO CUTSCENE & RENDERING ---
    // =========================================================================
    const cutsceneIntro101 = {
        active: false,
        phase: 'SAKURA_ASCEND', // 'SAKURA_ASCEND' -> 'SKY_TRANSFORM' -> 'LAND_ISLAND'
        timer: 0,
        altitude: 0,      // 0 = Sakura ground, 1 = high sky clouds, 2 = Sky Islands!
        glowIntensity: 0,
        rings: [],
        swirlParticles: []
    };

    const ambientSky = [];
    for (let i = 0; i < 42; i++) {
        ambientSky.push({
            x: Math.random() * 1400,
            y: Math.random() * 675,
            vx: -(0.35 + Math.random() * 0.75),
            vy: (Math.random() - 0.5) * 0.2,
            size: 2 + Math.random() * 3.5,
            alpha: 0.25 + Math.random() * 0.45,
            isStreak: Math.random() < 0.35
        });
    }

    function updateAmbientSky() {
        for (let i = 0; i < ambientSky.length; i++) {
            const p = ambientSky[i];
            p.x += p.vx;
            p.y += p.vy;
            if (p.x < -60) p.x = width + 60;
            if (p.y < -30) p.y = 690;
            if (p.y > 700) p.y = -20;
        }
    }

    function drawAmbientSky(scale) {
        ctx.save();
        for (let i = 0; i < ambientSky.length; i++) {
            const p = ambientSky[i];
            const sx = p.x * scale;
            const sy = p.y * scale;
            ctx.globalAlpha = p.alpha;
            if (p.isStreak) {
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
                ctx.lineWidth = 1.6 * scale;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx + 26 * scale, sy);
                ctx.stroke();
            } else {
                ctx.fillStyle = '#fef9c3';
                ctx.beginPath();
                ctx.arc(sx, sy, p.size * scale, 0, Math.PI * 2);
                ctx.fill();
            }
        }
        ctx.restore();
    }

    function startLevel101IntroCutscene() {
        currentState = STATES.CUTSCENE;
        cutsceneIntro101.active = true;
        cutsceneIntro101.phase = 'SAKURA_ASCEND';
        cutsceneIntro101.timer = 0;
        cutsceneIntro101.altitude = 0;
        cutsceneIntro101.glowIntensity = 0;
        cutsceneIntro101.rings = [];
        cutsceneIntro101.swirlParticles = [];

        if (hudOverlay) hudOverlay.classList.add('hidden');
        if (inventoryHud) inventoryHud.classList.add('hidden');
        if (coldHud) coldHud.classList.add('hidden');
        if (healthHud) healthHud.classList.add('hidden');
        if (thirstHud) thirstHud.classList.add('hidden');
        if (bossHud) bossHud.classList.add('hidden');
        if (samuraiSkillsHud) samuraiSkillsHud.classList.add('hidden');

        if (cutsceneOverlay) {
            cutsceneOverlay.classList.remove('hidden');
            const hintEl = cutsceneOverlay.querySelector('.cutscene-hint');
            if (hintEl) hintEl.textContent = 'Нажмите [Пробел] чтобы пропустить катсцену';
        }
        resetCutsceneChapterStyle();
        if (cutsceneChapter) cutsceneChapter.textContent = '☁️ СТРАНИЦА 6: НЕБЕСНЫЕ ОСТРОВА';
        if (cutsceneText) cutsceneText.textContent = 'Сверкающий небесный столб света поднимает героя прямо из цветущей Японии высоко в небо...';

        // Player starts in Sakura Japanese outfit before ascending into the sky!
        player.x = 320;
        player.y = 540;
        player.vx = 0;
        player.vy = 0;
        player.facing = 1;
        player.state = 'IDLE';
        player.grounded = true;
        player.hasSamuraiOutfit = true;
        player.katanaDrawn = false;
        player.health = 100;

        cameraX = 0;
        cameraY = 0;
        playSound('skyAscend');
    }

    function updateCutsceneIntro101() {
        if (!cutsceneIntro101.active) return;
        cutsceneIntro101.timer += 0.016;
        updateAmbientSky();

        for (let i = cutsceneIntro101.rings.length - 1; i >= 0; i--) {
            const r = cutsceneIntro101.rings[i];
            r.radius += r.speed;
            r.alpha -= 0.022;
            if (r.alpha <= 0) cutsceneIntro101.rings.splice(i, 1);
        }
        for (let i = cutsceneIntro101.swirlParticles.length - 1; i >= 0; i--) {
            const sp = cutsceneIntro101.swirlParticles[i];
            sp.angle += sp.angSpeed;
            sp.y -= sp.vy;
            sp.radius += sp.radSpeed;
            sp.alpha -= 0.015;
            if (sp.alpha <= 0) cutsceneIntro101.swirlParticles.splice(i, 1);
        }

        if (cutsceneIntro101.phase === 'SAKURA_ASCEND') {
            const t = Math.min(1, cutsceneIntro101.timer / 2.2);
            cutsceneIntro101.altitude = t * t; // 0 -> 1 ascending from Sakura town into open sky
            cutsceneIntro101.glowIntensity = Math.min(0.65, t * 0.75);
            player.state = t > 0.18 ? 'JUMP' : 'IDLE';
            player.y = 540 - t * 210;
            player.animTime += 0.1;

            if (Math.random() < 0.75) {
                cutsceneIntro101.swirlParticles.push({
                    angle: Math.random() * Math.PI * 2,
                    angSpeed: 0.1,
                    radius: 18 + Math.random() * 26,
                    radSpeed: 0.2,
                    y: player.y - Math.random() * 65,
                    vy: 2.2 + Math.random() * 2.2,
                    size: 3 + Math.random() * 3.5,
                    color: Math.random() < 0.5 ? '#f9a8d4' : '#fef08a',
                    alpha: 0.9
                });
            }

            if (cutsceneIntro101.timer >= 2.25) {
                cutsceneIntro101.phase = 'SKY_TRANSFORM';
                cutsceneIntro101.timer = 0;
                playSound('sakuraGlow');
                cutsceneIntro101.rings.push({ radius: 12, speed: 4.8, alpha: 0.95, color: '#ffffff' });
                cutsceneIntro101.rings.push({ radius: 6, speed: 3.4, alpha: 0.9, color: '#7dd3fc' });
                if (cutsceneChapter) cutsceneChapter.textContent = '✨ ПРЕОБРАЖЕНИЕ В НЕБЕСАХ';
                if (cutsceneText) cutsceneText.textContent = 'В потоке чистого небесного ветра японская одежда и катана исчезают — герой вновь становится обычным стикменом!';
            }
        } else if (cutsceneIntro101.phase === 'SKY_TRANSFORM') {
            const p = Math.min(1, cutsceneIntro101.timer / 2.1);
            cutsceneIntro101.altitude = 1 + p * 0.5;
            cutsceneIntro101.glowIntensity = Math.sin(p * Math.PI);
            player.y = 330 + Math.sin(cutsceneIntro101.timer * 4) * 10;
            player.state = 'JUMP';
            player.animTime += 0.08;

            if (Math.random() < 0.8) {
                cutsceneIntro101.swirlParticles.push({
                    angle: Math.random() * Math.PI * 2,
                    angSpeed: 0.12,
                    radius: 14 + Math.random() * 32,
                    radSpeed: 0.55,
                    y: player.y - 10 - Math.random() * 50,
                    vy: 1.4 + Math.random() * 2.0,
                    size: 3 + Math.random() * 4,
                    color: p < 0.5 ? '#f472b6' : (Math.random() < 0.5 ? '#ffffff' : '#38bdf8'),
                    alpha: 0.95
                });
            }

            // At peak light flash: Japanese outfit & katana vanish, player becomes normal stickman!
            if (p >= 0.48 && player.hasSamuraiOutfit) {
                player.hasSamuraiOutfit = false;
                player.katanaDrawn = false;
                screenShake = 8;
                cutsceneIntro101.rings.push({ radius: 16, speed: 6.2, alpha: 1.0, color: '#fef08a' });
                cutsceneIntro101.rings.push({ radius: 10, speed: 4.5, alpha: 0.95, color: '#38bdf8' });
            }

            if (cutsceneIntro101.timer >= 2.2) {
                cutsceneIntro101.phase = 'LAND_ISLAND';
                cutsceneIntro101.timer = 0;
                playSound('skyAscend');
                if (cutsceneChapter) cutsceneChapter.textContent = '🏝️ НЕБЕСНЫЕ ОСТРОВА';
                if (cutsceneText) cutsceneText.textContent = 'Облака расступаются, открывая парящие небесные острова, облака-батуты и сияющие храмы!';
            }
        } else if (cutsceneIntro101.phase === 'LAND_ISLAND') {
            const t = Math.min(1, cutsceneIntro101.timer / 1.5);
            cutsceneIntro101.altitude = 1.5 + t * 0.5;
            cutsceneIntro101.glowIntensity = Math.max(0, 0.25 * (1 - t));
            // Smooth descent onto the first floating sky island
            const easeOut = 1 - Math.pow(1 - t, 3);
            player.y = 330 + easeOut * (540 - 330);
            player.state = t < 0.92 ? 'JUMP' : 'IDLE';
            player.animTime += 0.08;

            if (cutsceneIntro101.timer >= 1.95) {
                finishLevel101IntroCutscene();
            }
        }
    }

    function finishLevel101IntroCutscene() {
        if (!cutsceneIntro101.active) return;
        cutsceneIntro101.active = false;
        cutsceneIntro101.glowIntensity = 0;
        resetCutsceneChapterStyle();
        if (cutsceneOverlay) cutsceneOverlay.classList.add('hidden');
        triggerFadeTransition(() => {
            loadLevel(101);
            player.reset();
            player.hasSamuraiOutfit = false;
            player.katanaDrawn = false;
            if (hudOverlay) hudOverlay.classList.remove('hidden');
            if (inventoryHud) inventoryHud.classList.add('hidden');
            if (coldHud) coldHud.classList.add('hidden');
            if (thirstHud) thirstHud.classList.add('hidden');
            if (healthHud) {
                healthHud.classList.remove('hidden');
                updateHealthHud();
            }
            currentState = STATES.PLAYING;
        });
    }

    function drawCutscene101Scene(scale) {
        const alt = cutsceneIntro101.altitude; // 0 (Sakura) -> 1 (Clouds) -> 2 (Sky Islands)
        const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
        if (alt < 1) {
            skyGrad.addColorStop(0, '#0284c7');
            skyGrad.addColorStop(0.55, '#7dd3fc');
            skyGrad.addColorStop(1, '#fbcfe8');
        } else {
            skyGrad.addColorStop(0, '#0284c7');
            skyGrad.addColorStop(0.45, '#38bdf8');
            skyGrad.addColorStop(0.85, '#bae6fd');
            skyGrad.addColorStop(1, '#f0f9ff');
        }
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Radiant Sun in clear sky
        const sunX = canvas.width - 210 * scale;
        const sunY = (115 - Math.min(1, alt) * 10) * scale;
        const sunHalo = ctx.createRadialGradient(sunX, sunY, 12 * scale, sunX, sunY, 130 * scale);
        sunHalo.addColorStop(0, '#ffffff');
        sunHalo.addColorStop(0.28, '#fef08a');
        sunHalo.addColorStop(0.62, 'rgba(253, 224, 71, 0.32)');
        sunHalo.addColorStop(1, 'rgba(253, 224, 71, 0)');
        ctx.fillStyle = sunHalo;
        ctx.beginPath();
        ctx.arc(sunX, sunY, 130 * scale, 0, Math.PI * 2);
        ctx.fill();

        // Phase 1 receding Sakura ground & torii shrinking below as player ascends!
        if (alt < 1.15) {
            const dropY = alt * 340 * scale;
            const gY = (540 - cameraY) * scale + dropY;
            ctx.save();
            ctx.globalAlpha = Math.max(0, 1 - alt * 0.9);
            ctx.fillStyle = '#334155';
            ctx.fillRect(0, gY, canvas.width, 220 * scale);
            ctx.fillStyle = '#22c55e';
            ctx.fillRect(0, gY, canvas.width, 8 * scale);
            // Distant crimson Torii silhouette on ground
            const tx = 580 * scale;
            ctx.fillStyle = '#dc2626';
            ctx.fillRect(tx - 44 * scale, gY - 120 * scale, 12 * scale, 120 * scale);
            ctx.fillRect(tx + 32 * scale, gY - 120 * scale, 12 * scale, 120 * scale);
            ctx.fillRect(tx - 60 * scale, gY - 122 * scale, 120 * scale, 12 * scale);
            ctx.fillStyle = '#f472b6';
            ctx.beginPath();
            ctx.arc(160 * scale, gY - 85 * scale, 52 * scale, 0, Math.PI * 2);
            ctx.arc(820 * scale, gY - 92 * scale, 58 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }

        // Passing fluffy clouds rushing downward during ascent
        ctx.save();
        ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
        for (let i = 0; i < 6; i++) {
            const cx = ((i * 250 + 90) % 1300) * scale;
            const cy = ((i * 115 + alt * 260) % 620) * scale;
            ctx.beginPath();
            ctx.arc(cx, cy, 30 * scale, 0, Math.PI * 2);
            ctx.arc(cx + 28 * scale, cy - 6 * scale, 24 * scale, 0, Math.PI * 2);
            ctx.arc(cx - 26 * scale, cy - 4 * scale, 22 * scale, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();

        // Phase 3 Floating Sky Island rising into view under the player!
        if (alt >= 1.35) {
            const islandProg = Math.min(1, (alt - 1.35) / 0.55);
            const islandY = (540 + (1 - islandProg) * 180) * scale;
            const ix = 120 * scale;
            const iw = 440 * scale;
            ctx.save();
            // Tapered floating sky-island rock bottom
            const rGrad = ctx.createLinearGradient(ix, islandY, ix, islandY + 130 * scale);
            rGrad.addColorStop(0, '#cbd5e1');
            rGrad.addColorStop(0.45, '#94a3b8');
            rGrad.addColorStop(1, '#475569');
            ctx.fillStyle = rGrad;
            ctx.beginPath();
            ctx.moveTo(ix, islandY);
            ctx.lineTo(ix + iw, islandY);
            ctx.lineTo(ix + iw - 48 * scale, islandY + 75 * scale);
            ctx.lineTo(ix + iw * 0.52, islandY + 135 * scale);
            ctx.lineTo(ix + 52 * scale, islandY + 80 * scale);
            ctx.closePath();
            ctx.fill();
            // Lush sunlit grass top
            ctx.fillStyle = '#22c55e';
            ctx.fillRect(ix, islandY, iw, 12 * scale);
            ctx.fillStyle = '#4ade80';
            ctx.fillRect(ix, islandY, iw, 4 * scale);
            ctx.restore();
        }

        // Radiant Ascension Beam & Transformation Glow around Player
        const px = (player.x - cameraX) * scale;
        const py = (player.y - 38 - cameraY) * scale;
        if (cutsceneIntro101.glowIntensity > 0.02) {
            ctx.save();
            const beamGrad = ctx.createLinearGradient(px - 65 * scale, 0, px + 65 * scale, 0);
            beamGrad.addColorStop(0, 'rgba(186, 230, 253, 0)');
            beamGrad.addColorStop(0.5, `rgba(254, 249, 195, ${0.42 * cutsceneIntro101.glowIntensity})`);
            beamGrad.addColorStop(1, 'rgba(186, 230, 253, 0)');
            ctx.fillStyle = beamGrad;
            ctx.fillRect(px - 65 * scale, 0, 130 * scale, canvas.height);

            const orbGrad = ctx.createRadialGradient(px, py, 6 * scale, px, py, 95 * scale);
            orbGrad.addColorStop(0, `rgba(255, 255, 255, ${0.95 * cutsceneIntro101.glowIntensity})`);
            orbGrad.addColorStop(0.45, `rgba(125, 211, 252, ${0.6 * cutsceneIntro101.glowIntensity})`);
            orbGrad.addColorStop(1, 'rgba(56, 189, 248, 0)');
            ctx.fillStyle = orbGrad;
            ctx.beginPath();
            ctx.arc(px, py, 95 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        }

        // Expanding Sky Rings & Swirling Particles
        cutsceneIntro101.rings.forEach(r => {
            ctx.save();
            ctx.strokeStyle = r.color;
            ctx.globalAlpha = Math.max(0, r.alpha);
            ctx.lineWidth = 3.5 * scale;
            ctx.beginPath();
            ctx.arc(px, py, r.radius * scale, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        });
        cutsceneIntro101.swirlParticles.forEach(sp => {
            const sx = px + Math.cos(sp.angle) * sp.radius * scale;
            const sy = (sp.y - cameraY) * scale;
            ctx.save();
            ctx.globalAlpha = Math.max(0, sp.alpha);
            ctx.fillStyle = sp.color;
            ctx.beginPath();
            ctx.arc(sx, sy, sp.size * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });
        drawAmbientSky(scale);
    }

    // --- SKY ISLANDS CLEAR DAYTIME BACKGROUND (SUN, CLOUDS, FLOATING BACKGROUND ISLANDS) ---
    function drawSkyBackground(scale) {
        // 1. Radiant Clear Daytime Azure Sky
        const skyGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
        skyGrad.addColorStop(0, '#0284c7');    // clear zenith azure
        skyGrad.addColorStop(0.38, '#38bdf8'); // vibrant sky blue
        skyGrad.addColorStop(0.76, '#bae6fd'); // bright sunlit horizon mist
        skyGrad.addColorStop(1, '#f0f9ff');    // cloud sea glow below
        ctx.fillStyle = skyGrad;
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Warm Radiant Sun with Soft Rays
        const sunX = canvas.width - 210 * scale;
        const sunY = 112 * scale;
        const sunHalo = ctx.createRadialGradient(sunX, sunY, 14 * scale, sunX, sunY, 155 * scale);
        sunHalo.addColorStop(0, '#ffffff');
        sunHalo.addColorStop(0.24, '#fef08a');
        sunHalo.addColorStop(0.55, 'rgba(253, 224, 71, 0.34)');
        sunHalo.addColorStop(1, 'rgba(253, 224, 71, 0)');
        ctx.fillStyle = sunHalo;
        ctx.beginPath();
        ctx.arc(sunX, sunY, 155 * scale, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#fffbeb';
        ctx.beginPath();
        ctx.arc(sunX, sunY, 34 * scale, 0, Math.PI * 2);
        ctx.fill();

        // 3. Distant Parallax Fluffy Clouds
        const timeDrift = Date.now() * 0.008;
        ctx.save();
        ctx.fillStyle = 'rgba(255, 255, 255, 0.86)';
        const farCloudStep = 370 * scale;
        const farCloudOff = -((cameraX * 0.045 + timeDrift * 0.6) * scale) % farCloudStep;
        for (let cx = farCloudOff - farCloudStep; cx < canvas.width + farCloudStep; cx += farCloudStep) {
            const idx = Math.round((cx - farCloudOff) / farCloudStep);
            const cy = (88 + Math.abs(Math.sin(idx * 1.7)) * 75) * scale;
            ctx.beginPath();
            ctx.arc(cx, cy, 26 * scale, 0, Math.PI * 2);
            ctx.arc(cx + 26 * scale, cy - 8 * scale, 22 * scale, 0, Math.PI * 2);
            ctx.arc(cx + 50 * scale, cy + 2 * scale, 19 * scale, 0, Math.PI * 2);
            ctx.arc(cx - 24 * scale, cy + 2 * scale, 20 * scale, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();

        // 4. Distant Background Floating Sky Islands (Parallax Layer 1 & 2 with Grass, Rock Bottoms & Tiny Waterfalls!)
        const drawBgIsland = (ix, iy, iw, ih, hasTemple, hasWaterfall) => {
            ctx.save();
            // Tapered floating rock underside
            const rGrad = ctx.createLinearGradient(ix, iy, ix, iy + ih);
            rGrad.addColorStop(0, '#94a3b8');
            rGrad.addColorStop(0.5, '#64748b');
            rGrad.addColorStop(1, '#334155');
            ctx.fillStyle = rGrad;
            ctx.beginPath();
            ctx.moveTo(ix, iy);
            ctx.lineTo(ix + iw, iy);
            ctx.lineTo(ix + iw * 0.84, iy + ih * 0.56);
            ctx.lineTo(ix + iw * 0.52, iy + ih);
            ctx.lineTo(ix + iw * 0.16, iy + ih * 0.58);
            ctx.closePath();
            ctx.fill();

            // Lush emerald grass cap
            ctx.fillStyle = '#22c55e';
            ctx.beginPath();
            ctx.roundRect(ix - 3 * scale, iy - 5 * scale, iw + 6 * scale, 11 * scale, 5 * scale);
            ctx.fill();
            ctx.fillStyle = '#86efac';
            ctx.fillRect(ix, iy - 5 * scale, iw, 3 * scale);

            // Optional tiny distant white sky-temple on the background island
            if (hasTemple) {
                const tx = ix + iw * 0.5;
                ctx.fillStyle = 'rgba(248, 250, 252, 0.9)';
                ctx.fillRect(tx - 18 * scale, iy - 28 * scale, 36 * scale, 23 * scale);
                ctx.fillStyle = '#fbbf24';
                ctx.beginPath();
                ctx.moveTo(tx - 24 * scale, iy - 28 * scale);
                ctx.lineTo(tx, iy - 42 * scale);
                ctx.lineTo(tx + 24 * scale, iy - 28 * scale);
                ctx.closePath();
                ctx.fill();
            }

            // Optional cascading sky waterfall dissolving into mist
            if (hasWaterfall) {
                const wx = ix + iw * 0.68;
                const wfGrad = ctx.createLinearGradient(wx, iy, wx, iy + ih * 1.45);
                wfGrad.addColorStop(0, 'rgba(186, 230, 253, 0.82)');
                wfGrad.addColorStop(1, 'rgba(224, 242, 254, 0)');
                ctx.fillStyle = wfGrad;
                ctx.fillRect(wx, iy + 2 * scale, 8 * scale, ih * 1.4);
            }
            ctx.restore();
        };

        const bgIslandStep = 520 * scale;
        const bgIslandOff = -(cameraX * 0.14 * scale) % bgIslandStep;
        for (let n = -1; n <= Math.ceil(canvas.width / bgIslandStep) + 1; n++) {
            const ix = bgIslandOff + n * bgIslandStep + 60 * scale;
            const bob = Math.sin(Date.now() * 0.0014 + n * 1.9) * 6 * scale;
            const iy = (225 + (Math.abs(n) % 3) * 58) * scale + bob;
            const iw = (135 + (Math.abs(n) % 2) * 55) * scale;
            const ih = (62 + (Math.abs(n) % 2) * 24) * scale;
            drawBgIsland(ix, iy, iw, ih, Math.abs(n) % 2 === 0, Math.abs(n) % 3 === 1);
        }

        // 5. Lower Cloud Sea Billows Beneath the Islands
        ctx.save();
        ctx.fillStyle = 'rgba(255, 255, 255, 0.72)';
        const seaStep = 260 * scale;
        const seaOff = -(cameraX * 0.08 * scale) % seaStep;
        const seaY = canvas.height - 22 * scale;
        for (let sx = seaOff - seaStep; sx < canvas.width + seaStep; sx += seaStep) {
            ctx.beginPath();
            ctx.arc(sx, seaY, 58 * scale, 0, Math.PI * 2);
            ctx.arc(sx + 70 * scale, seaY + 8 * scale, 52 * scale, 0, Math.PI * 2);
            ctx.arc(sx + 145 * scale, seaY - 4 * scale, 64 * scale, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();

        drawAmbientSky(scale);
    }

    // --- DRAW SCULPTED FLOATING SKY ISLAND GROUND SEGMENTS (AROUND CHASMS) ---
    function drawSkyFloatingIslands(scale) {
        const groundY = currentLevelData.groundY || 540;
        const worldW = currentLevelData.worldWidth || 12000;
        const chasms = (currentLevelData.chasms || []).slice().sort((a, b) => a.startX - b.startX);

        // Compute solid island spans between chasms
        const islands = [];
        let start = 0;
        chasms.forEach(c => {
            if (c.startX > start) islands.push({ x1: start, x2: c.startX });
            start = c.endX;
        });
        if (start < worldW) islands.push({ x1: start, x2: worldW });

        const topY = (groundY - cameraY) * scale;

        islands.forEach((isl, idx) => {
            const leftX = (isl.x1 - cameraX) * scale;
            const rightX = (isl.x2 - cameraX) * scale;
            const iw = rightX - leftX;
            if (rightX < -120 || leftX > canvas.width + 120) return;

            ctx.save();
            // Tapered Floating Island Cliff Underside
            const rockGrad = ctx.createLinearGradient(0, topY, 0, topY + 175 * scale);
            rockGrad.addColorStop(0, '#e2e8f0');
            rockGrad.addColorStop(0.28, '#cbd5e1');
            rockGrad.addColorStop(0.65, '#64748b');
            rockGrad.addColorStop(1, '#334155');
            ctx.fillStyle = rockGrad;
            ctx.beginPath();
            ctx.moveTo(leftX, topY);
            ctx.lineTo(rightX, topY);
            ctx.lineTo(rightX - Math.min(iw * 0.08, 44 * scale), topY + 72 * scale);
            ctx.lineTo(rightX - Math.min(iw * 0.18, 120 * scale), topY + 128 * scale);
            ctx.lineTo(leftX + iw * 0.5, topY + 158 * scale);
            ctx.lineTo(leftX + Math.min(iw * 0.18, 120 * scale), topY + 122 * scale);
            ctx.lineTo(leftX + Math.min(iw * 0.08, 44 * scale), topY + 70 * scale);
            ctx.closePath();
            ctx.fill();

            // Golden Marble Edge Trim along cliff top
            ctx.fillStyle = '#fde68a';
            ctx.fillRect(leftX, topY + 11 * scale, iw, 5 * scale);

            // Lush Sunlit Emerald Grass Turf
            const grassGrad = ctx.createLinearGradient(0, topY, 0, topY + 12 * scale);
            grassGrad.addColorStop(0, '#4ade80');
            grassGrad.addColorStop(1, '#16a34a');
            ctx.fillStyle = grassGrad;
            ctx.fillRect(leftX, topY, iw, 12 * scale);

            // Little decorative grass blades & sky flowers along island surface
            const step = 36;
            const visMin = Math.max(isl.x1 + 16, Math.floor((cameraX - 40) / step) * step);
            const visMax = Math.min(isl.x2 - 16, Math.ceil((cameraX + canvas.width / scale + 40) / step) * step);
            for (let wx = visMin; wx <= visMax; wx += step) {
                const gx = (wx - cameraX) * scale;
                ctx.fillStyle = '#86efac';
                ctx.beginPath();
                ctx.moveTo(gx - 2 * scale, topY);
                ctx.lineTo(gx + 1 * scale, topY - 7 * scale);
                ctx.lineTo(gx + 4 * scale, topY);
                ctx.fill();
                if ((wx / step) % 3 === 0) {
                    ctx.fillStyle = '#fef08a';
                    ctx.beginPath();
                    ctx.arc(gx + 8 * scale, topY - 3 * scale, 2.6 * scale, 0, Math.PI * 2);
                    ctx.fill();
                }
            }

            // Soft cloud wisps drifting under the floating island
            ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
            ctx.beginPath();
            ctx.ellipse(leftX + iw * 0.25, topY + 132 * scale, 52 * scale, 14 * scale, 0, 0, Math.PI * 2);
            ctx.ellipse(leftX + iw * 0.75, topY + 138 * scale, 58 * scale, 15 * scale, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
        });
    }

    // --- DRAW BOUNCY TRAMPOLINE CLOUD (ОБЛАКО ДЛЯ ОТСКОКА) ---
    function drawSkyBounceCloud(cloud, scale) {
        const cx = (cloud.x - cameraX) * scale;
        const cy = (cloud.y - cameraY) * scale;
        const w = (cloud.w || 110) * scale;
        const h = (cloud.h || 36) * scale;
        if (cx + w < -90 || cx - w > canvas.width + 90) return;

        // Juicy spring squish deformation when bounced on!
        const sq = cloud.squishTimer || 0;
        const squishWave = sq > 0 ? Math.sin((sq / 0.36) * Math.PI * 2.5) * (sq / 0.36) : 0;
        const scaleX = 1 + squishWave * 0.22;
        const scaleY = 1 - squishWave * 0.28;
        const floatY = Math.sin(Date.now() * 0.003 + cloud.x * 0.02) * 3 * scale;

        ctx.save();
        ctx.translate(cx, cy + h * 0.35 + floatY);
        ctx.scale(scaleX, scaleY);

        // Soft glowing sunlit halo under the bouncy cloud
        const halo = ctx.createRadialGradient(0, 0, 6 * scale, 0, 0, w * 0.65);
        halo.addColorStop(0, 'rgba(254, 240, 138, 0.45)');
        halo.addColorStop(1, 'rgba(186, 230, 253, 0)');
        ctx.fillStyle = halo;
        ctx.beginPath();
        ctx.ellipse(0, 4 * scale, w * 0.65, h * 0.8, 0, 0, Math.PI * 2);
        ctx.fill();

        // Soft sky-blue cloud underside shadow
        ctx.fillStyle = '#bae6fd';
        ctx.beginPath();
        ctx.ellipse(0, 6 * scale, w * 0.46, h * 0.44, 0, 0, Math.PI * 2);
        ctx.fill();

        // Plump multi-puff gleaming white cumulus cloud body
        ctx.fillStyle = '#ffffff';
        ctx.strokeStyle = '#7dd3fc';
        ctx.lineWidth = 2 * scale;
        ctx.beginPath();
        ctx.arc(-w * 0.28, 1 * scale, h * 0.46, 0, Math.PI * 2);
        ctx.arc(-w * 0.10, -h * 0.18, h * 0.54, 0, Math.PI * 2);
        ctx.arc(w * 0.13, -h * 0.14, h * 0.52, 0, Math.PI * 2);
        ctx.arc(w * 0.30, 2 * scale, h * 0.43, 0, Math.PI * 2);
        ctx.ellipse(0, 4 * scale, w * 0.42, h * 0.36, 0, 0, Math.PI * 2);
        ctx.fill();

        // Golden sunlit rim highlight on top
        ctx.strokeStyle = 'rgba(254, 240, 138, 0.9)';
        ctx.lineWidth = 2.4 * scale;
        ctx.beginPath();
        ctx.arc(-w * 0.10, -h * 0.18, h * 0.46, Math.PI * 1.15, Math.PI * 1.85);
        ctx.stroke();

        // Subtle animated upward bounce chevrons (shows it's a trampoline cloud!)
        const chevPulse = Math.sin(Date.now() * 0.008 + cloud.x) * 3 * scale;
        ctx.strokeStyle = '#0284c7';
        ctx.lineWidth = 2.4 * scale;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.beginPath();
        ctx.moveTo(-7 * scale, 1 * scale - chevPulse);
        ctx.lineTo(0, -6 * scale - chevPulse);
        ctx.lineTo(7 * scale, 1 * scale - chevPulse);
        ctx.stroke();

        ctx.restore();
    }

    // --- DRAW CELESTIAL SKY BUILDINGS (TEMPLE, OBSERVATORY, TOWER, ARCH) ---
    function drawSkyBuilding(box, scale) {
        const drawX = (box.x - cameraX) * scale;
        const drawY = (box.y - cameraY) * scale;
        const drawW = box.w * scale;
        const drawH = box.h * scale;
        if (drawX + drawW < -100 || drawX > canvas.width + 100) return;

        const style = box.skyStyle || 'temple';
        ctx.save();

        // Sunlit Ivory White Marble Facade
        const marbleGrad = ctx.createLinearGradient(drawX, drawY, drawX + drawW, drawY + drawH);
        marbleGrad.addColorStop(0, '#ffffff');
        marbleGrad.addColorStop(0.5, '#f1f5f9');
        marbleGrad.addColorStop(1, '#cbd5e1');
        ctx.fillStyle = marbleGrad;
        ctx.fillRect(drawX, drawY, drawW, drawH);

        // Golden Celestial Border & Cornice
        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 2.5 * scale;
        ctx.strokeRect(drawX, drawY, drawW, drawH);

        // Top Gold & Azure Roof Deck Trim
        ctx.fillStyle = '#38bdf8';
        ctx.fillRect(drawX - 4 * scale, drawY, drawW + 8 * scale, 10 * scale);
        ctx.fillStyle = '#fbbf24';
        ctx.fillRect(drawX - 6 * scale, drawY, drawW + 12 * scale, 4 * scale);

        // Fluted Classical Columns along sides
        const colW = 14 * scale;
        [drawX + 10 * scale, drawX + drawW - 10 * scale - colW].forEach(cx => {
            ctx.fillStyle = '#e2e8f0';
            ctx.fillRect(cx, drawY + 10 * scale, colW, drawH - 10 * scale);
            ctx.strokeStyle = '#94a3b8';
            ctx.lineWidth = 1.2 * scale;
            ctx.strokeRect(cx, drawY + 10 * scale, colW, drawH - 10 * scale);
            // Gold capital
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(cx - 2 * scale, drawY + 10 * scale, colW + 4 * scale, 6 * scale);
        });

        // Style-specific Celestial Architectural Accents
        if (style === 'arch') {
            // Grand sunlit sky archway cutout look
            const archW = drawW * 0.48;
            const archH = Math.min(drawH * 0.65, 95 * scale);
            const ax = drawX + (drawW - archW) * 0.5;
            const ay = drawY + drawH - archH;
            ctx.fillStyle = '#7dd3fc';
            ctx.beginPath();
            ctx.arc(ax + archW * 0.5, ay + archW * 0.35, archW * 0.5, Math.PI, 0);
            ctx.lineTo(ax + archW, drawY + drawH);
            ctx.lineTo(ax, drawY + drawH);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#f59e0b';
            ctx.lineWidth = 2.5 * scale;
            ctx.stroke();
        } else if (style === 'observatory') {
            // Glowing Azure Crystal Dome Window in facade
            const r = Math.min(drawW * 0.24, 42 * scale);
            const ox = drawX + drawW * 0.5;
            const oy = drawY + Math.min(drawH * 0.45, 76 * scale);
            const orbGrad = ctx.createRadialGradient(ox - 6 * scale, oy - 6 * scale, 4 * scale, ox, oy, r);
            orbGrad.addColorStop(0, '#e0f2fe');
            orbGrad.addColorStop(0.55, '#38bdf8');
            orbGrad.addColorStop(1, '#0369a1');
            ctx.fillStyle = orbGrad;
            ctx.beginPath();
            ctx.arc(ox, oy, r, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = '#fbbf24';
            ctx.lineWidth = 3 * scale;
            ctx.stroke();
        } else if (style === 'tower') {
            // Stacked tall azure lancet windows & gold filigree bands
            const floors = Math.max(2, Math.floor(box.h / 75));
            for (let f = 0; f < floors; f++) {
                const wy = drawY + 28 * scale + f * 66 * scale;
                if (wy + 34 * scale > drawY + drawH - 12 * scale) break;
                ctx.fillStyle = '#0ea5e9';
                ctx.beginPath();
                ctx.roundRect(drawX + drawW * 0.5 - 16 * scale, wy, 32 * scale, 36 * scale, [16 * scale, 16 * scale, 2 * scale, 2 * scale]);
                ctx.fill();
                ctx.strokeStyle = '#fbbf24';
                ctx.lineWidth = 2 * scale;
                ctx.stroke();
            }
        } else {
            // Classical Sky Temple golden emblem & sunlit columns
            const cx = drawX + drawW * 0.5;
            const cy = drawY + Math.min(64 * scale, drawH * 0.4);
            ctx.fillStyle = '#fbbf24';
            ctx.beginPath();
            ctx.arc(cx, cy, 16 * scale, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#38bdf8';
            ctx.beginPath();
            ctx.arc(cx, cy, 9 * scale, 0, Math.PI * 2);
            ctx.fill();
        }

        // Ledge-grab golden glow corner accents
        ctx.fillStyle = '#fef08a';
        ctx.beginPath();
        ctx.arc(drawX, drawY, 4.5 * scale, 0, Math.PI * 2);
        ctx.arc(drawX + drawW, drawY, 4.5 * scale, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
    }

    function drawSkyLadder(lad, scale) {
        const drawX = (lad.x - cameraX) * scale;
        const topY = (lad.topY - cameraY) * scale;
        const botY = (lad.bottomY - cameraY) * scale;
        const drawW = (lad.w || 42) * scale;
        const leftX = drawX - drawW * 0.5;
        const rightX = drawX + drawW * 0.5;

        ctx.save();
        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 4.5 * scale;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(leftX, topY);
        ctx.lineTo(leftX, botY);
        ctx.moveTo(rightX, topY);
        ctx.lineTo(rightX, botY);
        ctx.stroke();

        ctx.strokeStyle = '#fef08a';
        ctx.lineWidth = 3.2 * scale;
        for (let rY = lad.topY + 14; rY <= lad.bottomY - 8; rY += 22) {
            const sy = (rY - cameraY) * scale;
            ctx.beginPath();
            ctx.moveTo(leftX + 2 * scale, sy);
            ctx.lineTo(rightX - 2 * scale, sy);
            ctx.stroke();
        }
        ctx.restore();
    }

    function drawSkyTurnik(tur, scale) {
        const drawX = (tur.x - cameraX) * scale;
        const drawY = (tur.y - cameraY) * scale;
        const barLen = (tur.length || 95) * scale;

        ctx.save();
        // Floating cloud halo supporting the celestial golden bar
        ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.beginPath();
        ctx.arc(drawX - barLen * 0.5, drawY - 12 * scale, 14 * scale, 0, Math.PI * 2);
        ctx.arc(drawX + barLen * 0.5, drawY - 12 * scale, 14 * scale, 0, Math.PI * 2);
        ctx.fill();

        const barGrad = ctx.createLinearGradient(drawX - barLen * 0.5, drawY, drawX + barLen * 0.5, drawY);
        barGrad.addColorStop(0, '#f59e0b');
        barGrad.addColorStop(0.5, '#fef08a');
        barGrad.addColorStop(1, '#f59e0b');
        ctx.strokeStyle = barGrad;
        ctx.lineWidth = 6.5 * scale;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(drawX - barLen * 0.5, drawY);
        ctx.lineTo(drawX + barLen * 0.5, drawY);
        ctx.stroke();

        // Celestial cyan wing gems at bar tips
        ctx.fillStyle = '#38bdf8';
        ctx.beginPath();
        ctx.arc(drawX - barLen * 0.5, drawY, 5.5 * scale, 0, Math.PI * 2);
        ctx.arc(drawX + barLen * 0.5, drawY, 5.5 * scale, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
    }

    function drawSkyRope(rope, scale) {
        const anchorX = (rope.x - cameraX) * scale;
        const anchorY = (rope.anchorY - cameraY) * scale;
        const ropeLen = (rope.length || 185) * scale;
        let currentAngle = Math.sin(Date.now() * 0.002 + rope.x) * 0.05;
        if (player.state === 'ROPE' && player.activeRope && player.activeRope.id === rope.id) {
            currentAngle = player.ropeAngle;
        }
        const endX = anchorX + Math.sin(currentAngle) * ropeLen;
        const endY = anchorY + Math.cos(currentAngle) * ropeLen;

        ctx.save();
        // Floating fluffy cloud anchor overhead
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(anchorX, anchorY, 16 * scale, 0, Math.PI * 2);
        ctx.arc(anchorX - 14 * scale, anchorY + 3 * scale, 12 * scale, 0, Math.PI * 2);
        ctx.arc(anchorX + 14 * scale, anchorY + 3 * scale, 12 * scale, 0, Math.PI * 2);
        ctx.fill();

        // Radiant Golden Sky-Chain Rope
        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 4.5 * scale;
        ctx.beginPath();
        ctx.moveTo(anchorX, anchorY);
        ctx.lineTo(endX, endY);
        ctx.stroke();

        ctx.strokeStyle = '#fef08a';
        ctx.lineWidth = 2 * scale;
        ctx.setLineDash([5 * scale, 5 * scale]);
        ctx.beginPath();
        ctx.moveTo(anchorX, anchorY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
        ctx.setLineDash([]);

        // Glowing Sky-Orb Grip Knot
        ctx.fillStyle = '#38bdf8';
        ctx.strokeStyle = '#fef08a';
        ctx.lineWidth = 2.4 * scale;
        ctx.beginPath();
        ctx.arc(endX, endY, 9 * scale, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        ctx.restore();
    }

    // --- DRAW DAMAGING SKY HAZARD (ELECTRIC STORM CRYSTALS / THORNS) ---
    function drawSkyHazard(hz, scale) {
        const drawX = (hz.x - cameraX) * scale;
        const drawY = (hz.y - cameraY) * scale;
        const w = (hz.w || 40) * scale;
        const h = (hz.h || 52) * scale;
        if (drawX + w < -60 || drawX - w > canvas.width + 60) return;

        const pulse = 0.65 + 0.35 * Math.sin(Date.now() * 0.012 + hz.x);
        ctx.save();

        // Crackling storm danger aura
        const glow = ctx.createRadialGradient(drawX, drawY - h * 0.45, 3 * scale, drawX, drawY - h * 0.45, w * 0.85);
        glow.addColorStop(0, `rgba(250, 204, 21, ${0.45 * pulse})`);
        glow.addColorStop(0.6, `rgba(168, 85, 247, ${0.32 * pulse})`);
        glow.addColorStop(1, 'rgba(168, 85, 247, 0)');
        ctx.fillStyle = glow;
        ctx.beginPath();
        ctx.arc(drawX, drawY - h * 0.45, w * 0.85, 0, Math.PI * 2);
        ctx.fill();

        // 3 Jagged Dark-Storm Lightning Crystal Spires
        const shards = [
            { ox: -0.28, sh: 0.72, col: '#581c87' },
            { ox: 0.0, sh: 1.0, col: '#7e22ce' },
            { ox: 0.28, sh: 0.78, col: '#581c87' }
        ];
        shards.forEach(s => {
            const sx = drawX + s.ox * w;
            const topY = drawY - h * s.sh;
            ctx.fillStyle = s.col;
            ctx.strokeStyle = '#fde047';
            ctx.lineWidth = 1.6 * scale;
            ctx.beginPath();
            ctx.moveTo(sx - 7 * scale, drawY);
            ctx.lineTo(sx, topY);
            ctx.lineTo(sx + 7 * scale, drawY);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
        });

        // Flickering electric spark bolt across the tips
        if (Math.sin(Date.now() * 0.025 + hz.x) > 0.1) {
            ctx.strokeStyle = '#fef08a';
            ctx.lineWidth = 2 * scale;
            ctx.beginPath();
            ctx.moveTo(drawX - 11 * scale, drawY - h * 0.68);
            ctx.lineTo(drawX - 2 * scale, drawY - h * 0.82);
            ctx.lineTo(drawX + 4 * scale, drawY - h * 0.74);
            ctx.lineTo(drawX + 12 * scale, drawY - h * 0.88);
            ctx.stroke();
        }
        ctx.restore();
    }

    function drawSkyFlag(flag, scale) {
        const flagX = (flag.x - cameraX) * scale;
        const flagY = (flag.y - cameraY) * scale;
        const poleH = (flag.poleHeight || 118) * scale;
        const bannerW = (flag.bannerW || 48) * scale;
        const bannerH = (flag.bannerH || 34) * scale;

        ctx.save();
        ctx.strokeStyle = '#f59e0b';
        ctx.lineWidth = 5 * scale;
        ctx.beginPath();
        ctx.moveTo(flagX, flagY);
        ctx.lineTo(flagX, flagY - poleH);
        ctx.stroke();

        ctx.fillStyle = '#fef08a';
        ctx.beginPath();
        ctx.arc(flagX, flagY - poleH, 7.5 * scale, 0, Math.PI * 2);
        ctx.fill();

        const wave = Math.sin(Date.now() * 0.006) * 5 * scale;
        const topY = flagY - poleH + 8 * scale;
        const fGrad = ctx.createLinearGradient(flagX, topY, flagX + bannerW, topY);
        fGrad.addColorStop(0, '#0284c7');
        fGrad.addColorStop(0.5, '#38bdf8');
        fGrad.addColorStop(1, '#fef08a');

        ctx.fillStyle = fGrad;
        ctx.beginPath();
        ctx.moveTo(flagX, topY);
        ctx.quadraticCurveTo(flagX + bannerW * 0.5, topY + wave, flagX + bannerW, topY + wave / 2);
        ctx.lineTo(flagX + bannerW, topY + bannerH + wave / 2);
        ctx.quadraticCurveTo(flagX + bannerW * 0.5, topY + bannerH + wave, flagX, topY + bannerH);
        ctx.closePath();
        ctx.fill();

        ctx.fillStyle = '#ffffff';
        ctx.font = `bold ${16 * scale}px sans-serif`;
        ctx.fillText('☁️', flagX + 10 * scale, topY + bannerH * 0.72 + wave / 2);
        ctx.restore();
    }

    // =========================================================================
    // --- LEVEL 100: CRIMSON SAMURAI BOSS FIGHT & CINEMATIC DIALOGUE SYSTEM ---
