    btnNextLevel.addEventListener('click', () => {
        initAudio();
        victoryScreen.classList.remove('screen-active');
        victoryScreen.classList.add('hidden');

        const nextLevelNum = currentLevelIndex + 1;
        if (nextLevelNum > 100) {
            currentSelectPage = 6;
            generateLevelsGrid();
        } else if (nextLevelNum > 80) {
            currentSelectPage = 5;
            generateLevelsGrid();
        } else if (nextLevelNum > 60) {
            currentSelectPage = 4;
            generateLevelsGrid();
        } else if (nextLevelNum > 40) {
            currentSelectPage = 3;
            generateLevelsGrid();
        } else if (nextLevelNum > 20 && currentSelectPage === 1) {
            currentSelectPage = 2;
            generateLevelsGrid();
        }

        if (levelsData[nextLevelNum]) {
            startLevelWithFade(nextLevelNum);
        } else {
            triggerFadeTransition(() => {
                player.reset();
                hudOverlay.classList.add('hidden');
                levelSelectScreen.classList.remove('hidden');
                levelSelectScreen.classList.add('screen-active');
                currentState = STATES.LEVEL_SELECT;
            });
        }
    });

